window.BOOK={"key":"adab","app":"mutoon-adab","lsk":"mutoon_adab_v1","prefix":"ad_","title":"منظومة الآداب","sub":"الألفية في الآداب الشرعية · ابن عبد القوي المقدسي الحنبلي (ت ٦٩٩هـ) · ٩٤٧ بيتًا","poems":[{"id":"adab","title":"منظومة الآداب","nazim":"شمس الدين أبو عبد الله محمد بن عبد القوي المرداوي المقدسي الحنبلي","death":"ت ٦٩٩هـ","meter":"الطويل","source":"المكتبة الشاملة: الألفية في الآداب الشرعية (منظومة الآداب)، باعتناء محمد بن ناصر العجمي","srcUrl":"https://shamela.ws/book/54","note":"النص والشكل من طبعة العجمي (دار البشائر، ط٢ ١٤٢١هـ) المحققة على نسختي برنستون والظاهرية والمطبوعة، وقوبل آليًّا بما في «غذاء الألباب» للسفاريني و«موارد الظمآن» من أبياتها (نحو ربع المنظومة)، وأُكمل الشكل الناقص من «غذاء الألباب» في الأبيات المتطابقة لفظًا فقط. عناوين الفصول من وضع المحقق. والطبعة مشكولة نحو ٦٥٪، فأكمل الذكاء الاصطناعي باقي الحركات على الإعراب والوزن، وصُحّحت تصحيفات ظاهرة (مسجّلة في تقرير المصادر). فإذا شككت بحركة فراجع شيخك.","verses":[["بِحَمْدِكَ اللَّهُمَّ أُنْهِي وَأَبْتَدِي","فَحَمْدُكَ فَرْضٌ لَازِمٌ كُلَّ مُوجَدِ"],["تَعَالَيْتَ عَنْ نِدٍّ وَعَنْ وَلَدٍ وَعَنْ","شَرِيكٍ وَعَنْ مَا يَفْتَرِي كُلُّ مُلْحِدِ"],["نُقِرُّ بِلَا شَكٍّ بِأَنَّكَ وَاحِدٌ","وَنُؤْمِنُ بِالدَّاعِي إِلَيْكَ مُحَمَّدِ"],["رَسُولِكَ أَزْكَى مَنْ بَعَثْتَ إِلَى الْوَرَى","وَخَيْرِ مَنِ اسْتَخْرَجْتَ مِنْ خَيْرِ مَحْتِدِ"],["عَلَيْهِ صَلَاةُ اللَّهِ ثُمَّ سَلَامُهُ","صَلَاةً لَنَا تَقْضِي بِفَوْزٍ مُؤَبَّدِ"],["وَكُلِّ نَبِيٍّ لِلْأَنَامِ وَضُوعِفَتْ","لِأَشْرَفِ مَخْلُوقٍ بِأَشْرَفِ مَحْتِدِ"],["وَأَصْحَابِهِ وَالْغُرِّ مِنْ آلِ هَاشِمٍ","وَمَنْ بِهُدَاهُمْ فِي الْأَعَاصِيرِ يَهْتَدِي"],["وَأَشْهَدُ أَنَّ اللَّهَ لَا رَبَّ غَيْرُهُ","وَأَسْأَلُهُ عَفْوًا وَإِتْمَامَ مَا ابْتُدِي"],["وَخَاتِمَةً حُسْنَى تُنِيلُ الْفَتَى الرِّضَا","وَتُبْلِغُهُ فِي الْفَوْزِ أَشْرَفَ مَقْعَدِ"],["وَنَحْمَدُهُ حَمْدًا يَلِيقُ بِطَوْلِهِ","وَنَسْأَلُهُ الْإِخْلَاصَ فِي كُلِّ مَقْصَدِ"],["وَبَعْدُ فَإِنِّي سَوْفَ أَنْظِمُ جُمْلَةً","مِنَ الْأَدَبِ الْمَأْثُورِ عَنْ خَيْرِ مُرْشِدِ"],["مِنَ السُّنَّةِ الْغَرَّاءِ أَوْ مِنْ كِتَابِ مَنْ","تَقَدَّسَ عَنْ قَوْلِ الْغُوَاةِ وَجُحَّدِ"],["وَمِنْ قَوْلِ أَهْلِ الْفَضْلِ مِنْ عُلَمَائِنَا","أَئِمَّةِ أَهْلِ السِّلْمِ مِنْ كُلِّ أَمْجَدِ"],["لَعَلَّ إِلَهَ الْعَرْشِ يَنْفَعُنَا بِهَا","وَيُنْزِلُنَا فِي الْحَشْرِ فِي خَيْرِ مَقْعَدِ"],["أَلَا مَنْ لَهُ فِي الْعِلْمِ وَالدِّينِ رَغْبَةٌ","لِيُصْغِ بِقَلْبٍ حَاضِرٍ مُتَرَصِّدِ"],["وَيَقْبَلُ نُصْحًا مِنْ شَفِيقٍ عَلَى الْوَرَى","حَرِيصٍ عَلَى زَجْرِ الْأَنَامِ عَنِ الرَّدِ"],["فَعِنْدِيَ مِمَّا فِي الْحَدِيثِ أَمَانَةٌ","سَأَبْذُلُهَا جُهْدِي فَأَهْدِي وَأَهْتَدِي"],["فَخُذْهَا هَدَاكَ اللَّهُ لَا تُهْمِلَنَّهَا","فَفِيهَا مِنَ الْخَيْرَاتِ كُلُّ مُنَضَّدِ"],["أَقُولُ ابْتِدَاءً فِي الْقَرِيضِ وَنَظْمِهِ","فَكُنْ سَامِعًا نَظْمِي بِغَيْرِ تَفَنُّدِ"],["أَلَا كُلُّ مَنْ رَامَ السَّلَامَةَ فَلْيَصُنْ","جَوَارِحَهُ عَمَّا نَهَى اللَّهُ يَهْتَدِ"],["يَكُبُّ الْفَتَى فِي النَّارِ حَصْدُ لِسَانِهِ","فَحَافِظْ عَلَى ضَبْطِ اللِّسَانِ وَقَيِّدِ"],["فُضُولَ الْكَلَامِ ارْفُضْ فَلَا تَكُ مُكْثِرًا","كَلَامًا بِغَيْرِ الذِّكْرِ لِلَّهِ تَسْعَدِ"],["فَإِنَّ فُضُولًا لِلْكَلَامِ قَسَاوَةٌ","لِقَلْبِ الْفَتَى عَنْهُ الْخُشُوعُ بِمُبْعَدِ"],["فَتُرْدِي بِقَائِلِهَا إِلَى النَّارِ كِلْمَةٌ","وَإِرْسَالُ طَرْفِ الْمَرْءِ أَنْكَى فَقَيِّدِ"],["وَطَرْفُ الْفَتَى يَا صَاحِ رَائِدُ فَرْجِهِ","وَمُتْعِبُهُ فَاغْضُضْهُ مَا اسْطَعْتَ تَهْتَدِ"],["فَمَنْ مَدَّ طَرْفًا أَوْ زَنَا يَزْنِ أَهْلُهُ","فَعِفَّ يَعِفَّ قَالَهُ خَيْرُ مُرْشِدِ"],["فَمَنْ عَفَّ تَقْوَى عَنْ مَحَارِمِ غَيْرِهِ","يَصُنْ أَهْلَهُ حَقًّا وَإِنْ يَزْنِ يُفْسِدِ"],["فَلَوْ لَمْ يَكُنْ فِعْلُ الزِّنَاءِ كَبِيرَةً","وَلَمْ يَخْشَ مِنْ عُقْبَاهُ ذُو اللُّبِّ فِي غَدِ"],["لَكَانَ جَدِيرًا أَنْ يَصُونَ حَرِيمَهُ","بِهَجْرِ الزِّنَا خَوْفَ الْقِصَاصِ كَمَا ابْتُدِي"],["فَصِخْ وَصُنِ الْآرَابَ كُلٌّ لَهُ زِنًا","وَلَكِنْ زِنَا الْفَرْجِ الْكَبِيرَةُ فَاعْدُدِ"],["فَقَدْ قَرَنَ اللَّهُ الزِّنَا بِالدِّعَا الْفَتَى","مَعَ اللَّهِ رَبًّا فِي عَذَابٍ مُخَلَّدِ"],["وَأَدِّبْ وَعَزِّرْ آتِيًا لِبَهِيمَةٍ","وَمَنْ رَاوَدَ الْحَسْنَاءَ عَنْ نَفْسِهَا اعْضُدِ"],["إِذَا قَتَلَتْهُ بِانْتِفَاءِ ضَمَانِهِ","وَمَنْ يَرَ مَعْ زَوْجٍ فَتًى فَيُجَرِّدِ"],["لِقَتْلِهِمَا سَيْفًا فَيَقْتُلْهُمَا مَعًا","فَلَيْسَ عَلَيْهِ مِنْ قِصَاصٍ وَلَا يَدِ"],["فَإِنْ كَانَ هَذَا مِنْهُ دَعْوَى فَأَنْكَرَ الْـ","ـوَلِيُّ لِيَحْلِفْ وَالْقِصَاصَ فَأَكِّدِ"],["وَيَحْرُمُ رَأْيُ الْمُرْدِ مَعْ شَهْوَةٍ فَقَطْ","وَقِيلَ وَمَعْ خَوْفٍ وَلِلْكُرْهِ جَوِّدِ"],["فَإِيَّاكَ وَالْأَحْدَاثَ لَا تَقْرَبَنَّهُمْ","وَلَا تُرْسِلَنَّ الطَّرْفَ فِيهِمْ وَقَيِّدِ"],["وَإِرْسَالُ طَرْفٍ مِنْكَ لَا تَحْقِرَنَّهُ","فَفِي ضِمْنِهِ سَهْمٌ بِنَارٍ يُوَقَّدِ"],["وَيَحْرُمُ بُهْتٌ وَاغْتِيَابٌ نَمِيمَةٌ","وَإِفْشَاءُ سِرٍّ ثُمَّ لَعْنُ مُقَيَّدِ"],["وَفُحْشٌ وَمَكْرٌ وَالْبَذَا وَخَدِيعَةٌ","وَسُخْرِيَةٌ وَالْهُزْءُ وَالْكِذْبَ قَيِّدِ"],["لِغَيْرِ خِدَاعِ الْكَافِرِينَ بِحَرْبِهِمْ","وَلِلْعُرْسِ أَوِ اصْلَاحِ أَهْلِ التَّنَكُّدِ"],["وَأَوْجِبْ عَنِ الْمَحْظُورِ كَفَّ جَوَارِحٍ","وَنَدْبٌ عَنِ الْمَكْرُوهِ غَيْرَ مُشَدِّدِ"],["وَقَدْ قِيلَ صُغْرَى غِيبَةٌ وَنَمِيمَةٌ","وَكِلْتَاهُمَا كُبْرَى عَلَى نَصِّ أَحْمَدِ"],["وَأَمْرَكَ بِالْمَعْرُوفِ وَالنَّهْيَ يَا فَتَى","عَنِ الْمُنْكَرِ اجْعَلْ فَرْضَ عَيْنٍ تُسَدَّدِ"],["عَلَى عَالِمٍ بِالْحَظْرِ وَالْفِعْلِ لَمْ يَقُمْ","سِوَاهُ بِهِ مَعْ أَمْنِ عِدْوَانِ مُعْتَدِ"],["وَلَوْ كَانَ ذَا فِسْقٍ وَجَهْلٍ وَفِي سِوَى الَّـ","ـذِي قِيلَ فَرْضٌ بِالْكِفَايَةِ وَاحْدُدِ"],["وَبِالْعُلَمَا يَخْتَصُّ مَا اخْتُصَّ عِلْمُهُ","بِهِمْ وَبِمَنْ يَسْتَنْصِرُونَ بِهِ قَدِ"],["وَأَضْعَفُهُ بِالْقَلْبِ ثُمَّ لِسَانِهِ","وَأَقْوَاهُ إِنْكَارُ الْفَتَى الْجَلْدِ بِالْيَدِ"],["وَأَنْكِرْ عَلَى الصِّبْيَانِ كُلَّ مُحَرَّمٍ","بِتَأْدِيبِهِمْ وَالْعِلْمُ فِي الشَّرْعِ بِالرَّدِ"],["فَمَنْ ضَرَبَ الْأَوْلَادَ ضَرْبَ مُؤَدِّبٍ","وَزَوْجَتَهُ عِنْدَ النُّشُوزِ الْمُنَكِّدِ"],["وَضَرْبُ أَمِيرِ الْمُسْلِمِينَ رَعِيَّةً","لِتَأْدِيبِهِمْ بِالشَّرْعِ غَيْرَ مُشَدِّدِ"],["وَضَرْبُ وَلِيٍّ أَوْ مُعَلِّمِ صِبْيَةٍ","بِغَيْرِ اعْتِدَاءٍ لَا ضَمَانَ لِمَا ابْتُدِ"],["وَمَنْ سَلَّمَ ابْنًا كَيْ يُعَلَّمَ عَائِمًا","فَيَغْرَقَ لَمْ يَضْمَنْ كَتَسْلِيمِ أَرْشَدِ"],["لَهُ نَفْسَهُ كَيْ يَهْتَدِي لِسِبَاحَةٍ","فَيَغْرَقْ وَقِيلَ الِابْنُ يُودِي بِمُبْعَدِ"],["وَإِنْ أَمَرَ الْإِنْسَانُ غَيْرَ مُكَلَّفٍ","لِيَنْزِلَ بِئْرًا أَوْ يَقُولَ لَهُ اصْعَدِ"],["إِلَى نَخْلَةٍ فَاحْكُمْ بِتَضْمِينِ آمِرٍ","وَإِنْ كَانَ ذَا عَقْلٍ كَبِيرًا فَلَا يَدِي"],["وَإِنْ كَانَ ذُو السُّلْطَانِ آمِرَهُ بِهِ","فَوَجْهَيْنِ فِي تَضْمِينِهِ هَكَذَا طِدِ"],["وَيَضْمَنُ بِالتَّأْدِيبِ إِسْقَاطَ حَامِلٍ","وَمَنْ مِنْ دَوَا أَمْرَاضِهَا أَسْقَطَتْ قِدِ"],["وَإِنْ جَهَرَ الذِّمِّيُّ بِالْمُنْكَرَاتِ فِي الشَّـ","ـرِيعَةِ يُزْجَرْ دُونَ مُخْفٍ بِمَرْكَدِ"],["وَبِالْأَسْهَلِ ابْدَأْ ثُمَّ زِدْ قَدْرَ حَاجَةٍ","فَإِنْ لَمْ يَزُلْ بِالنَّافِذِ الْأَمْرِ فَاصْدُدِ"],["إِذَا لَمْ تَخَفْ فِي ذَلِكَ الْأَمْرِ حَيْفَهُ","إِذَا كَانَ ذَا الْإِنْكَارِ حَتْمَ التَّأَكُّدِ"],["وَلَا غُرْمَ فِي كَسْرِ الصَّلِيبِ وَلَا إِنَا","لُجَيْنٍ وَعَيْنٍ لِلذُّكُورِ وَخُرَّدِ"],["وَلَا غُرْمَ فِي دُفِّ الصَّنُوجِ كَسَرْتَهُ","وَلَا صُوَرٍ أَيْضًا وَلَا آلَةِ الدَّدِ"],["وَآلَةِ تَنْجِيمٍ وَسِحْرٍ وَنَحْوِهِ","وَكُتْبٍ حَوَتْ هَذَا وَأَشْبَاهِهِ اقْدُدِ"],["وَبَيْضٍ وَجَوْزٍ لِلْقِمَارِ بِقَدْرِ مَا","يُزِيلُ عَنِ الْمَنْكُورِ مَقْصَدَ مُفْسِدِ"],["وَشَقِّ ظُرُوفِ الْخَمْرِ وَالدَّنِّ مُطْلَقًا","وَإِنْ نَفَعَتْ فِي غَيْرِهِ فِي الْمُؤَطَّدِ"],["وَيَحْرُمُ مِزْمَارٌ وَشَبَّابَةٌ وَمَا","يُضَاهِيهِمَا مِنْ آلَةِ اللَّهْوِ وَالرَّدِ"],["وَلَوْ لَمْ يُقَارِنْهَا غِنَاءٌ جَمِيعَهَا","فَمِنْهَا ذَوُو الْأَوْتَارِ دُونَ تَقَيُّدِ"],["وَحَظْرُ الْغِنَاءِ الْأَكْثَرُونَ قَضَوْا بِهِ","وَعَنْ أَبَوَيْ بَكْرٍ إِمَامٍ وَمُقْتَدِ"],["إِبَاحَتُهُ لَا كُرْهُهُ وَأَبَاحَهُ الْـ","ـإِمَامُ أَبُو يَعْلَى مَعَ الْكُرْهِ فَانْشُدِ"],["فَمَنْ يَشْتَهِرْ فِيهِ وَيُكْثِرْ وَيَتَّخِذْ","لَهُ قَيْنَةً لَمْ يُعْتَبَرْ مَعَ شُهَّدِ"],["وَلَا بَأْسَ بِالشِّعْرِ الْمُبَاحِ وَحِفْظِهِ","وَصَنْعَتِهِ مَنْ ذَمَّ ذَلِكَ يَعْتَدِي"],["فَقَدْ سَمِعَ الْمُخْتَارُ شِعْرَ صِحَابِهِ","وَتَشْبِيبَهُمْ مِنْ غَيْرِ تَعْيِينِ خُرَّدِ"],["وَلَمْ يَكُ فِي عَصْرٍ لِذَلِكَ مُنْكِرٌ","فَكَيْفَ وَفِيهِ حِكْمَةٌ فَارْوِ وَانْشُدِ"],["وَحَظْرُ الْهِجَا وَالْمَدْحِ بِالزُّورِ وَالْخَنَا","وَتَشْبِيبِهِ بِالْأَجْنَبِيَّاتِ أَكِّدِ"],["وَوَصْفُ الزِّنَا وَالْخَمْرِ وَالْمُرْدِ وَالنِّسَا الْـ","ـقِيَانِ وَنَوْحٌ لِلتَّسَخُّطِ يُورَدِ"],["وَهِجْرَانُ مَنْ أَبْدَى الْمَعَاصِيَ سُنَّةٌ","وَقَدْ قِيلَ إِنْ يَرْدَعْهُ أَوْجِبْ وَأَكِّدِ"],["وَقِيلَ عَلَى الْإِطْلَاقِ مَا دَامَ مُعْلِنًا","وَلَاقِهْ بِوَجْهٍ مُكْفَهِرٍّ مُرَبَّدِ"],["وَيَحْرُمُ تَجْسِيسٌ عَلَى مُتَسَتِّرٍ","بِفِسْقٍ وَمَاضِي الْفِسْقِ إِذْ لَمْ يُجَدِّدِ"],["وَهِجْرَانُ مَنْ يَدْعُو لِأَمْرٍ مُضِلٍّ أَوْ","مُفَسِّقٍ احْتِمْهُ بِغَيْرِ تَرَدُّدِ"],["عَلَى غَيْرِ مَنْ يَقْوَى عَلَى دَحْضِ قَوْلِهِ","وَيَدْفَعُ إِضْرَارَ الْمُضِلِّ بِمِذْوَدِ"],["وَيَقْضِي أُمُورَ النَّاسِ فِي إِتْيَانِهِ","وَلَا هَجْرَ مَعْ تَسْلِيمِهِ الْمُتَعَوَّدِ"],["وَحَظْرَ انْتِفَا التَّسْلِيمِ فَوْقَ ثَلَاثَةٍ","عَلَى غَيْرِ مَنْ قُلْنَا بِهَجْرٍ فَأَكِّدِ"],["وَيُكْرَهُ لِلْمَرْءِ الْجُلُوسُ مَعَ امْرِئٍ","دَنِيٍّ وَمَعْ ذِي الْفِسْقِ أَوْ ذِي الرِّيَا الرَّدِ"],["كَذَا مَعْ سَخِيفٍ وَهْوَ مَنْ رَقَّ عَقْلُهُ","وَمَعْ لَاعِبِ الشِّطْرَنْجِ وَالنَّرْدِ وَالرَّدِ"],["وَمُتَّهَمٍ فِي دِينِهِ أَوْ بِعِرْضِهِ","بِهِ أَفْتَى ابْنُ حَمْدَانٍ فَتَابِعْهُ وَاقْتَدِ"],["وَكُنْ عَالِمًا أَنَّ السَّلَامَ لِسُنَّةٍ","وَرَدُّكَ فَرْضٌ لَيْسَ نَدْبًا بِأَوْطَدِ"],["وَيُجْزِئُ تَسْلِيمُ امْرِئٍ مِنْ جَمَاعَةٍ","وَرَدُّ فَتًى مِنْهُمْ عَنِ الْكُلِّ يَا عَدِي"],["وَتَسْلِيمُ نَزْرٍ وَالصَّغِيرِ وَعَابِرِ السَّـ","ـبِيلِ وَرُكْبَانٍ عَلَى الضِّدِّ أَيِّدِ"],["وَإِنْ سَلَّمَ الْمَأْمُورُ بِالرَّدِّ مِنْهُمُ","فَقَدْ حَصَلَ الْمَسْنُونُ إِذْ هُوَ مُبْتَدِ"],["وَسَلِّمْ إِذَا مَا قُمْتَ مِنْ حَضْرَةِ امْرِئٍ","وَسَلِّمْ إِذَا مَا جِئْتَ بَيْتَكَ تَقْتَدِي"],["وَإِفْشَاؤُكَ التَّسْلِيمَ يُوجِبُ مَحَبَّةً","مِنَ النَّاسِ مَجْهُولًا وَمَعْرُوفًا اقْصِدِ"],["وَتَعْرِيفُهُ لَفْظَ السَّلَامِ مُجَوَّزٌ","وَتَنْكِيرُهُ أَيْضًا عَلَى نَصِّ أَحْمَدِ"],["وَقَدْ قِيلَ يُكْرَهُ وَقِيلَ تَحِيَّةٌ","لِمَيِّتٍ وَالتَّوْدِيعَ عَرِّفْ كَمُرْدِدِ"],["وَسُنَّةٌ اسْتِئْذَانُهُ لِدُخُولِهِ","عَلَى غَيْرِهِ مِنْ أَقْرَبِينَ وَبُعَّدِ"],["ثَلَاثًا وَمَكْرُوهٌ دُخُولٌ لِهَاجِمٍ","وَلَا سِيَّمَا مِنْ سَفْرَةٍ وَتَبَعُّدِ"],["وَوَقْفَتُهُ تِلْقَاءَ بَابٍ وَكُوَّةٍ","فَإِنْ لَمْ يُجَبْ يَمْضِي وَإِنْ يَخْفَ يَزْدَدِ"],["وَتَحْرِيكُ نَعْلَيْهِ وَإِظْهَارُ حِسِّهِ","لِدَخْلَتِهِ حَتَّى لِمَنْزِلِهِ اشْهَدِ"],["وَإِنْ نَظَرَ الْإِنْسَانُ مِنْ شَقِّ بَابِهِ","بِلَا إِذْنِهِ إِنْ يَفْقَ عَيْنَيْهِ لَمْ يَدِ"],["وَسِيَّانِ مِنْ دَرْبٍ وَمِنْ مِلْكِ نَاظِرٍ","وَمِنْ كُوَّةٍ أَوْ مِنْ جِدَارٍ مُشَيَّدِ"],["وَلَوْ مَعَ إِمْكَانِ الدِّفَاعِ بِدُونِهِ","وَفَقْدِ النِّسَا أَوْ كَوْنِ مَحْرَمِ مُعْتَدِ"],["وَلَا تَحْذِفِ الْأَعْمَى وَقَالَ أَبُو الْوَفَا","بَلَى إِنْ يَكُنْ يَسْمَعْ لِيُحْذَفْ وَيُصْدَدِ"],["وَكُلُّ قِيَامٍ لَا لِوَالٍ وَعَالِمٍ","وَوَالِدِهِ أَوْ سَيِّدٍ كُرْهَهُ امْهَدِ"],["وَصَافِحْ لِمَنْ تَلْقَاهُ مِنْ كُلِّ مُسْلِمٍ","تَنَاثَرُ خَطَايَاكُمْ كَمَا فِي الْمُسَنَّدِ"],["وَلَيْسَ لِغَيْرِ اللَّهِ حَلَّ سُجُودُنَا","وَيُكْرَهُ تَقْبِيلُ الثَّرَى بِتَشَدُّدِ"],["وَيُكْرَهُ مِنْكَ الِانْحِنَاءُ مُسَلِّمًا","وَتَقْبِيلُ رَأْسِ الْمَرْءِ حَلَّ وَفِي الْيَدِ"],["وَحَلَّ عِنَاقٌ لِلْمُلَاقِي تَدَيُّنًا","وَيُكْرَهُ تَقْبِيلُ الْفَمِ افْهَمْ وَقَيِّدِ"],["وَنَزْعُ يَدٍ مِمَّنْ يُصَافِحُ عَاجِلًا","وَأَنْ يَتَنَاجَى الْجَمْعُ مَا دُونَ مُفْرَدِ"],["وَأَنْ يَجْلِسَ الْإِنْسَانُ عِنْدَ مُحَدِّثٍ","بِسِرٍّ وَقِيلَ احْظُرْ وَإِنْ يَأْذَنِ اقْعُدِ"],["وَمَرْأَى عَجُوزٍ لَمْ تُرَدْ وَصِفَاحُهَا","وَخَلْوَتَهَا اكْرَهْ لَا تَحِيَّتَهَا اشْهَدِ"],["وَتَشْمِيتُهَا وَاكْرَهْ كِلَا الْخَصْلَتَيْنِ لِلـ","ـشَّبَابِ مِنَ الصِّنْفَيْنِ بُعْدَى وَأَبْعَدِ"],["وَيُكْرَهُ تَسْلِيمٌ عَلَى مُتَشَاغِلٍ","بِذِكْرٍ وَقُرْآنٍ وَقَوْلِ مُحَمَّدِ"],["خَطِيبٍ وَذِي دَرْسٍ وَمَنْ يَبْحَثُونَ فِي الْـ","ـعُلُومِ وَذِي وَعْظٍ لِنَفْعِ الْمُوَحِّدِ"],["مُكَرِّرِ فِقْهٍ وَالْمُؤَذِّنِ بَعْدَهُ الْـ","ـمُصَلِّي وَذِي طُهْرٍ لِفِعْلِ تَعَبُّدِ"],["وَدَعْ آكِلًا مَعْ ذِي التَّغَوُّطِ ثُمَّ مَنْ","يُقَاتِلُ لِلْأَعْدَاءِ فِي حَرْبِ جُحَّدِ"],["وَكُنْ وَاصِلَ الْأَرْحَامِ حَتَّى لِكَاشِحٍ","تُوَفَّرُ فِي عُمْرٍ وَرِزْقٍ وَتَسْعَدِ"],["وَلَا تَقْطَعِ الْأَرْحَامَ إِنَّ قَطِيعَةً","لِذِي رَحِمٍ كُبْرَى مِنَ اللَّهِ تُبْعَدِ"],["فَلَا تَغْشَ قَوْمًا رَحْمَةُ اللَّهِ فِيهِمُ","ثَوَى قَاطِعٌ قَدْ جَاءَ ذَا بِتَوَعُّدِ"],["وَيَحْسُنُ تَحْسِينٌ لِخُلْقٍ وَصُحْبَةٍ","وَلَا سِيَّمَا لِلْوَالِدِ الْمُتَأَكِّدِ"],["وَلَوْ كَانَ ذَا كُفْرٍ وَأَوْجَبَ طَوْعَهُ","سِوَى فِي حَرَامٍ أَوْ لِأَمْرٍ مُؤَكَّدِ"],["كَتِطْلَابِ عِلْمٍ لَا يَضُرُّهُمَا بِهِ","وَتَطْلِيقِ زَوْجَاتٍ بِرَأْيٍ مُجَرَّدِ"],["وَأَحْسِنْ إِلَى أَصْحَابِهِ بَعْدَ مَوْتِهِ","وَنَفِّذْ وَصَايَا مِنْهُ فِي حُسْنِ مَعْهَدِ"],["وَأَكْرِمْهُ بِاسْتِغْفَارِكَ انْ كُنْتَ بَارِرًا","فَهَذَا بَقَايَا بِرِّهِ الْمُتَعَوِّدِ"],["وَوَاجِبٌ التَّعْدِيلُ بَيْنَ بَنِيهِ فِي الْـ","ـعَطِيَّةِ كَالْمِيرَاثِ مِنْ كُلِّ مُحْتَدِ"],["وَأُمٌّ مَعَ الْأَوْلَادِ مِثْلُ أَبِيهِمُ","عَلَيْهَا احْتِمِ التَّعْدِيلَ فِي الْقَسْمِ تُرْشَدِ"],["وَمَا الْأَبُ فِي تَخْصِيصِهِ بَعْضَ وُلْدِهِ","لِقَصْدٍ صَحِيحٍ آثِمًا بَلْ لِيُحْمَدِ"],["وَلَيْسَ مُبَاحًا عَوْدُ مُهْدٍ هَدِيَّةً","وَإِنْ لَمْ يُثَبْ أَوْ وَاهِبٍ مُتَجَرِّدِ"],["سِوَى الْأَبِ فِي الْأَوْلَى وَجَدٍّ بِأَبْعَدٍ","وَأُمٍّ بِوَجْهٍ خَرَّجُوهُ مُجَوَّدِ"],["وَلَا تَتَّبِعْ عِلْمَ النُّجُومِ سِوَى الَّذِي","إِلَى جِهَةٍ يَهْدِي وَوَقْتِ تَعَبُّدِ"],["فَغَايَتُهُ عِلْمُ الْكُسُوفِ وَمَا بِهِ انْـ","ـتِفَاعٌ لِذِي لُبٍّ وَلَا حُسْنُ مَقْصَدِ"],["وَلَيْسَ كُسُوفُ النَّيِّرَيْنِ بِمُوجِبٍ","لِأَمْرٍ سِوَى تَخْوِيفِنَا وَالتَّهَدُّدِ"],["فَلَا تَسْمَعِ التَّهْوِيلَ مِنْ كُلِّ مُفْتَرٍ","وَكَذِّبْ بِأَحْكَامِ الْمُنَجِّمِ وَارْدُدِ"],["وَصَلِّ صَلَاةً لِلْكُسُوفِ فَإِنَّهَا","لَأَثْبَتُ مَا يَرْوِي لَنَا كُلُّ مُسْنِدِ"],["وَمَنْ تَبْدُ مِنْهُ سَحْرَةٌ كَرُكُوبِهِ الْـ","ـجَمَادَ فَتَسْرِي تَحْتَهُ كَعَمَرَّدِ"],["وَدَعْوَى اجْتِمَاعِ الْجِنِّ طَاعَةً لَهُ","بِتَعْزِيمِهِ أَنَّى يَشَأْ طَوْعَ مُسْعَدِ"],["وَأَنَّ الدَّرَارِي فِي السَّمَاءِ بِزَعْمِهِ","تُخَاطِبُهُ يَكْفُرْ وَبِالسَّيْفِ فَاقْدُدِ"],["وَوَجْهَيْنِ إِنْ لَمْ يَبْدُ مِنْ فِعْلِهِ سِوَى","مُجَرَّدِ دَعْوَى فِعْلِ ذَلِكَ أَسْنِدِ"],["وَسَاحِرُ أَهْلِ الذِّمَّةِ ابْقِ بِأَجْوَدِ","لِإِبْقَاءٍ ابْنَ الْأَعْصَمِ الْمُتَمَرِّدِ"],["وَذُو السِّحْرِ بِالتَّدْخِينِ أَوْ بِالدَّوَاءِ أَوْ","بِسَقْيٍ إِذَا لَمْ يَرْتَدِدْ عَزِّرَنْ قِدِ"],["وَيُقْتَصُّ مِنْهُ إِنْ أَتَى مُوجِبًا لَهُ","وَإِنْ لَمْ يَتُبْ فَاحْبِسْهُ حَبْسَ مُصَدِّدِ"],["وَعَنْهُ كَعَرَّافٍ لِيُحْبَسْ وَكَاهِنٍ","ذَوَا السِّحْرِ بِالْإِطْلَاقِ غَيْرَ مُقَيَّدِ"],["وَحُكْمُ ذَوِي التَّعْزِيمِ أَحْكَامُ سَاحِرٍ","وَقَدْ قِيلَ فِيمَا فِيهِ نَفْعُ الْمُوَحِّدِ"],["كَحَلٍّ وَتَعْزِيمٍ يُسَامَحُ فِيهِمَا","فَمَا النَّهْيُ إِلَّا عَنْ مُضِرٍّ وَمُفْسِدِ"],["وَشَرْطُ الَّذِي مِنْ ذَلِكُمْ فِيهِ رَخَّصُوا","إِذَا كَانَ بِالْقَوْلِ الْمُبَاحِ الْمُعَوَّدِ"],["وَتُكْرَهُ فِي الْحَمَّامِ كُلُّ قِرَاءَةٍ","وَذِكْرُ لِسَانٍ وَالسَّلَامُ لِمُبْتَدِي"],["وَأُجْرَةُ حَمَّامٍ حَلَالٌ كَرِيهَةٌ","كَأَثْمَانِهِ وَالْعَقْدُ غَيْرُ مُفَسَّدِ"],["وَرَفْعُكَ صَوْتًا بِالدُّعَاءِ أَوْ مَعَ الْـ","ـجَنَازَةِ أَوْ فِي الْحَرْبِ حِينَ التَّشَدُّدِ"],["وَنَقْطٌ وَشَكْلٌ فِي مَقَالٍ لِمُصْحَفٍ","وَلَا تَكْتُبَنْ فِيهِ سِوَاهُ وَجَرِّدِ"],["وَحَرِّمْ وَعَنْهُ اكْرَهْ إِجَارَةَ مُصْحَفٍ","كَبَيْعٍ وَفِي الْإِبْدَالِ وَجْهَيْنِ أَسْنِدِ"],["وَحَظْرٌ بِلَا خُلْفٍ سِفَارٌ بِمُصْحَفٍ","لِدَارِ حُرُوبٍ مِثْلَ تَمْلِيكِ مُلْحِدِ"],["وَحَرِّمْ عَلَيْهِ الِاتِّكَاءَ عَلَى الَّذِي","بِهِ مِنْهُ مَعْ كُتْبِ الْحَدِيثِ وَشَدِّدِ"],["وَجَائِزٌ إِيجَارٌ لِنَسْخِ الْقُرَانِ وَالْـ","ـحَدِيثِ وَكُتْبِ الْفِقْهِ وَالشِّعْرِ لَا الرَّدِ"],["بِمُدَّةِ أَوْ تَقْدِيرِ أَوْرَاقِهِ مَعَ السُّـ","ـطُورِ وَوَصْفِ الْخَطِّ وَالْهَامِشِ احْدُدِ"],["وَغِبًّا تَدَهَّنْ وَاكْتَحِلْ مُوتِرًا تُصِبْ","عَلَى كُلِّ عَيْنٍ فِي الْقَوِيِّ بِإِثْمِدِ"],["وَغَيِّرْ بِغَيْرِ الْأَسْوَدِ الشَّيْبَ وَابْقِهِ","وَلَا تَنْتِفَنْهُ فَهْوَ نُورُ الْمُوَحِّدِ"],["وَذَاكَ نَذِيرُ الْمَرْءِ يَنْعِي ارْتِحَالَهُ","وَلِلْقَزَعِ اكْرَهْ ثُمَّ تَدْلِيسَ نُهَّدِ"],["لِلَعْنٍ عَلَيْهِ احْظُرْ كَوَشْمٍ وَوَشْرِهَا","وَنَمْصٍ وَوَصْلِ الشَّعْرِ بِالشَّعْرِ قَيِّدِ"],["وَحَفُّ الرِّجَالِ الْوَجْهَ يُكْرَهُ مُطْلَقًا","وَحَلْقُ الْقَفَا أَيْضًا عَلَى النَّاسِ فَاشْهَدِ"],["وَإِعْفَا اللِّحَا نَدْبٌ وَقِيلَ خُذَنَّ مَا","يَلِي الْحَلْقَ مَعْ مَا زَادَ عَنْ قَبْضَةِ الْيَدِ"],["وَجَزٌّ وَقِيلَ الْخَيْرُ حَفُّ شَوَارِبٍ","خِلَافَ مَجُوسٍ مَعْ رَوَافِضِ مُرَّدِ"],["وَكُنْ عَالِمًا أَنَّ الْخِتَانَ لِوَاجِبٍ","مَعَ الْأَمْنِ فِي الْأَقْوَى وَحَتْمُ التَّعَبُّدِ"],["وَيُشْرَعُ أَنْ لَا يَبْلُغَ الْعَشْرَ أَقْلَفًا","وَيُكْرَهُ فِي الْأُسْبُوعِ فِعْلَ التَّهَوُّدِ"],["وَلَا تَخْتِنَنَّ الْمَيْتَ مِنْ غَيْرِ مِرْيَةٍ","وَشَارِبَهُ وَالْإِبْطَ وَالظُّفْرَ فَاجْدُدِ"],["وَيُشْرَعُ إِيكَاءُ السِّقَا وَغَطَا الْإِنَا","وَإِيجَافُ أَبْوَابٍ وَطَفْوُ الْمُؤَقَّدِ"],["وَتَقْلِيمُ أَظْفَارٍ وَنَتْفٌ لِإِبْطِهِ","وَحَلْقًا أَوِ التَّنْوِيرَ لِلْعَانَةِ اقْصِدِ"],["وَيُكْرَهُ بَعْدَ الْأَرْبَعِينَ بَقَاؤُهُ","وَدَفْنُكَ كُلًّا سُنَّةٌ فَارْوِ وَاقْتَدِ"],["وَنَدْبٌ بِبَادِي الرِّيحِ طِيبُ ذُكُورِنَا","وَظَاهِرُ كَوْنٍ حَسْبُ طِيبٍ لِخُرَّدِ"],["وَيَحْسُنُ خَفْضُ الصَّوْتِ مِنْ عَاطِسٍ وَأَنْ","يُغَطِّيَ وَجْهًا لِاسْتِتَارٍ مِنَ الرَّدِي"],["وَيَحْمَدُ جَهْرًا وَلْيُشَمِّتْهُ سَامِعٌ","لِتَحْمِيدِهِ وَلْيُبْدِ رَدَّ الْمُعَوِّدِ"],["وَقُلْ لِلْفَتَى عُوفِيتَ بَعْدَ ثَلَاثَةٍ","وَلِلطِّفْلِ بُورِكَ فِيكَ وَأْمُرْهُ يَحْمَدِ"],["وَغَطِّ فَمًا وَاكْظِمْ تُصِبْ فِي تَثَاؤُبٍ","فَذَلِكَ مَسْنُونٌ بِأَمْرِ الْمُرَشِّدِ"],["وَمَكْرُوهٌ اسْتِئْمَانُنَا أَهْلَ ذِمَّةٍ","لِإِحْرَازِ مَالٍ أَوْ لِقِسْمَتِهِ اشْهَدِ"],["وَمَكْرُوهٌ اسْتِطْبَابُهُمْ لَا ضَرُورَةً","وَمَا رَكَّبُوهُ مِنْ دَوَاءٍ مُؤَصَّدِ"],["وَيَحْرُمُ تَصْدِيرُ الْكَفُورِ بِمَجْلِسٍ","وَفِي سُبُلٍ فَاضْطَرَّ لِلضِّيقِ وَاضْهَدِ"],["وَقُلْ وَعَلَيْكُمْ إِنْ يُسَلِّمْ بَعْضُهُمْ","مُجِيبًا وُجُوبًا لَا تُجِزْهُ لِمُبْتَدِ"],["وَلَا تَسْأَلَنْ عَنْ حُكْمِ أَطْفَالِهِمْ وَإِنْ","سُئِلْتَ فَقُلِ أَللَّهُ أَعْلَمُ بِمُفْسِدِ"],["وَلَا بَأْسَ شَرْعًا أَنْ يَطِبَّكَ مُسْلِمٌ","وَتَشْكُو الَّذِي تَلْقَا وَبِالْحَمْدِ فَابْتَدِ"],["وَتَرْكُ الدَّوَا أَوْلَى وَفِعْلُكَ جَائِزٌ","بِمَا لَمْ تَيَقَّنْ فِيهِ حُرْمَةُ مُفْرَدِ"],["فَفِي السُّقْمِ وَالْآفَاتِ أَعْظَمُ حِكْمَةٍ","مُيَقِّظَةٍ ذَا اللُّبِّ عِنْدَ التَّفَقُّدِ"],["يُنَادِي لِسَانُ الْحَالِ جِدُّوا لِتَرْحَلُوا","عَنِ الْمَنْزِلِ الْغَثِّ الْكَثِيرِ التَّنَكُّدِ"],["أَتَاكَ نَذِيرُ الشَّيْبِ بِالسُّقْمِ مُخْبِرًا","بِأَنَّكَ تَتْلُو الْقَوْمَ فِي الْيَوْمِ أَوْ غَدِ"],["فَخُذْ أُهْبَةً فِي الزَّادِ فَالْمَوْتُ كَائِنٌ","فَمَا مِنْهُ مَنْجَا وَلَا عَنْهُ عَنْدَدِ"],["فَمَا دَارُكُمْ هَذِي بِدَارِ إِقَامَةٍ","وَلَكِنَّهَا دَارُ ابْتِلَا وَتَزَوُّدِ"],["أَمَا جَاءَكُمْ عَنْ رَبِّكُمْ ﴿وَتَزَوَّدُوا﴾","فَمَا عُذْرُ مَنْ وَافَاهُ غَيْرَ مُزَوَّدِ"],["فَمَا هَذِهِ الْأَيَّامُ إِلَّا مَرَاحِلٌ","تُقَرِّبُ مِنْ دَارِ اللِّقَا كُلَّ مُبْعَدِ"],["وَمَنْ سَارَ نَحْوَ الدَّارِ سِتِّينَ حِجَّةً","فَقَدْ حَانَ مِنْهُ الْمُلْتَقَى وَكَأَنْ قَدِ"],["فَمَا النَّاسُ إِلَّا مِثْلُ سُفْرٍ تَتَابَعُوا","مُقِيمٌ لِتَهْوِيمٍ عَلَى إِثْرِ مُغْتَدِ"],["وَمَنْ كَانَ عِزْرَائِيلُ كَافِلَ رُوحِهِ","إِذَا فَاتَهُ فِي الْيَوْمِ لَمْ يَنْجُ فِي غَدِ"],["وَمَنْ رُوحُهُ فِي الْجِسْمِ مِنْهُ وَدِيعَةٌ","فَهَيْهَاتَ أَمْنٌ يُرْتَجَى مِنْ مُرَدَّدِ"],["فَمَا حَقُّ ذِي لُبٍّ يَبِيتُ بِلَيْلَةٍ","بِلَا كَتْبِ إِيصَاءٍ وَإِشْهَادِ شُهَّدِ"],["وَوَاجِبٌ الْإِيصَا عَلَى الْمَرْءِ إِنْ يَكُنْ","عَلَيْهِ حُقُوقٌ وَاجِبَاتُ التَّرَدُّدِ"],["وَمَنْ يُوصِ فِي إِثْمٍ كَإِحْدَاثِ بِيعَةٍ","وَكَتْبٍ لِتَوْرَاةٍ وَالِانْجِيلِ يُرْدَدِ"],["وَشَارِبِ خَمْرٍ أَوْ مُغَنٍّ وَنَحْوِ ذَا","مِنَ الْعَوْنِ فِي فِعْلِ الْمَعَاصِي لِمُعْتَدِي"],["وَسِيَّانِ إِيصَاءُ التَّقِيِّ وَفَاجِرٍ","بِهَذَا وَإِيصَا ذِمَّةٍ وَمُوَحِّدِ"],["وَلَا بَأْسَ أَنْ يَخْبَا الْفَتَى كَفَنًا لَهُ","لِحِلٍّ وَآثَارِ الرِّضَى وَالتَّعَبُّدِ"],["فَبَادِرْ هُجُومَ الْمَوْتِ فِي كَسْبِ مَا بِهِ","تَفُوزُ بِهِ يَوْمَ الْقِيَامَةِ وَاجْهَدِ"],["فَكَمْ غَبْنَ مَغْبُونٍ بِنِعْمَةِ صِحَّةٍ","وَنِعْمَةِ إِمْكَانِ اكْتِسَابِ التَّعَبُّدِ"],["فَنَفْسَكَ فَاجْعَلْهَا وَصِيَّكَ مُكْثِرًا","لِسَفْرَةِ يَوْمِ الْحَشْرِ طِيبَ التَّزَوُّدِ"],["وَمَثِّلْ وُرُودَ الْقَبْرِ مَهْمَا رَأَيْتَهُ","لِنَفْسِكَ نَفَّاعًا فَقَدِّمْهُ تَسْعَدِ"],["فَمَا نَفَعَ الْإِنْسَانَ مِثْلُ اكْتِسَابِهِ","بِيَوْمٍ يَفِرُّ الْمَرْءُ مِنْ كُلِّ مَحْتِدِ"],["كَفَى زَاجِرًا لِلْمَرْءِ مَوْتٌ مُحَتَّمٌ","وَقَبْرٌ وَأَهْوَالٌ تُشَاهَدُ فِي غَدِ"],["وَنَارًا تَلَظَّى أَوْعَدَ اللَّهُ مَنْ عَصَى","فَمِنْ خَارِجٍ بَعْدَ الشَّقَا وَمُخَلَّدِ"],["وَيُسْأَلُ فِي الْقَبْرِ الْفَتَى عَنْ نَبِيِّهِ","وَعَنْ رَبِّهِ وَالدِّينِ فِعْلَ مُهَدَّدِ"],["فَمَنْ ثَبَّتَ اللَّهُ اسْتَجَابَ مُوَحِّدًا","وَمَنْ لَمْ يُثَبِّتْ فَهْوَ غَيْرُ مُوَحِّدِ"],["وَتِلْكَ لَعَمْرِي آخِرُ الْفِتَنِ الَّتِي","مَتَى تَنْجُ مِنْهَا فُزْتَ فَوْزَ مُخَلَّدِ"],["فَنَسْأَلُهُ التَّثْبِيتَ دُنْيَا وَآخِرَا","وَخَاتِمَةً تَقْضِي بِفَوْزٍ مُؤَبَّدِ"],["وَيُكْرَهُ تَأْذِينٌ لِنَعْيٍ مُعَمَّمًا","أَلَا مَاتَ زَيْدٌ لَا لِأَهْلِ التَّوَدُّدِ"],["وَنَدْبٌ جُلُوسُ الْمُؤْنِسِينَ حِذَاءَهُ","كَنَحْرِ جَزُورٍ بَيْنَ بَاكٍ وَمُسْعَدِ"],["وَيُقْطَعُ نَبَّاشُ الْقُبُورِ بِأَخْذِهِ","عَنِ الْمَيِّتِ الْأَكْفَانَ مِنْ حِرْزِ مُلْحَدِ"],["وَإِيَّاكَ وَالْمَالَ الْحَرَامَ مُوَرِّثًا","تَبُوءُ بِخُسْرَانٍ مُبِينٍ وَتَكْمَدِ"],["فَتَشْقَى بِهِ جَمْعًا وَتَصْلَى بِهِ لَظَى","وَغَيْرُكَ يُهْنَاهُ وَيَسْعَدُ فِي غَدِ"],["وَبَادِرْ بِإِخْرَاجِ الْمَظَالِمِ طَائِعًا","وَفَتِّشْ عَلَى عَصْرِ الصِّبَا وَتَفَقَّدِ"],["فَيَا لَكَ أَشْقَى النَّاسِ مِنْ مُتَكَلِّفٍ","لِغَيْرِكَ جَمَّاعًا إِذَا لَمْ تَزَوَّدِ"],["وَرَجِّحْ عَلَى الْخَوْفِ الرَّجَا عِنْدَ يَأْسِهِ","وَلَاقِ بِحُسْنِ الظَّنِّ رَبَّكَ تَسْعَدِ"],["وَيُشْرَعُ لِلْمَرْضَى الْعِيَادَةُ فَأْتِهِمْ","تَخُضْ رَحْمَةً تَغْمُرْ مَجَالِسَ عُوَّدِ"],["فَسَبْعُونَ أَلْفًا مِنْ مَلَائِكَةِ الرِّضَى","تُصَلِّي عَلَى مَنْ عَادَ مَرْضَى إِلَى الْغَدِ"],["وَإِنْ عَادَهُ فِي أَوَّلِ الْيَوْمِ وَاصَلَتْ","عَلَيْهِ إِلَى اللَّيْلِ الصَّلَاةَ فَأَسْنِدِ"],["فَمِنْهُمْ مُغِبًّا عُدْ وَخَفِّفْ وَمِنْهُمُ الَّـ","ـذِي يُؤْثِرُ التَّطْوِيلَ مِنْ مُتَوَدِّدِ"],["فَفَكِّرْ وَرَاعِ فِي الْعِيَادَةِ حَالَ مَنْ","تَعُودُ وَلَا تُكْثِرْ سُؤَالًا تُنَكِّدِ"],["وَذَكِّرْ لِمَنْ تَأْتِي بِتَوْبَةِ مُخْلِصٍ","وَلَقِّنْهُ عِنْدَ الْمَوْتِ قَوْلَ الْمُوَحِّدِ"],["وَ«يس» إِنْ تُتْلَى يُخَفَّفُ مَوْتُهُ","وَيُرْفَعُ عَنْهُ الْإِصْرُ عِنْدَ التَّلَحُّدِ"],["وَوَفِّ دُيُونَ الْمَيْتِ شَرْعًا وَفَرِّقَنْ","وَصِيَّةَ عَدْلٍ ثُمَّ تَجْهِيزَهُ اقْصِدِ"],["وَيُخْتَارُ لِلْغُسْلِ الْأَمِينُ وَعَالِمٌ","بِأَحْكَامِ تَغْسِيلٍ وَلَوْ بِتَقَلُّدِ"],["وَلَا تُفْشِ سِرًّا يُؤْثِرُ الْمَيْتُ كَتْمَهُ","سِوَى ذِي فُجُورٍ وَابْتِدَاعٍ مُعَوَّدِ"],["وَفَاضِلُ مَا يُجْبَى لِمَيْتٍ لِرَبِّهِ","وَإِنْ جُهِلُوا فَاصْرِفْ لِآخَرَ تَهْتَدِ"],["وَلَا تَمْنَعَنْ مِنْ رُؤْيَةِ الْمَيْتِ أَهْلَهُ","وَتَقْبِيلُهُ فِعْلُ الْمُحِبِّ الْمُجَوَّدِ"],["وَتَعْزِيَةُ الْمَرْءِ الْمُصَابِ فَضِيلَةٌ","يَدُلُّ عَلَيْهِ بِالْحَدِيثِ الْمُؤَيَّدِ"],["وَكُلُّ بُكَاءٍ لَيْسَ مَعْهُ نِيَاحَةٌ","وَلَا نَدَبَ الْآتِي بِهِ غَيْرَ مُعْتَدِ"],["وَيَحْرُمُ شَقُّ الْجَيْبِ وَاللَّطْمُ بَعْدَهُ الـ","ـنِّيَاحَةُ مَعْ نَدْبٍ وَأَشْبَاهِهَا اعْدُدِ"],["وَيُشْرَعُ لِلذُّكْرَانِ زَوْرُ مَقَابِرٍ","وَيُكْرَهُ فِي أَوْلَى الْمَقَالِ لِنُهَّدِ"],["وَيُهْدِي إِلَيْهِمْ مَا تَيَسَّرَ فِعْلُهُ","مِنَ الْبِرِّ وَالْقُرْآنِ يَنْفَعُ مَنْ هُدِي"],["وَمَا قَدْ رُوِيَ عِنْدَ الْمَزُورِ بِقَوْلِهِ","فَكَمْ مُرْسَلٍ قَدْ جَاءَ فِيهِ وَمُسْنَدِ"],["وَيُكْرَهُ تَطْيِيبُ الْقُبُورِ وَسَرْجُهَا","وَعَنْ لَثْمِهَا وَالْأَخْذِ مِنْ تُرْبِهَا ذِدِ"],["وَمَا النَّاسُ إِلَّا مَيِّتٌ وَمُؤَخَّرٌ","فَعِلْمُ الَّذِي قَدْ مَاتَ نِصْفٌ لَهُ اقْصِدِ"],["فَبَادِرْ إِلَى عِلْمِ الْفَرَائِضِ إِنَّهُ","لَأَوَّلُ عِلْمٍ دَارِسٍ وَمُفْقَدِ"],["فَفِي نَصْبِ أَحْكَامِ التَّوَارُثِ حِكْمَةٌ","تَدُلُّ عَلَى الْأَحْكَامِ كُلَّ مُرَشَّدِ"],["وَإِنْ مَرِضَتْ أُنْثَى وَلَمْ يَجِدُوا لَهَا","طَبِيبًا سِوَى رَجُلٍ أَجِزْهُ وَمَهِّدِ"],["وَمَا كَانَ فِيهِ الدَّاءُ مِنْ كُلِّ جِسْمِهَا","فَبِالنَّظَرِ احْكُمْ لِلطَّبِيبِ الْمُجَوِّدِ"],["وَيَنْظُرُ وَجْهَ الْخُودِ وَالْكَفَّ عَبْدُهَا","وَمَنْ لَمْ يَكُنْ ذَا إِرْبَةٍ فِي الْمُؤَكَّدِ"],["بِدَاءٍ وَتَخْنِيثٍ وَشَيْخُوخَةٍ فَقِسْ","وَلَيْسَ مِنَ الطِّفْلِ اسْتِتَارٌ لِخُرَّدِ"],["وَطِفْلَتُنَا بَيْنَ الرِّجَالِ كَطِفْلِنَا","مَعَ النِّسْوَةِ افْهَمْ مَا أَقُولُ وَأَرْشِدِ"],["وَإِنْ طِفْلَةٌ أَضْحَتْ مُمَيِّزَةً فَكَالْـ","ـمُمَيِّزِ فِيهَا الْحُكْمُ لِلْمُتَفَقِّدِ"],["وَمَا كَانَ يَبْدُو مِنْ عَجَائِزِ النِّسَا","فَمَنْ يَنْظُرْهُ لَيْسَ بِمُبْعَدِ"],["كَذَا الْحُكْمُ فِي الشَّوْهَا وَوَجْهِ أَجَانِبٍ","وَكَفًّا لِيَنْظُرَ آمِنًا فِي مُبَعَّدِ"],["وَكُلٌّ لَهُ مِنْ جِنْسِهِ نَظَرٌ إِلَى","سِوَى الْعَوْرَةِ الْفَحْشَاءِ ذَاتِ التَّزَيُّدِ"],["كَذَلِكَ فِي ذِمِّيَّةٍ مَعَ حُرَّةٍ","مَعَ الْمُسْلِمَاتِ انْقُلْهُمَا نَقْلَ أَقْصَدِ"],["وَهَلْ يَنْظُرُ النِّسْوَانُ مَا لَيْسَ ظَاهِرًا","يُرَى غَالِبًا مِنَّا فَقَوْلَيْنِ أَسْنِدِ"],["وَوَجْهَ الْفَتَاةِ انْظُرْ إِذَا كُنْتَ خَاطِبًا","وَمَا يَبْدُ مِنْهَا غَالِبًا فِي الْمُؤَكَّدِ"],["وَعَنْهُ إِلَى وَجْهٍ وَعَنْهُ وَكَفِّهَا","كَمَحْرَمِهَا مِنْ غَيْرِ خَلْوَةٍ ابْعَدِ"],["وَيَنْظُرُ مُسْتَامٌ إِلَى كُلِّ ظَاهِرٍ","يُرَى غَالِبًا وَالرَّأْسِ مَعْ سَاقِ نُهَّدِ"],["كَذَلِكَ فِي قَوْلٍ ذَوَاتُ مَحَارِمٍ","فَكُنْ وَاعِيًا وَاحْفَظْ لِنَفْسِكَ وَاجْهَدِ"],["وَقِيلَ لِيَنْظُرْ غَيْرَ مَا بَيْنَ رُكْبَةٍ","إِلَى سُرَّةٍ فِي الصُّورَتَيْنِ فَقَيِّدِ"],["وَتَخْصِيصُ هَذَا بِالْإِمَاءِ مُقَدَّمٌ","مَخَافَةَ عَيْبٍ غَامِضٍ مُتَعَمَّدِ"],["كَذَا حُكْمُ ذِي التَّمْيِيزِ مِنْ غَيْرِ شَهْوَةٍ","وَإِلَّا كَمَحْرَمِهَا وَعَنْهُ كَأَبْعَدِ"],["وَوَجْهَ الْفَتَاةِ انْظُرْ إِذَا كُنْتَ شَاهِدًا","عَلَيْهَا وَإِنْ بَايَعْتَهَا انْظُرْهُ وَاعْقِدِ"],["وَيَحْرُمُ إِنْ كَانَ الْعِيَانُ لِشَهْوَةٍ","إِلَى كُلِّ مَنْ سَمَّيْتُهُ فِي التَّعَدُّدِ"],["وَكُلٌّ لَهُ مِنْ زَوْجَةٍ لَمْسُ كُلِّهِ","مَعَ النَّظَرِ افْهَمْهُ بِغَيْرِ تَقَيُّدِ"],["كَذَاكَ مُبَاحَاةُ الْإِمَاءِ لِرَبِّهَا","وَإِنْ زُوِّجَتْ يَنْظُرْ سِوَى عَوْرَةٍ قَدِ"],["وَيُكْرَهُ حَقْنُ الْمَرْءِ إِلَّا ضَرُورَةً","وَيَنْظُرُ مَا يَحْتَاجُهُ حَاقِنٌ قَدِ"],["كَقَابِلَةٍ حِلٌّ لَهَا نَظَرٌ إِلَى","مَكَانِ وِلَادَاتِ النِّسَاءِ فِي التَّوَلُّدِ"],["وَيُكْرَهُ إِنْ لَمْ يَسْرِ قَطْعُ بَوَاسِرٍ","وَبَطُّ الْأَذَى حِلٌّ كَقَطْعِ مُجَوَّدِ"],["لِآكِلَةٍ تَسْرِي بِعُضْوٍ أَبِنْهُ إِنْ","تَخَافَنَّ عُقْبَاهُ وَلَا تَتَرَدَّدِ"],["وَقَبْلَ الْأَذَى لَا بَعْدَهُ الْكَيَّ فَاكْرَهَنّ","وَعَنْهُ عَلَى الْإِطْلَاقِ غَيْرَ مُقَيَّدِ"],["كَذَاكَ الرُّقَى إِلَّا بِآيٍ وَمَا رُوِي","فَتَعْلِيقُ ذَا حِلٌّ كَكَتْبٍ لِوُلَّدِ"],["وَكُلُّ دَوَاءٍ فِيهِ خَلْطٌ مُحَرَّمٌ","حَرَامٌ كَتِرْيَاقٍ بِغَيْرِ تَقَيُّدِ"],["وَحَلَّ بِغَيْرِ الْوَجْهِ وَسْمُ بَهَائِمٍ","وَفِي الْأَشْهَرِ اكْرَهْ جَزَّ ذَيْلٍ مُمَدَّدِ"],["كَمَعْرِفَةٍ حَتْمًا لِإِضْرَارِهَا بِمَا","لِقَطْعِكَ مَا تَدْرَا بِهِ لِلْمُنَكَّدِ"],["وَفِي مَا سِوَى الْأَغْنَامِ قَدْ كَرِهُوا الْخِصَا","لِتَعْذِيبِهِ الْمَنْهِيِّ عَنْهُ بِمُسْنَدِ"],["وَقَطْعُ قُرُونٍ وَالْأَذَانِ وَشَقُّهَا","بِلَا ضَرَرٍ تَغْيِيرُ خَلْقٍ مُعَوَّدِ"],["وَحَرِّمْ خِصَاءَ الْآدَمِيِّينَ كُلِّهِمْ","سِوَى فِي قِصَاصٍ مِنْ ظَلُومٍ وَمُعْتَدِ"],["وَيَحْسُنُ فِي الْإِحْرَامِ وَالْحِلِّ قَتْلُ مَا","يَضُرُّ بِلَا نَفْعٍ كَنِمْرٍ وَمَرْثَدِ"],["وَغِرْبَانِ غَيْرِ الزَّرْعِ أَيْضًا وَشِبْهِهَا","كَذَا حَشَرَاتِ الْأَرْضِ دُونَ تَقَيُّدِ"],["كَبَقٍّ وَبُرْغُوثٍ وَفَأْرٍ وَعَقْرَبٍ","وَدَبْرٍ وَحَيَّاتٍ وَشِبْهِ الْمُعَدَّدِ"],["وَيُكْرَهُ قَتْلُ النَّمْلِ إِلَّا مَعَ الْأَذَى","بِهِ وَاكْرَهَنْ بِالنَّارِ إِحْرَاقَ مُفْسِدِ"],["وَلَوْ قِيلَ بِالتَّحْرِيمِ ثُمَّ أُجِيزَ مَعْ","أَذًى لَمْ يَزُلْ إِلَّا بِهِ لَمْ أُبَعِّدِ"],["وَيَحْرُمُ إِلْقَا الْحُوتِ فِي النَّارِ لَمْ يَمُتْ","وَكُلْهُ بِمَا يَحْوِي وَإِنْ لَمْ يُقَدَّدِ"],["وَقَدْ جَوَّزَ الْأَصْحَابُ تَشْمِيسَ قَزِّهِمْ","وَتَدْخِينَ دَبُّورٍ وَشَيًّا بِمُوقَدِ"],["وَيُكْرَهُ لِنَهْيِ الشَّرْعِ عَنْ قَتْلِ ضِفْدَعٍ","وَصِرْدَانِ طَيْرٍ شِبْهِ ذَيْنِ وَهُدْهُدِ"],["وَحَلَّ دَوَابُّ الْمَاءِ غَيْرَ ضَفَادِعٍ","وَيَحْرُمُ تِمْسَاحٌ عَلَى الْمُتَأَكِّدِ"],["وَيَحْرُمُ مَصْبُورٌ مِنَ الْحَيَوَانِ وَالْـ","ـمُجْثِمُ مِنْ طَيْرٍ لِأَغْرَاضِ مُعْتَدِ"],["وَإِنْ تَرَ فِي الْمَذْبُوحِ فِي الْبَطْنِ مَيْتَةً","تَحِلُّ وَحَبَّ الرَّوْثِ حَرِّمْ بِأَوْكَدِ"],["وَيُكْرَهُ قَتْلُ الْهِرِّ إِلَّا مَعَ الْأَذَى","وَإِنْ مُلِكَتْ فَاحْظُرْ إِذَنْ غَيْرَ مُفْسِدِ"],["وَمَا فِيهِ إِضْرَارٌ وَنَفْعٌ كَبَاشِقٍ","وَكَلْبٍ وَفَهْدٍ لِاقْتِصَادِ التَّصَيُّدِ"],["إِذَا لَمْ تَكُنْ مِلْكًا فَأَنْتَ مُخَيَّرٌ","وَإِنْ مُلِكَتْ فَاحْظُرْ وَإِنْ تُؤْذِ فَاقْدُدِ"],["وَمَا لَمْ يَكُنْ فِيهِ انْتِفَاعٌ وَلَا أَذًى","كَدُودِ ذُبَابٍ لَمْ يَضُرَّ كُرْهَهُ طِدِ"],["وَمَا حَلَّ لِلْمُضْطَرِّ حَلَّ لِمُكْرَهٍ","وَمَا لَا فَلَا غَيْرَ الْخُمُورِ بِأَوْكَدِ"],["وَلَغْوٌ مَعَ الْإِكْرَاهِ أَفْعَالُ مُكْرَهٍ","سِوَى الْقَتْلِ وَالْإِسْلَامِ ثُمَّ الزِّنَا قِدِ"],["وَيُكْرَهُ نَفْخٌ فِي الْغَدَا وَتَنَفُّسٌ","وَجَوْلَانُ أَيْدٍ فِي طَعَامٍ مُوَحَّدِ"],["فَإِنْ كَانَ أَنْوَاعًا فَلَا بَأْسَ فَالَّذِي","نُهِيَ فِي اتِّحَادٍ قَدْ عُفِيَ فِي التَّعَدُّدِ"],["وَكُلْ بِثَلَاثٍ مِنْ أَصَابِعَ جَالِسًا","وَمَعْ قَائِمٍ فَاكْرَهْهُمَا وَمُمَدَّدِ"],["وَأَكْلَكَ بِالثِّنْتَيْنِ وَالْإِصْبَعِ اكْرَهَنْ","وَمَعْ نَتَنِ الْعَرْفِ اكْرَهْ إِتْيَانَ مَسْجِدِ"],["وَأَخْذٌ وَإِعْطَاءٌ وَأَكْلٌ وَشَرْبَةٌ","بِيُسْرَاهُ فَاكْرَهْهُ وَمُتَّكِئًا زِدِ"],["وَإِنْ فِي طَرِيقٍ وَاسِعٍ تَبْنِ مَسْجِدًا","بِإِذْنِ إِمَامٍ لَا يَضُرُّ تُسَدَّدِ"],["وَلَا تَبْنِهِ مِنْ غَيْرِ عُذْرٍ بِأَوْكَدٍ","فَقِفْ مَعْ مَرَاسِيمِ الشَّرِيعَةِ تَهْتَدِ"],["وَيَحْرُمُ إِحْدَاثُ الْغِرَاسِ بِمَسْجِدٍ","فَإِنْ وُقِفَتْ مَعْ وَقْفِهِ الْمُتَأَكِّدِ"],["فَإِنْ كَانَ عَنْ أَثْمَانِهَا ذَا غِنًى فَكُلْ","وَإِلَّا فَفِي إِصْلَاحِهِ بِعْهُ وَارْدُدِ"],["وَمَنْ يَبْنِ لِلَّهِ الْمُهَيْمِنِ مَسْجِدًا","بِمَالٍ حَلَالٍ لِلرُّكُوعِ وَسُجَّدِ"],["فَيُبْنَى لَهُ بَيْتٌ بِجَنَّةِ رَبِّهِ","فَصُنْهُ عَنِ الْأَوْسَاخِ وَالْقَذَرِ الرَّدِي"],["وَصُنْ عَنْ قَذَاةٍ أَوْ مُخَاطٍ وَبَزْقَةٍ","وَزَخْرَفَةٍ مَا مِنْ لُجَيْنٍ وَعَسْجَدِ"],["وَيَحْرُمُ بَيْعٌ فِيهِ ثُمَّ شِرَاؤُهُ","وَوَجْهَانِ فِي تَصْحِيحِ بَيْعٍ مُعَقَّدِ"],["وَإِنْ يُبْنَ مَا بَيْنَ الْمَقَابِرِ مَسْجِدٌ","فَحَرِّمْ وَفِي الْمَبْنِيِّ مِنْ قَبْلِهَا اسْجُدِ"],["وَلَا بَأْسَ إِنْ صَلَّى لِمَيْتٍ بِمَسْجِدٍ","وَإِنْشَادُ شِعْرٍ مِنْ مُبَاحٍ لِمُنْشِدِ"],["وَكُلْ جَالِسًا فَوْقَ الْيَسَارِ وَنَاصِبِ الْـ","ـيَمِينَ وَبَسْمِلْ ثُمَّ فِي الِانْتِهَا احْمَدِ"],["وَيُكْرَهُ سَبْقُ الْقَوْمِ لِلْأَكْلِ نَهْمَةً","وَلَكِنَّ رَبَّ الْبَيْتِ إِنْ شَاءَ يَبْتَدِي"],["وَمِنْ قَبْلِ مَسْحٍ فَالْعَقِ الْيَدَ وَالْإِنَا","يُبَارَكْ وَيَسْتَغْفِرْ لَكَ الصَّحْنُ أَسْنِدِ"],["وَكُنْ رَافِعًا قَبْلَ الْقِيَامِ الطَّعَامَ قَدْ","نُهِيَ عَنْ قِيَامٍ قَبْلَ رَفْعِ الْمُمَيَّدِ"],["وَجَمْعٌ عَلَى الزَّادِ الْعِيَالَ يَزِدْ نَمَا","لَهُمْ وَانْهَهُمْ عَنْ أَكْلِهِمْ بِتَفَرُّدِ"],["وَلَا بَأْسَ أَنْ يَخْبَا الْفَتَى قُوتَ أَهْلِهِ","لِعَامٍ وَفِي ذَا بِالنَّبِيِّ لِتَقْتَدِ"],["وَلَا تَحْتَكِرْ قُوتًا فَذَاكَ مُحَرَّمٌ","وَفِي غَيْرِ قُوتٍ لَمْ يُحَرَّمْ بِأَوْكَدِ"],["وَيُشْرَطُ لِلتَّحْرِيمِ تَضْيِيقُ مُشْتَرٍ","عَلَى النَّاسِ فِي وَقْتٍ شَدِيدٍ مُعَجْرَدِ"],["وَمِنْ غَيْرِ إِضْرَارٍ فَلَيْسَ مُحَرَّمًا","كَمُدَّخِرٍ فِي الرُّخْصِ ذَا نَفْعٍ اشْهَدِ"],["وَيَحْرُمُ تَسْعِيرٌ فَرَبِّي مُسَعِّرٌ","وَرُبَّتَمَا التَّسْعِيرُ دَاعِي التَّزَيُّدِ"],["وَإِنْ تَأْكُلَنْ عِنْدَ امْرِئٍ فَادْعُوَنْ لَهُ","فَقَدْ أَمَرَ الْهَادِي بِهِ وَدَعَا اشْهَدِ"],["وَكُنْ مُكْرِمًا لِلْخُبْزِ غَيْرَ مُهِينِهِ","وَأَرْغِفَةً صَغِّرْ وَلِلْعَجْنِ جَوِّدِ"],["وَضَيْفَكَ أَكْرِمْهُ وَعَجِّلْ قِرَاءَهُ","وَقُلْ مَرْحَبًا فِي ذَا بِأَحْمَدَ فَاقْتَدِ"],["وَيَعْرِفُ حَقَّ الضَّيْفِ كُلُّ مُعَالِجِ السَّـ","ـفَارِ مُطِيلُ الْجَوْبِ فِي كُلِّ فَدْفَدِ"],["أَتَى صَرِدًا وَاللَّيْلُ بَادٍ عُبُوسُهُ","يَؤُمُّ سَنَا نَارٍ لِذِي خَيْرِ مُوقِدِ"],["فَوَاسَاهُ مِنْ زَادٍ وَأَبْدَى بَشَاشَةً","وَأَذْهَبَ عَنْهُ الْقُرَّ تَوْطِيدَ مَرْقَدِ"],["فَكَمْ بَيْنَ هَذَا وَامْرِئٍ بَاتَ ضَيْفُهُ","مُضَاجِعَ جُوعٍ مُسْهِرٍ وَتَصَرُّدِ"],["فَلَا خَيْرَ فِيمَنْ لَا يُضَيِّفُ هَكَذَا","رُوِيَ مُسْنَدًا عَنْ خَيْرِ هَادٍ مُحَمَّدِ"],["أَلَا قَاتَلَ اللَّهُ الْبَخِيلَ لِضَنِّهِ","فَلِلضَّيْفِ رِزْقٌ وَاصِلٌ لَمْ يُزَهَّدِ"],["وَلِلْمُسْلِمِ الْمُجْتَازِ بِالْأَخِ فِي الْقُرَى","وَقِيلَ وَمِصْرٍ وَالْكُفُورِ كَمُهْتَدِي"],["ضِيَافَةُ يَوْمٍ أَوْجِبَنَّ وَلَيْلَةٍ","وَقِيلَ ثَلَاثًا وَهْيَ نَدْبٌ بِأَجْوَدِ"],["وَلَيْسَ عَلَيْهِ أَنْ يُبَيِّتَهُ بِلَا","اضْطِرَارٍ سِوَى فَقْدِ مَأْوَى كَمَسْجِدِ"],["وَإِنْ خَافَ مِنْهُ لَمْ يَجِبْ مُطْلَقًا سِوَى","إِذَا اضْطُرَّ قَطْ وَلْيَحْتَرِسْ خَوْفَ مُفْسِدِ"],["وَمَا زَالَ جِبْرِيلٌ يُوَصِّي نَبِيَّنَا","بِجِيرَانِهِ مِنْ أَقْرَبِينَ وَبُعَّدِ"],["إِلَى انْ ظَنَّ أَنْ سَيُورَثُ الْجَارُ يَا فَتَى","وَأَقْرَبُهُمْ بِالْبِرِّ أَوْلَى فَجَوِّدِ"],["وَمَنْ دَارُهُ تَعْلُو عَلَى الْجَارِ يَلْزَمَنْ","بِنًا يَسْتُرُ الْأَدْنَى لِبَاغِي تَصَعُّدِ"],["وَيَلْزَمُ أَيْضًا سَدُّ طَاقٍ عَلَا وَلَوْ","تَقَدَّمْ وَدَعْوَى لَا أَرَى لَا تُقَلِّدِ"],["وَمَنْ يَأْبَ أَلْزِمْهُ الْبِنَا مَعَ جَارِهِ","إِذَا اسْتَوَيَا فِي الِارْتِفَاعِ بِأَجْوَدِ"],["وَلَا غُرْمَ فِي هَدْمِ الْمَخُوفِ سُقُوطُهُ الْـ","ـمُضِرِّ وَإِنْ يُؤْمَنْ لِيَضْمَنْهُ مُعْتَدِ"],["وَمَنْ كَانَ يُؤْمِنُ بِالْمَلِيكِ إِلَهِنَا","فَلَا يُؤْذِ جَارًا صَالِحًا غَيْرَ مُفْسِدِ"],["وَيَمْنَعْهُ مِنْ كُلِّ مُؤْذٍ لِجَارِهِ","كَحُشٍّ وَحَمَّامٍ وَتَنُّورِ مُوقِدِ"],["وَدُكَّانِ حَدَّادٍ وَدَقِّ قِصَارَةٍ","وَمَدْبَغَةٍ تُؤْذِي بِرِيحٍ مُنَكِّدِ"],["وَمِنْ غَرْسِ مَا يَمْتَدُّ مِنْهُ عُرُوقُهُ","إِلَى بِئْرِ مَاءِ الْجَارِ فِي الْمُتَأَطِّدِ"],["وَسِيَّانِ مُؤْذِي النَّفْسِ وَالْمَالِ يَا فَتَى","وَضَمِّنْهُ مَا أَرْدَاهُ فِعْلُ الْمُصَدِّدِ"],["وَيُكْرَهُ أَكْلُ الْهَجْمِ إِنْ يَتَرَصَّدَنْ","مَعَ الْإِذْنِ لَكِنْ دُونَهُ احْظُرْهُ وَاطْرُدِ"],["وَبُشَّ إِلَى الضِّيفَانِ وَامْزَحْ عَلَى الْقِرَى","لِتُذْهِبَ عَنْهُ خَجْلَةَ الْمُتَنَكِّدِ"],["وَكُنْ مُؤْثِرًا إِنْ كَانَ فِي الزَّادِ قِلَّةٌ","وَلَا تَتَكَلَّفْ تَعْجَزَنَّ فَتَفْنَدِ"],["وَمَعْ بَنِي دُنْيَا إِنَ اكَلْتَ فَاحْتَشِمْ","وَمَعْ فُقَرَائِهِمْ أَثِرْهُمْ تُسَدَّدِ"],["وَالِاخْوَانُ مَعْهُمْ إِنْ أَكَلْتَ فَانْبَسِطْ","وَوَانِسْ وَلَا تَذْكُرْ كَلَامًا يُنَكِّدِ"],["وَلَا تَحْكِيَنَّ الْمُضْحِكَاتِ فَيَشْرَقُوا","وَلَا تَذْكُرَنْ بَوْلًا وَلَا قَذَرًا رَدِي"],["وَلَا تَحْقِرَنْ شَيْئًا يُقَدَّمُ لِلْقِرَى","وَتَعْجِيلُ نَزْرٍ زِينَةٌ لِلْمُصَرِّدِ"],["وَيُكْرَهُ أَكْلُ التُّرْبِ إِلَّا تَدَاوِيًا","وَأَكْلُ خَبِيثِ الرِّيحِ غَيْرِ مُصَخَّدِ"],["وَأَكْلُكَ أُذْنَ الْقَلْبِ وَالْغُدَدَ اكْرَهَنْ","وَحَرِّمْ شِرَى جَوْزِ الْقِمَارِ وَشَرِّدِ"],["وَإِنْ مَرَّ إِنْسَانٌ بِأَثْمَارِ حَائِطٍ","بِلَا حَائِطٍ أَوْ نَاظِرٍ مُتَرَصِّدِ"],["لِيَأْكُلْ وَلَا يَحْمِلْ وَلَوْ عَنْ غُصُونِهِ","وَعَنْ أَحْمَدَ احْظُرْ مِنْهُ غَيْرَ الْمُبَدَّدِ"],["وَعَنْ أَحْمَدَ احْظُرْ مُطْلَقًا دُونَ حَاجَةٍ","وَمَعْهَا بِلَا غُرْمٍ فَكُلْ لَا تَزَوَّدِ"],["وَلَيْسَ عَلَيْهِ فِي الْمُبَاحِ غَرَامَةٌ","كَأَكْلٍ لِضُرٍّ مِنْ مَحُوطٍ بِمُبْعَدِ"],["وَلَا تَطْعَمَنْ مِنْ دَرِّ أَنْعَامِ غَائِبٍ","وَزَرْعٍ بِحَبِّ الرَّطْبِ مِنْهُ بِأَوْكَدِ"],["وَيَحْرُمُ زَرْعٌ أَوْ ثِمَارٌ سَقَيْتَهُ النَّـ","ـجَاسَةَ أَوْ دَمَلْتُمُوهَا بِأَوْطَدِ"],["وَإِنْ سُقِيَتْ مِنْ بَعْدِ ذَاكَ بِطَاهِرٍ","أُبِيحَتْ وَقِيلَ اكْرَهْ فَقَطْ لَا تُشَدِّدِ"],["وَمَنْ كَانَ أَوْفَى قُوتِهِ مِنْ نَجَاسَةٍ","وَقِيلَ كَثِيرًا مِنْهُ حَرِّمْ بِأَوْكَدِ"],["وَأَلْبَانَهَا وَالْبَيْضَ مِنْهَا فَحَرِّمَنْ","وَعَنْهُ بَلِ اكْرَهْ قَبْلَ تَحْبِيسِهَا قِدِ"],["وَلَا تَحْظُرَنْ إِنْ كَانَ أَوْفَاهُ طَاهِرًا","وَلَا تَكْرَهَنْ مِنْ بَعْدِ حَبْسٍ مُقَيَّدِ"],["ثَلَاثَةَ أَيَّامٍ وَتُطْعَمُ طَاهِرًا","وَيُكْرَهُ قَبْلَ الْحَبْسِ إِنْ تُرْكَبِ اشْهَدِ"],["وَمَنْ لَمْ يُرِدْ أَنْ يَذْبَحَ الْبُدْنَ عَاجِلًا","يَجُزْ عَلْفُهَا أَحْيَانًا النَّجِسَ الرَّدِ"],["وَإِطْعَامُهُ الْمَحْظُورَةَ اللَّحْمِ جَائِزٌ","عَلَى نَصِّهِ مَعْ كُرْهِ كُلٍّ بِأَوْكَدِ"],["وَيُكْرَهُ فِي التَّمْرِ الْقِرَانُ وَنَحْوُهُ","وَقِيلَ مَعَ التَّشْرِيكِ لَا فِي التَّفَرُّدِ"],["وَلَا بَأْسَ عِنْدَ الْأَكْلِ مِنْ شِبَعِ الْفَتَى","وَمَكْرُوهٌ الْإِسْرَافُ وَالثُّلْثَ أَكِّدِ"],["وَيَحْسُنُ قَبْلَ الْمَسْحِ لَعْقُ أَصَابِعٍ","وَأَكْلُ فُتَاتٍ سَاقِطٍ بِتَثَرُّدِ"],["وَيَحْسُنُ تَصْغِيرُ الْفَتَى لُقْمَةَ الْغَذَا","وَبَعْدَ ابْتِلَاعٍ ثَنِّ وَالْمَضْغَ جَوِّدِ"],["وَتَخْلِيلُ مَا بَيْنَ الْمَوَاضِعِ بَعْدَهُ","وَأَلْقِ وَجَانِبْ مَا نَهَى اللَّهُ تَهْتَدِ"],["وَغَسْلُ يَدٍ قَبْلَ الطَّعَامِ وَبَعْدَهُ","وَيُكْرَهُ بِالْمَطْعُومِ غَيْرَ مُقَيَّدِ"],["وَيُكْرَهُ نَوْمُ الْمَرْءِ مِنْ قَبْلِ غَسْلِهِ","مِنَ الدُّهْنِ وَالْأَلْبَانِ لِلْفَمِ وَالْيَدِ"],["وَكُلْ طَيِّبًا أَوْ ضِدَّهُ وَالْبَسِ الَّذِي","تُلَاقِيهِ مِنْ حِلٍّ وَلَا تَتَقَيَّدِ"],["وَمَا عِفْتَهُ فَاتْرُكْهُ غَيْرَ مُعَنِّفٍ","وَلَا عَائِبٍ رِزْقًا وَبِالشَّارِعِ اقْتَدِ"],["وَلَا تَشْرَبَنْ مِنْ فِي السِّقَاءِ وَثُلْمَةِ الْـ","ـإِنَاءِ وَانْظُرَنْ فِيهِ وَمَصًّا تَزَرَّدِ"],["وَنَحِّ الْإِنَا عَنْ فِيكَ وَاشْرَبْ ثَلَاثَةً","هُوَ اهْنَا وَأَمْرَا ثُمَّ أَرْوَى لِمَنْ صَدِي"],["وَأَخْذٌ وَإِعْطَاءٌ وَأَكْلٌ وَشُرْبُهُ","بِيُسْرَاهُ فَاكْرَهْهُ وَمُتَّكِئًا زِدِ"],["وَيُكْرَهُ بِالْيُمْنَى مُبَاشَرَةُ الْأَذَى","وَأَوْسَاخِهِ مَعْ نَثْرِ مَا أَنْفِهِ الرَّدِي"],["كَذَا خَلْعُ نَعْلَيْهِ بِهَا وَاتِّكَاؤُهُ","عَلَى يَدِهِ الْيُسْرَى وَرَا ظَهْرِهِ اشْهَدِ"],["وَنَوْمُكَ بَعْدَ الْفَجْرِ وَالْعَصْرِ أَوْ عَلَى","قَفَاكَ وَرَفْعُ الرِّجْلِ فَوْقَ اخْتِهَا امْدُدِ"],["وَيُكْرَهُ بَيْنَ الظِّلِّ وَالْحَرِّ جِلْسَةٌ","وَنَوْمٌ عَلَى وَجْهِ الْفَتَى الْمُتَمَدِّدِ"],["وَقَتْلُكَ حَيَّاتِ الْبُيُوتِ وَلَمْ تَقُلْ","ثَلَاثًا لَهُ اذْهَبْ سَالِمًا غَيْرَ مُعْتَدِ"],["وَذَا الطُّفْيَتَيْنِ اقْتُلْ وَأَبْتَرَ حَيَّةٍ","وَمَا بَعْدَ إِيذَانٍ يُرَى أَوْ بِفَدْفَدِ"],["وَيُكْرَهُ نَوْمٌ فَوْقَ سَطْحٍ وَلَمْ يُحَطْ","عَلَيْهِ بِتَحْجِيرٍ لِخَوْفٍ مِنَ الرَّدِي"],["كَذَاكَ رُكُوبُ الْبَحْرِ فِي هَيَجَانِهِ","وَوَطْءُ النِّسَا فِي السُّفْنِ فِي نَصِّ أَحْمَدِ"],["وَلَا تَفْعَلَنَّ النَّذْرَ مَا النَّذْرُ سُنَّةٌ","لِفُقْدَانِهِ مِنْ كُلِّ هَادٍ وَمُرْشِدِ"],["وَلَا تَحْسَبَنَّ النَّذْرَ لِلْخَيْرِ جَالِبًا","بَلِ النَّذْرُ مِخْرَاقُ الْبَخِيلِ الْمُشَدِّدِ"],["وَلَيْسَ حَرَامَ الْفِعْلُ إِذْ نُدِبَ الْوَفَا","بِهِ فِي كِتَابِ اللَّهِ مَعْ صِدْقِ مُسْنَدِ"],["وَكُنْ عَالِمًا أَنَّ الشَّهَادَةَ مَنْصِبٌ","مِنَ الدِّينِ حِفْظًا لِلْحُقُوقِ مِنَ الرَّدِ"],["وَفِيهَا صَلَاحٌ لِلْفَرِيقَيْنِ حَقُّ ذَا","يُصَانُ وَتَبْرَا ذِمَّةُ الْمُتَجَحِّدِ"],["وَكُنْ ذَا احْتِيَاطٍ عَنْ شَهَادَةِ فِرْيَةٍ","تَؤُولُ إِلَى سُخْطِ الْمُهَيْمِنِ فِي غَدِ"],["وَتُوجِبُ لِلْآتِي بِهَا فِي مَقَامَةِ الْـ","ـجَحِيمِ رَوَى هَذَا ابْنُ مَاجَةَ أَسْنِدِ"],["وَكَمْ حَذَّرَ الْهَادِي الْوَرَى عَنْ شَهَادَةٍ","بِزُورٍ بِتَهْدِيدٍ أَتَى وَتَوَعُّدِ"],["أَمَا قَالَ قَوْلُ الزُّورِ أَعْلَى كَبِيرَةٍ","مَعَ الشِّرْكِ فِي لَفْظِ الصَّحِيحَيْنِ قَيِّدِ"],["فَأَرْبَعَةٌ بِالزُّورِ يُهْلِكُ نَفْسَهُ","وَبَاغٍ وَمَظْلُومٌ وَقَاضٍ تَعَمَّدِ"],["كَفَى زَاجِرًا عَنْ ذَلِكُمْ كُلَّ عَاقِلٍ","سُقُوطُ شَهِيدِ الزُّورِ مِنْ عَيْنِ شُهَّدِ"],["وَيَحْرُمُ فِي الْحَالَيْنِ جُعْلٌ وَقِيلَ لَا","لِفَقْرٍ وَقِيلَ انْ عَيَّنَا وَالْأَدَا قِدِ"],["وَمَنْ عِنْدَهُ عِلْمٌ بِحَدٍّ لِرَبِّهِ","فَتَرْكُ الْأَذَى أَوْلَى وَإِنْ شَا لِيَشْهَدِ"],["وَلَوْ قِيلَ دَعْوَى وَاعْكِسِ إِنْ تَخْشَ كَثْرَةَ الْـ","ـخَنَا أَوْ أَبَى وَعْظًا بَلَ اوْجِبْ بِأَجْوَدِ"],["وَيُنْدَبُ لِلْإِرْشَادِ لَا لِمَثُوبَةٍ","عَلَى كُلِّ عَقْدٍ غَيْرَ مَا أَوْجَبَ اشْهَدِ"],["وَحَظْرُ شَهَادَاتِ الْفَتَى بِسِوَى الَّذِي","بِأَوْقَاتِ الِاسْتِرْعَاءِ يَعْلَمُهُ قِدِ"],["وَرُدَّ الْمُغَنِّيَ وَالْمُصَافِعَ مَعْ ذَوِي التَّـ","ـمَسْخُرِ وَالرَّقَّاصِ تُهْدَ وَتُرْشَدِ"],["وَلَاعِبَ شِطْرَنْجٍ وَنَرْدٍ لِفِعْلِهِ الْـ","ـحَرَامَ وَلَعَّابَ الْحَمَامِ الْمُغَرِّدِ"],["إِذَا كَانَ عَبَّاثًا بِهَا أَوْ مُقَامِرًا","وَسَرَّاقًا امْنَعْهُ الشَّهَادَةَ وَارْدُدِ"],["وَمَنْ يَقْتَنِي لِلْأُنْسِ أَوْ لِفِرَاخِهَا","أَوِ الْكُتْبِ لَمْ يُمْنَعْ لِصِحَّةِ مَقْصَدِ"],["وَمُفْشِيَ سِرٍّ مِنْ جِمَاعٍ وَنَحْوِهِ","وَكَشَّافَ مَا فِي الْعُرْفِ صِينَ بِمَشْهَدِ"],["وَمَنْ يَدْخُلُ الْحَمَّامَ مِنْ غَيْرِ مِئْزَرٍ","وَيَأْكُلُ بَيْنَ النَّاسِ مَا لَمْ يُعَوَّدِ"],["وَمَنْ مَدَّ رِجْلَيْهِ لِغَيْرِ ضَرُورَةٍ","وَخَاطَبَ بِالْفُحْشِ النِّسَاءَ بِمَحْشَدِ"],["وَزَاعِمَ جَمْعِ الْجِنِّ ثُمَّ مُنَجِّمًا","وَرَمَّالًا اوْ قَصَّاصًا وَمُؤَجِّرَ الرَّدِ"],["وَلَعَّابَ أُرْجُوحٍ وَرَفْعَ الثِّقَالِ وَالْـ","ـمُسَابِقَ فِي سَبْحٍ وَسَعْيِ مُعَوَّدِ"],["وَأَنْ يَحْتَوِي لُعْبٌ عَلَى عِوَضٍ مِنَ الْـ","ـجَوَانِبِ أَوْ مِنْ بَعْضِهَا احْظُرْهُ وَاصْدُدِ"],["فَذَاكَ قِمَارٌ مَيْسِرٌ بِاجْتِنَابِهِ","أَتَى الْأَمْرُ فِي الْقُرْآنِ أَمْرَ مُهَدِّدِ"],["وَإِنْ يَخْلُ عَنْ جُعْلٍ فَمِنْهُ مُحَرَّمٌ","كَنَرْدٍ وَشِطْرَنْجٍ وَشِبْهِهِمَا اعْدُدِ"],["وَقِيلَ اكْرَهِ الشِّطْرَنْجَ لَا تَحْظُرَنْ فَبِالتَّـ","ـكَثُّرِ مِنْهُ ارْدُدْهُ لَا بِالْمُصَرِّدِ"],["وَلَا بَأْسَ فِي لُعْبٍ بِغَيْرِ أَذَى وَلَا","دَنَاءَةَ فِيهِ كَالشِّقَافِ الْمُعَوَّدِ"],["وَإِيَّاكَ شُرْبًا لِلْخُمُورِ فَإِنَّهَا","تُسَوِّدُ وَجْهَ الْعَبْدِ فِي الْيَوْمِ مَعْ غَدِ"],["أَلَا إِنَّ شُرْبَ الْخَمْرِ ذَنْبٌ مُعَظَّمٌ","يُزِيلُ صِفَاتِ الْآدَمِيِّ الْمُسَدَّدِ"],["فَيُلْحَقُ بِالْأَنْعَامِ بَلْ هُوَ دُونَهَا","يُخَلِّطُ فِي أَفْعَالِهِ غَيْرَ مُهْتَدِ"],["وَيَسْخَرُ مِنْهُ كُلُّ رَاءٍ لِسُوءِ مَا","يُعَايِنُ مِنْ تَخْلِيطِهِ وَالتَّبَدُّدِ"],["يُزِيلُ الْحَيَا عَنْهُ وَيَذْهَبُ بِالْغِنَا","وَيُوقِعُ فِي الْفَحْشَا وَقَتْلِ الْمُعَرْبِدِ"],["وَكُلُّ صِفَاتِ الذَّمِّ فِيهَا تَجَمَّعَتْ","كَذَا سُمِّيَتْ أُمَّ الْفُجُورِ فَأَسْنِدِ"],["فَكَمْ آيَةٍ تُنْبِي بِتَحْرِيمِهَا لِمَنْ","تَدَبَّرَ آيَاتِ الْكِتَابِ الْمُمَجَّدِ"],["وَقَدْ لَعَنَ الْمُخْتَارُ فِي الْخَمْرِ تِسْعَةً","رَوَاهُ أَبُو دَاوُدَ عَنْ خَيْرِ مُرْشِدِ"],["وَأَقْسَمَ رَبُّ الْعَرْشِ أَنْ لَيُعَذِّبَنْ","عَلَيْهَا رَوَاهُ أَحْمَدٌ عَنْ مُحَمَّدِ"],["وَمَا قَدْ أَتَى فِي حَظْرِهَا بَالِغٌ إِذَا","تَأَمَّلْتَهُ حَدَّ التَّوَاتُرِ فَاهْتَدِ"],["وَأَجْمَعْ عَلَى تَحْرِيمِهَا كُلُّ مُسْلِمٍ","فَكَفِّرَ مُبِيحَنْهَا وَفِي النَّارِ خَلِّدِ"],["وَإِدْمَانُهَا إِحْدَى الْكَبَائِرِ فَاجْتَنِبْ","لَعَلَّكَ تَحْظَى بِالْفَلَاحِ وَتَهْتَدِي"],["وَيَحْرُمُ مِنْهَا النَّزْرُ مِثْلُ كَثِيرِهَا","وَلَيْسَتْ دَوَاءً بَلْ هِيَ الدَّاءُ فَابْعِدِ"],["فَمَا جَعَلَ اللَّهُ الْعَظِيمُ دَوَاءَنَا","بِمَا هُوَ مَحْظُورٌ بِمِلَّةِ أَحْمَدِ"],["وَكُلُّ شَرَابٍ إِنْ تَكَاثَرَ مُسْكِرًا","يُحَرَّمُ مِنْهُ النَّزْرُ وَالْخَمْرَ فَاعْدُدِ"],["وَمِنْ أَيِّ شَيْءٍ كَانَ يَحْرُمُ مُطْلَقًا","وَلَوْ كَانَ مَطْبُوخًا بِغَيْرِ تَقَيُّدِ"],["سِوَى لِظَمَا الْمُضْطَرِّ إِنْ مُزِجَتْ بِمَا","يُرَوِّي وَلِلْمُغْتَصِّ إِجْمَاعًا ازْدَدِ"],["وَلَا يَثْبُتُ التَّحْرِيمُ فِيمَا انْتَبَذْتَهُ","قُبَيْلَ الثَّلَاثِ اشْرَبْهُ مَا لَمْ يُزَبِّدِ"],["وَلَا بَأْسَ بِالْفُقَّاعِ إِذْ لَيْسَ مُسْكِرًا","وَلَا آيِلًا بَلْ إِنْ يُبَقِّيهِ يَفْسُدِ"],["وَعَزِّرْ مَنِ اسْتَمْنَى وَلَمْ يَخَفِ الزِّنَا","وَلَا ضَرَرًا فِي جِسْمِهِ وَتَوَعَّدِ"],["وَعَنْ أَحْمَدٍ بَلْ فِيهِ مَعْ فَقْدِ خَوْفَةٍ","كَرَاهَةُ تَنْزِيهٍ بِغَيْرِ تَشَدُّدِ"],["وَقَدْ نَقَلَ الْبَنَّاءُ تَكْفِيرَ مَنْ رَأَى","مَسَبَّةَ أَصْحَابِ النَّبِيِّ مُحَمَّدِ"],["حَذَارِكَ مِنْ كَذْبِ الْيَمِينِ فَإِنَّهُ","لَيُوجِبُ سُخْطَ اللَّهِ إِنْ يُتَعَمَّدِ"],["وَأَوْجِبْ لِإِنْجَا هَالِكٍ مِنْ ظَلَامَةٍ","وَنَدْبٍ لِمَنْدُوبٍ لِإِصْلَاحِ مُفْسِدِ"],["وَمَنْ يُولِ عَهْدًا كَاذِبًا لِاقْتِطَاعِهِ","بِحَقِّ امْرِئٍ يُغْضَبْ عَلَيْهِ وَيُبْعَدِ"],["وَلَا شَيْءَ فِي إِيلَا الْمُحِقِّ تَيَقُّنًا","وَإِنْ يَفْتَدِي الْإِيلَا أَبَرَّ فَجَوِّدِ"],["وَلَا تَجْعَلَنَّ اللَّهَ دُونَكَ جُنَّةً","بِأَيْمَانِ كِذْبٍ كَالْمُنَافِقِ تَعْتَدِي"],["وَيُكْرَهُ تَكْثِيرٌ وَإِفْرَاطُ صَادِقِ الْـ","ـيَمِينِ لِخَوْفِ الْكَذِبِ عِنْدَ التَّعَدُّدِ"],["وَمَنْ يَكُ خَيْرًا حِنْثُهُ فَهْوَ سُنَّةٌ","وَنَدْبٌ لَدَى الْقَاضِي لِذِي الْحَقِّ يَفْتَدِ"],["وَلَا بَأْسَ فِي أَيْمَانِهِ مَعَ صِدْقِهِ","وَلَا يَنْفَعُ التَّأْوِيلُ مِنْ كُلِّ مُعْتَدِ"],["وَحَرِّمْ وَقِيلَ اكْرَهْ يَمِينًا بِمَنْ سِوَى الْـ","ـإِلَهِ لَهُ أَسْنَدْتَ أَوْ لَمْ تُقَيِّدِ"],["وَلَا يَجِبُ التَّكْفِيرُ مِنْ حِنْثِ حَالِفٍ","سِوَى حَالِفٍ بِاللَّهِ رَبِّي وَمُوجِدِي"],["وَلَمْ تَنْعَقِدْ أَيْمَانُ غَيْرِ مُكَلَّفٍ","مُرِيدًا مُوَاتِيهِ وَإِنْ لَمْ يُعَوَّدِ"],["وَنَدْبٌ وَقِيلَ اوْجِبْ تَبَرُّرَ مُقْسِمٍ","بِلَا ضَرَرٍ أَوْ ظَاهِرًا أَبْرِزَنْ قِدِ"],["وَمَنْ يَتَوَسَّلْ بِالْإِلَهِ أَجِبْ تُصِبْ","بِلَا ضَرَرٍ مَا سَنَّهُ خَيْرُ مُرْشِدِ"],["أَلَا إِنَّ قَذْفَ الْمُحْصَنَاتِ كَبِيرَةٌ","أَتَى النَّصُّ فِي تَعْظِيمِهَا بِالتَّوَعُّدِ"],["أَيَا أُمَّةَ الْهَادِي أَمَا تَنْهَوُنَّ عَنْ","ذُنُوبٍ بِهَا حَبْسُ الْحَيَا الْمُتَعَوَّدِ"],["وَذَلِكَ عُقْبَى الْجَوْرِ مِنْ كُلِّ ظَالِمٍ","وَعُقْبَى الزِّنَا ثُمَّ الرِّبَا وَالتَّزَيُّدِ"],["تَعُمُّ بِمَا تَجْنِي الْعُقُوبَةُ غَيْرَنَا","هُنَا وَغَدًا يَشْقَى بِهَا كُلُّ مُعْتَدِ"],["وَقَاذِفَ أُمِّ الْمُصْطَفَى اقْتُلْهُ بَتَّةً","وَلَوْ كَانَ ذَا إِسْلَامٍ أَوْ ذَا تَهَوُّدِ"],["وَقَاذِفُهُ أَيْضًا وَذَلِكَ رِدَّةٌ","وَلَا يُسْقِطُ الْإِسْلَامُ قَتْلًا بِأَوْكَدِ"],["وَإِنْ كَانَ ذَا كُفْرٍ فَأَسْلَمَ أَبْقِهِ","فِي الِاوْلَى وَعِنْدَ اللَّهِ يُفْلِحُ مَنْ هُدِي"],["وَمَنْ تَابَ مِنْ قَذْفِ امْرِئٍ قَبْلَ عِلْمِهِ","وَتَحْلِيلِهِ لَمْ يَبْرَ فِي الْمُتَأَكَّدِ"],["خَفِ اللَّهَ فِي ظُلْمِ الْوَرَى وَاحْذَرَنَّهُ","وَخَفْ يَوْمَ عَضِّ الظَّالِمِينَ عَلَى الْيَدِ"],["وَلَا تَحْسَبَنَّ اللَّهَ عَنْ ذَاكَ غَافِلًا","وَلَكِنَّهُ يُمْلِي لِمَنْ شَا إِلَى الْغَدِ"],["فَلَا تَغْتَرِرْ بِالْحِلْمِ عَنْ ظُلْمِ ظَالِمٍ","سَيَأْخُذُهُ أَخْذًا وَبِيلًا وَعَنْ يَدِ"],["أَلَا إِنَّ ظُلْمَ النَّاسِ ذَنْبٌ مُعَظَّمٌ","أَتَى النَّصُّ فِي تَحْرِيمِهِ بِالتَّوَعُّدِ"],["وَيُرْجَى لِغَيْرِ الظُّلْمِ غُفْرَانُهُ غَدًا","وَإِنْ يَشَأِ الْمَظْلُومُ يَقْتَصُّ فِي غَدِ"],["وَمَنْ كَانَ فِي الدُّنْيَا يَشِحُّ بِمَالِهِ","فَكَيْفَ بِهِ يَوْمَ الْعَذَابِ الْمُؤَبَّدِ"],["فَلَا تَغْتَرِرْ مِمَّنْ يُسَامَحُ فِي الدُّنَا","وَأَدِّ حُقُوقَ النَّاسِ تَسْلَمْ وَتَرْشُدِ"],["إِذَا كَانَ دَيْنُ الْمَرْءِ فَهْوَ عَنِ الرِّضَى","مَتَى لَمْ يُوَفَّ يَبْقَ كَيْفَ بِمَشْهَدِ"],["وَمَنْ قَتَلَ الزَّانِي بِزَوْجَتِهِ فَلَا","قِصَاصَ عَلَيْهِ فِي الظَّلُومِ وَلَا يَدِي"],["وَإِنْ لَمْ يُصَدِّقْهُ الْوَلِيُّ وَلَا أَتَى","بِبَيِّنَةِ الْعُدْوَانِ ضَمِّنْهُ وَالْهَدِ"],["وَإِيَّاكَ قَتْلَ الْعَمْدِ ظُلْمًا لِمُؤْمِنٍ","فَذَلِكَ بَعْدَ الشِّرْكِ كُبْرَى التَّفَسُّدِ"],["كَفَى زَاجِرًا عَنْهُ تَوَعُّدُ قَادِرٍ","بِنَارٍ وَلَعْنٍ ثُمَّ تَخْلِيدِ مُعْتَدِ"],["فَقَدْ قَالَ عَبْدُ اللَّهِ فِيهَا مُؤَوِّلًا","بِنَفْيِ مَتَابِ الْقَاتِلِ الْمُتَعَمِّدِ"],["وَتَخْلِيدِهِ فِي النَّارِ مِنْ غَيْرِ مَخْرَجٍ","وَقَالَ سِوَاهُ إِنْ يُجَازَى يُخَلَّدِ"],["وَإِلَّا فَعَفْوُ اللَّهِ عَنْ غَيْرِ مُشْرِكٍ","فَسِيحٌ كَمَا أَنْبَا بِآيٍ مُعَدَّدِ"],["وَتَسْتَغْفِرُ اللَّهَ الْعَظِيمَ بِتَوْبَةٍ","وَتَرْفَعُ كَفَّ الْمُسْتَغِيثِ الْمُجَهَّدِ"],["وَتَدْعُو دُعَاءَ الْمُخْبِتِينَ بِرَغْبَةٍ","دُعَاءَ غَرِيقٍ فِي دُجَا اللَّيْلِ مُفْرَدِ"],["فَإِنَّ الَّذِي تَدْعُوهُ يَرْزُقُ مَنْ عَصَى","وَفَاتِحُ بَابٍ لِلْمُطِيعِ وَمُعْتَدِي"],["وَلَكِنَّمَا صِدْقُ الرَّجَاءِ مَفَاتِحُ الْـ","ـخَزَائِنِ فَادْعُ وَابْتَغِ الْفَضْلَ وَاجْهَدِ"],["وَقُلْ بِانْكِسَارٍ قَارِعًا بَابَ رَاحِمٍ","قَرِيبٍ مُجِيبٍ بِالْفَوَاضِلِ يَبْتَدِي"],["إِلَهِي أَتَى الْعَاصُونَ بَابَكَ مَلْجَأً","يُرَجُّونَ عَفْوًا مِنْكَ رَبِّي وَسَيِّدِي"],["إِلَيْكَ فَرَرْنَا مِنْ عَذَابِكَ رَهْبَةً","فَلَا تَطْرُدَنَّا عَنْ جَنَابِكَ وَاسْعِدِ"],["دَعَوْنَاكَ لِلْأَمْرِ الَّذِي أَنْتَ ضَامِنٌ","إِجَابَتَهُ يَا غَيْرَ مُخْلِفِ مَوْعِدِ"],["إِلَيْكَ مَدَدْنَا بِالرَّجَاءِ أَكُفَّنَا","فَحَاشَاكَ مِنْ رَدِّ الْفَتَى صَافِرَ الْيَدِ"],["وَمَنْ يَنْتَحِبْ مِنْ خَشْيَةِ اللَّهِ قُلْ لَهُ","طَفَأْتَ لَظًى وَاحْرَزْتَ كُلَّ التَّعَبُّدِ"],["فَعَيْنٌ بَكَتْ مِنْ خَشْيَةِ اللَّهِ حُرِّمَتْ","عَلَى النَّارِ فِي نَصِّ الْحَدِيثِ الْمُسَدَّدِ"],["عَلَى الصَّلَوَاتِ الْخَمْسِ حَافِظْ فَإِنَّهَا","لَآكَدُ مَفْرُوضٍ عَلَى كُلِّ مُهْتَدِي"],["فَلَا رُخْصَةٌ فِي تَرْكِهَا لِمُكَلَّفٍ","وَأَوَّلُ مَا عَنْهَا يُحَاسَبُ فِي غَدِ"],["بِإِهْمَالِهَا يَسْتَوْجِبُ الْمَرْءُ قَرْنَهُ","بِفِرْعَوْنَ مَعْ هَامَانَ فِي شَرِّ مِذْوَدِ"],["وَمَا زَالَ يُوصِي بِالصَّلَاةِ نَبِيُّنَا","لَدَى الْمَوْتِ حَتَّى كَلَّ عَنْ نُطْقِ مِذْوَدِ"],["بِهَا مُرْ بَنِي سَبْعٍ وَذِي الْعَشْرِ فَاضْرِبَنْ","وَعَنْهُ كَذَا أَوْجِبْ عَلَيْهِمْ وَشَدِّدِ"],["وَأَوْجِبْ عَلَى وَلِيِّهِمْ أَمْرَهُمْ بِهَا","وَصَحِّحْ صَلَاةَ الْوَاعِ مِنْهُمْ تُسَدَّدِ"],["وَتَفْوِيتُهَا أَوْ بَعْضِهَا مِنْ مُكَلَّفٍ","حَرَامٌ سِوَى لِلْجَمْعِ أَوْ شَرْطِ فُقَّدِ"],["وَمَنْ جَحَدَ الْإِيجَابَ كَفِّرْهُ إِنْ يَشَأْ","بِدَارِ الْهُدَى مَا بَيْنَ أَهْلِ التَّعَبُّدِ"],["كَذَا كُلُّ مَجْمُوعٍ عَلَى حُكْمِهِ مَتَى","يَكُنْ ظَاهِرًا دُونَ الْخَفِيِّ الْمُبَعَّدِ"],["فَمَنْ جَحَدَ الْأَرْكَانَ أَوْ حُرْمَةَ الزِّنَا","وَخَمْرٍ وَحِلَّ الْمَاءِ وَالْخُبْزِ يَجْحَدِ"],["وَأَشْبَاهِهَا مِنْ ظَاهِرِ الْحُكْمِ مُجْمَعٌ","عَلَيْهِ لِجَهْلٍ عَرِّفَنْهُ وَأَرْشِدِ"],["فَمَنْ لَمْ يَتُبْ أَوْ لَيْسَ يَجْهَلُ مِثْلُهُ","لِمَجْحُودِهِ يَكْفُرْ وَبِالسَّيْفِ فَاقْدُدِ"],["وَتَارِكِ إِحْدَى الْخَمْسِ وَهْنًا وَصَوْمِهِ","وَحَجًّا زَكَاةً نَاوِيًا تَرْكَ سَرْمَدِ"],["وَمُرْجِيهِ مَعَ ظَنِّهِ الْمَوْتَ قَبْلَهُ","إِذَا لَمْ يَتُبْ فَاقْتُلْهُ كُفْرًا بِأَبْعَدِ"],["وَمَنْ جَحَدَ الْخَلَّاقَ أَوْ صِفَةً لَهُ","أَوِ الْبَعْضَ مِنْ كُتْبِ الْإِلَهِ الْمُوَحَّدِ"],["أَوِ الرُّسْلَ أَوْ مَنْ سَبَّهُ أَوْ رَسُولَهُ","وَلَوْ كَانَ ذَا مَزْحٍ كَفَرْ كَالتَّعَمُّدِ"],["وَمُسْتَهْزِئٍ بِاللَّهِ أَوْ آيَةٍ لَهُ","أَوِ الرُّسْلِ كَفِّرْهُ وَأَدِّبْ وَلَوْ هُدِي"],["وَدَعْوَى شَرِيكٍ أَوْ أَبٍ أَوْ قَرِينَةٍ","لَهُ أَوْ وَلِيدٍ كُلُّ ذَا كُفْرٌ اعْدُدِ"],["وَيَكْفُرُ أَيْضًا مُدَّعٍ لِنُبُوَّةٍ","وَيَكْفُرُ فِي تَصْدِيقِهِ كُلُّ مُسْعَدِ"],["وَمَنْ حَلَّلَ الْمَحْظُورَ مِنْ غَيْرِ شُبْهَةٍ","عَنِ النَّفْسِ وَالْأَمْوَالِ كَفِّرْهُ تُرْشَدِ"],["وَإِنْ كَانَ بِالتَّأْوِيلِ مِنْهُ اسْتَحَلَّهُ","فَلَا كُفْرَ حَتَّى يَسْتَبِينَ بِمُرْشِدِ"],["وَمَنْ أَكَلَ الْخِنْزِيرَ أَوْ نَحْوَهَا فَلَا","تُكَفِّرْهُ يَا هَذَا بِأَكْلٍ مُجَرَّدِ"],["وَمَنْ أَظْهَرَ الْإِسْلَامَ وَالْكُفْرُ بَاطِنٌ","فَذَلِكَ زِنْدِيقٌ مَتَى تَابَ فَارْدُدِ"],["كَذَا حُكْمُ مَنْ قَدْ كَفَّرُوهُ بِسِحْرِهِ","وَمَنْ يَتَكَرَّرْ كُفْرُهُ بَعْدَ أَنْ هُدِي"],["وَمَنْ سَبَّ رَبَّ الْخَلْقِ أَوْ مُرْسَلًا لَهُ","فَقَتْلَ أُولَاءِ احْتِمْ بِغَيْرِ تَرَدُّدِ"],["وَعَنْ أَحْمَدَ اقْبَلْ تَوْبَةَ الْجَمْعِ إِنْ يُرَى","لَكَ الصِّدْقُ كَالْكُفْرِ الْأَصِيلِيِّ تَهْتَدِ"],["وَمِثْلَ الْمُؤَذِّنِ قُلْ إِذَا مَا سَمِعْتَهُ","وَحَوْقِلْ إِذَا حَيْعَلْ تُثَابُ وَتُرْشَدِ"],["وَعِنْدَ فَرَاغٍ مِنْهُ فَاسْأَلْ وَسِيلَةً","لِخَيْرِ الْوَرَى تُؤْتَى الشَّفَاعَةَ فِي غَدِ"],["وَبَعْدَ النِّدَا قَبْلَ الْإِقَامَةِ فَادْعُوَنْ","يُجَابُ الدُّعَا فِي ذَا بِغَيْرِ تَرَدُّدِ"],["وَمِنْ خَيْرِهِ أَنْ تَسْأَلَ الْعَفْوَ يَا فَتَى","وَعَافِيَةً دُنْيَا وَأُخْرَى أَلَا اجْهَدِ"],["وَفَضْلُ أَذَانِ الْمَرْءِ يَعْلُو إِمَامَةً","وَقَدْ قِيلَ ذَا بِالْعَكْسِ فَاخْتَرْ وَجَوِّدِ"],["وَأَفْضَلُ نَفْلِ الْمَرْءِ لَيْلًا بِبَيْتِهِ","فَقُمْ تِلْوَ نِصْفٍ مِثْلَ دَاوُدَ فَاسْجُدِ"],["وَلَا تُخْلِيَنَّ اللَّيْلَ مِنْ وِرْدِ طَائِعٍ","بِحِزْبِكَ تَتْلُو فِيهِ سِرًّا تُجَوِّدِ"],["وَإِنْ شِئْتَ فَاجْهَرْ فِيهِ مَا لَمْ تَخَفْ أَذًى","لِإِبْعَادِ شَيْطَانٍ وَإِيقَاظِ رُقَّدِ"],["وَخُذْ قَدْرَ طَوْقِ النَّفْسِ لَا تَسْأَمَنَّهُ","وَقِلْ تَسْتَعِنْ بِالنَّوْمِ عِنْدَ التَّهَجُّدِ"],["فَإِنْ لَمْ تُصَلِّ فَاذْكُرِ اللَّهَ جَاهِدًا","وَتُبْ وَاسْتَقِلْ مِمَّا جَنَيْتَ وَسَدِّدِ"],["فَلَا خَيْرَ فِي عَبْدٍ نَؤُومٍ إِلَى الضُّحَى","أَمَا يَسْتَحِي مَوْلًا رَقِيبًا بِمَرْصَدِ"],["يُنَادِيهِ هَلْ مِنْ سَائِلٍ يُعْطَ سُؤْلَهُ","وَمُسْتَغْفِرٍ يُغْفَرْ لَهُ وَيُؤَيَّدِ"],["وَفِي السُّبْعِ فَاخْتِمْ فَهْوَ أَوْلَى وَلَا تَزِدْ","عَلَى الثُّلْثِ فِي يَوْمٍ تُصِبْ سُنَّةَ أَحْمَدِ"],["فَإِنَّ قَلِيلًا مَعْ تَدَبُّرِ قَارِئٍ","أَبَرُّ فَلَا تَهْذُذْ كَشِعْرٍ وَتَسْرُدِ"],["وَلَا تَقْرَأَنْ إِمَّا أَمَمْتَ خِلَافَ مَا","عَلَيْهِ أَهْلُ ذَاكَ الْعَصْرِ تُقْلَ وَتُبْعَدِ"],["وَحَمْزَةَ جَانِبْ وَالْكِسَائِيَّ حَرْفَهُ","فَكِلْتَاهُمَا مَكْرُوهَةٌ فِي الْمُؤَكَّدِ"],["وَيُكْرَهُ أَنْ يَقْرَا بِأَلْحَانِ كَالْغِنَا","وَإِنْ غَيَّرْتَ حَرْفًا فَحَرِّمْ وَشَدِّدِ"],["وَكَيْفَ تَشَا فَاقْرَأْ بِلَا حَدَثٍ عَلَى","وَبِالطُّهْرِ أَوْلَى وَاكْرَهِ الْمَوْضِعَ الرَّدِي"],["وَيَحْرُمُ إِبْدَالُ الْكَلَامِ بِآيَةٍ","تُفِيدُ الَّذِي خَاطَبْتَهُ نَيْلَ مَقْصَدِ"],["وَيُكْرَهُ بَعْدَ الْأَرْبَعِينَ تَأَخُّرٌ","لِخَتْمٍ بِلَا عُذْرٍ عَلَى نَصِّ أَحْمَدِ"],["وَإِنْ خَافَ مِنْ نِسْيَانِهِ احْظُرْ وَسُنَّةٌ","بِأَوَّلِ لَيْلٍ فِي الشِّتَا الْخَتْمُ يَا عَدِي"],["وَفِي الصَّيْفِ فَاعْكِسْ ثُمَّ تَجْمِيعُ أَهْلِهِ","لَدَى الْخَتْمِ مَحْبُوبٌ وَيَدْعُو وَيَحْمَدِ"],["وَيُشْرَعُ لِلشُّكْرِ السُّجُودُ لِطَاهِرٍ","لِمَدْفُوعِ شَرٍّ أَوْ لِفَضْلٍ مُجَدَّدِ"],["وَصَلِّ إِنْ تَرُمْ أَمْرًا صَلَاةَ اسْتِخَارَةٍ","وَإِنْ بَعْدُ بِالْمَأْثُورِ تَدْعُ تُسَدَّدِ"],["وَمَا عَرَضَتْ مِنْ حَاجَةٍ صَلِّ وَابْتَهِلْ","فَكَمْ مُرْسَلٍ قَدْ جَاءَ فِي ذَا وَمُسْنَدِ"],["عَلَى سِتَّةٍ بَيْنَ الْعِشَاءَيْنِ حَافِظَنْ","وَصَلِّ بِتَسْبِيحٍ كَمَا جَاءَ تُحْمَدِ"],["وَيُكْرَهُ قَطْعُ النَّفْلِ مِنْ غَيْرِ حَاجَةٍ","وَعَنْ أَحْمَدٍ حُرِّمْ كَفَرْضٍ مُؤَكَّدِ"],["وَبَادِرْ إِلَى مَحْوِ الذُّنُوبِ بِرَكْعَتَيْ","مَتَابٍ كَمَا قَدْ جَاءَ وَادْعُ تُسَدَّدِ"],["وَإِنَّ عِمَادَ الدِّينِ إِخْلَاصُ نِيَّةٍ","وَإِلَّا تَوَلَّى بِالْعَنَا صَافِرَ الْيَدِ"],["وَإِيَّاكَ عَنْ سَبْقِ الْإِمَامِ فَإِنَّهُ","مُخَالَسَةُ الشَّيْطَانِ عِنْدَ التَّعَبُّدِ"],["سَعَى فِي التَّوَانِي ثُمَّ لَمَّا عَصَيْتَهُ","تَدَارَكَ سَعْيًا فِي فُنُونِ التَّفَسُّدِ"],["وَفِي الْخَمْسِ أَلْزِمْ فِي الْأَصَحِّ الرِّجَالَ بِالْـ","ـجَمَاعَةِ لَا عَبْدًا وَشَرْطًا بِأَوْكَدِ"],["وَلَيْسَ بِمَكْرُوهٍ صَلَاةُ الْعَجَائِزِ الْـ","ـجَمَاعَةَ مَعْنَا بَلْ لِذَاتِ التَّرَادِ"],["وَنَدْبٌ دُعَاءُ الْمَرْءِ خَلْفَ صَلَاتِهِ","بِمَا شَاءَ لِلدُّنْيَا وَلِلدِّينِ فَاجْهَدِ"],["وَإِيَّاكَ وَالتَّفْرِيطَ فِي جُمْعَةٍ بِهَا","قَدِ اخْتَصَّ رَبُّ الْعَرْشِ أُمَّةَ أَحْمَدِ"],["فَفِي يَوْمِهَا يُعْطِي الْمَزِيدَ لِفَائِزٍ","فَيَنْظُرُهُ مِنْ غَيْرِ كَيْفٍ فَقَيِّدِ"],["وَفِي تَرْكِهَا مِنْ غَيْرِ عُذْرٍ ثَلَاثَةً","يُرَانُ عَلَى قَلْبِ الْغَفُولِ الْمُبَعَّدِ"],["وَيُشْرَعُ غُسْلٌ يَوْمَهَا عِنْدَ قَصْدِهَا","وَطِيبٌ وَتَنْظِيفٌ وَلُبْسُ الْمُجَدَّدِ"],["وَتَبْكِيرُ مَاشٍ مُدَّنٍ لِإِمَامِهِ","يُصَلِّي وَيُكْثِرُ مِنْ فُنُونِ التَّعَبُّدِ"],["وَيَدْعُو وَيَقْرَأُ سُورَةَ الْكَهْفِ مُكْثِرًا","صَلَاةً عَلَى خَيْرِ الْأَنَامِ مُحَمَّدِ"],["وَلَا يَتَخَطَّى النَّاسَ إِلَّا إِمَامُهُمْ","وَرَاءٍ مَكَانًا خَالِيًا فِي الْمُؤَكَّدِ"],["وَخُذْ عِلْمَ أَحْكَامِ الزَّكَاةِ نَظِيرَةَ الصَّـ","ـلَاةِ بِآيَاتِ الْكِتَابِ الْمُمَجَّدِ"],["وَحَسْبُكَ فِي تَفْضِيلِهَا نَفْعُ غَيْرِهِ","بِقَهْرِ هَوًى وَسْوَاسُهُ لَمْ يُرَدَّدِ"],["وَفِرْقَةُ مَا تَهْوَى امْتِثَالًا بِبَذْلِهَا","يَفُكُّ الْفَتَى سَبْعِينَ لَحْيٍ مُفَنَّدِ"],["وَأَدِّ زَكَاةَ الْمَالِ حَيًّا مُطَيِّبًا","وَلَا تَتْرُكَنْ لِلشَّامِتِينَ وَحُسَّدِ"],["وَيُشْرَعُ فِي قُرْبَاكَ مَنْ لَيْسَ وَارِثًا","عَلَى قَدْرِ حَاجَاتٍ وَقُرْبٍ لِيُمْدَدِ"],["وَمِنْ بَعْدِهِمْ ذَا الْعِلْمِ وَالْجَارَ قَدِّمَنْ","وَرَاعِ ذَوِي الْحَاجَاتِ وَالسِّتْرِ تُرْشَدِ"],["وَلَيْسَ بِمُجْزٍ دَفْعُهَا لِشَرِيكِهِ","وَلَا مَنْ يَعُولَنْ مِنْ قَرِيبٍ وَمُبْعَدِ"],["وَلَا كَفَنُ الْمَوْتَى وَلَا فِي دُيُونِهِمْ","وَلَا نَحْوُ سَدِّ الْبَثْقِ أَوْ رَمِّ مَسْجِدِ"],["وَيَحْرُمُ حَتْمًا أَنْ يَقِي مَالَهُ بِهَا","وَيَدْفَعُ ذَمًّا أَوْ لِتَحْصِيلِ مَحْمَدِ"],["وَذَلِكَ نَفْلُ الْبِرِّ سِرًّا بِفَاضِلٍ","عَنِ النَّفْسِ مَعْ قُوتِ الْعِيَالِ الْمُؤَكَّدِ"],["يُسَنُّ وَفِي الْحَاجَاتِ أَوْ شَهْرِ صَوْمِهِمْ","وَلِلْجَارِ وَالْقُرْبَى وَإِنْ يُؤْذِ أَكِّدِ"],["وَيَأْثَمُ فِي إِضْرَارِ نَفْسٍ وَعَيْلَةٍ","وَمَطْلِ غَرِيمٍ فِي التَّقَاضِي مُلَدِّدِ"],["وَإِنْ تَكُ ذَا صَبْرٍ وَحُسْنِ تَوَكُّلٍ","وَتَرْكِ سُؤَالٍ بِالْجَمِيعِ انْ تَشَا جُدِ"],["وَإِلَّا تَكُنْ تَأْثَمْ بِبَذْلِ جَمِيعِهِ","وَيُكْرَهُ تَضْيِيقٌ لِغَيْرِ الْمُعَوَّدِ"],["وَجَوِّزْ سُؤَالَ الْمَرْءِ مَا جَازَ أَخْذُهُ","وَعَنْهُ احْظُرَنْ عَنْ ذِي الْعَشَا وَالْغَدَا قِدِ"],["وَمَا جَا بِلَا اسْتِشْرَافِ نَفْسٍ وَطَلْبِهِ","يُسَنُّ وَلَمْ يُوجَبْ قَبُولٌ بِأَوْكَدِ"],["وَيُكْرَهُ بِاسْتِشْرَافِ نَفْسٍ وَجَائِزٌ","عَلَى الْكُفْرِ بَذْلُ الْبِرِّ فِي نَصِّ أَحْمَدِ"],["وَخُذْ فِي بَيَانِ الصَّوْمِ غَيْرَ مُقَصِّرٍ","عِبَادَةَ سِرٍّ ضِدَّ طَبْعٍ مُعَوَّدِ"],["وَصَبْرٍ لِفَقْدِ الْإِلْفِ مِنْ حَالَةِ الصَّبِي","وَفَطْمٍ عَنِ الْمَحْبُوبِ وَالْمُتَعَوَّدِ"],["فَتُوفِيهِ بِالْوَعْدِ الْقَدِيمِ مِنَ الَّذِي","لَهُ الصَّوْمُ يُجْزِي غَيْرَ مُخْلِفِ مَوْعِدِ"],["وَحَافِظْ عَلَى شَهْرِ الصِّيَامِ فَإِنَّهُ","لَخَامِسُ أَرْكَانٍ لِدِينِ مُحَمَّدِ"],["تُغَلَّقُ أَبْوَابُ الْجَحِيمِ إِذَا أَتَى","وَتُفْتَحُ أَبْوَابُ الْجِنَانِ لِسُعَّدِ"],["وَيُرْفَعُ عَنْ أَهْلِ الْقُبُورِ عَذَابُهُمْ","وَيُصْفَدُ فِيهِ كُلُّ شَيْطَانٍ مُعْتَدِ"],["وَيُبْسَطُ فِيهِ الرِّزْقُ لِلْخَلْقِ كُلِّهِمْ","وَيَسْهُلُ فِيهِ فِعْلُ كُلِّ تَعَبُّدِ"],["تُزَخْرَفُ جَنَّاتُ النَّعِيمِ وَحُورُهَا","لِأَهْلِ الرِّضَى فِيهِ وَأَهْلِ التَّهَجُّدِ"],["وَقَدْ خَصَّهُ اللَّهُ الْعَظِيمُ بِلَيْلَةٍ","عَلَى أَلْفِ شَهْرٍ فُضِّلَتْ فَلْتُرَصَّدِ"],["فَأَرْغِمْ بِأَنْفِ الْقَاطِعِ الشَّهْرَ غَفْلَةً","وَأَعْظِمْ بِأَجْرِ الْمُخْلِصِ الْمُتَعَبِّدِ"],["فَقُمْ لَيْلَهُ وَاقْطَعْ نَهَارَكَ صَائِمًا","وَصُنْ صَوْمَهُ عَنْ كُلِّ مَوْهٍ وَمُفْسِدِ"],["وَتَرْكُ مَقَالِ الزُّورِ فِي النَّاسِ وَاجِبٌ","وَلَكِنَّهُ مِنْ صَائِمٍ ذُو تَأَكُّدِ"],["فَإِنْ شُتِمَ اشْرَعْ قَوْلَهُ أَنَا صَائِمٌ","لِتَذْكِيرِ نَفْسٍ أَوْ لِوَعْظٍ لِمُعْتَدِ"],["وَمَنْ خَافَ مِنْ جُوعٍ وَمِنْ عَطَشٍ وَمِنْ","أَذَى شَبَقٍ يُفْطِرُ وَيَقْضِي وَلَا يَدِي"],["وَإِنْ تَبْغِ أَسْنَى الصَّوْمِ نَفْلًا تَصُومُهُ","فَيَوْمًا وَيَوْمًا صَوْمُ دَاوُدَ فَاقْصِدِ"],["وَمِنْ كُلِّ شَهْرٍ صُمْ ثَلَاثَةَ بِيضِهِ","وَيَوْمَ خَمِيسٍ ثُمَّ الِاثْنَيْنِ فَاعْمِدِ"],["وَمُتْبِعِ شَهْرِ الصَّوْمِ صَوْمًا بِسِتَّةٍ","جَزَتْ سَنَةً مِنْ جَامِعٍ وَمُبَدِّدِ"],["وَعَامَيْنِ يُجْزِي صَوْمُ يَوْمٍ مُعَرَّفٍ","وَعَنْ يَوْمِ عَاشُورَاءَ بِالْعَامِ أَسْنِدِ"],["وَفِي عَرَفَاتٍ يُشْرَعُ الْفِطْرُ قُوَّةً","عَلَى دَعَوَاتٍ عِنْدَ أَفْضَلِ مَشْهَدِ"],["وَيُشْرَعُ صَوْمُ الْعَشْرِ وَالشَّهْرِ كَامِلًا","إِذَا كُنْتَ تَبْغِي فَالْمُحَرَّمُ فَاسْرُدِ"],["فَإِنْ تَقْتَصِرْ صُمْ عَشْرَهُ ثُمَّ إِنْ تَهُنْ","فَتَاسِعَهُ مَعْ عَاشِرٍ أَوْ لِذَا قِدِ"],["وَيُكْرَهُ صَوْمُ الدَّهْرِ وَالسَّبْتِ وَحْدَهُ","وَإِفْرَادُ تَرْجِيبٍ وَجُمْعَةِ مُفْرَدِ"],["وَيَحْسُنُ إِتْمَامُ التَّطَوُّعِ مُطْلَقًا","وَإِفْسَادَهُ جَوِّزْ فَإِنْ تَقْضِ جَوِّدِ"],["وَبَادِرْ بِفَرْضِ الْعُمْرِ قَبْلَ انْقِضَائِهِ","بِحَجٍّ إِلَى الْبَيْتِ الْعَتِيقِ الْمُؤَكَّدِ"],["وَمَا الْحَجُّ إِلَّا الْقَصْدُ قَصْدٌ مُخَصَّصٌ","عِبَادَةُ إِذْعَانٍ وَمَحْضُ تَعَبُّدِ"],["تَحِنُّ الْقُلُوبُ الْمُسْتَجَابُ لَهَا الدُّعَا","إِلَى الصَّادِقِ الْبَرِّ الْخَلِيلِ الْمُمَجَّدِ"],["أَتَى بِخُصُوصٍ فِي الدُّعَاءِ مُبَعِّضًا","وَلَوْ عَمَّ طَارَ الشَّوْقُ بِالنَّاسِ عَنْ يَدِ"],["تَحِنُّ إِلَى أَعْلَامِ مَكَّةَ دَائِمًا","قُلُوبٌ إِلَى الدَّاعِي تَرُوحُ وَتَغْتَدِي"],["رِجَالًا وَرُكْبَانًا عَلَى كُلِّ ضَامِرٍ","يُلَبُّونَ دَاعِيَ الْحَقِّ مِنْ كُلِّ مَوْرِدِ"],["يَطِيرُ بِهِمْ شَوْقًا إِلَى ذَلِكَ الْحِمَى","لِتَحْصِيلِ وَعْدِ النَّفْعِ فِي خَيْرِ مَشْهَدِ"],["عَلَى كُلِّهِمْ قَدْ هَانَ نَفْسٌ عَزِيزَةٌ","وَأَهْلٌ وَمَالٌ مِنْ طَرِيفٍ وَمُتْلَدِ"],["رَضُوا عَنْ مَدِيدِ الظِّلِّ قَطْعَ مَهَامِهٍ","يَظَلُّ بِهَا نِحْرِيرُهَا لَيْسَ يَهْتَدِي"],["وَلَذَّ لَهُمْ فِي جَنْبِ مَا يَبْتَغُونَهُ","سَمُومٌ بِجَهْلَاءِ الْمَعَالِمِ صَيْخَدِ"],["يَهُونُ بِهَا لَفْحُ الْهَجِيرِ عَلَيْهِمُ","كَهَجْرِ مُحِبٍّ يَرْتَجِي صِدْقَ مَوْعِدِ"],["وَكُلُّ مُحِبٍّ قَابَلَ الْهَجْرَ بِالرِّضَا","سَيَجْنِي بِمَا يَرْضَاهُ مِنْ كُلِّ مَقْصَدِ"],["فَكَمْ مِنْ رَخِيِّ الْعَيْشِ حَرَّكَهُ الْهَوَى","فَقَامَ بِأَعْبَاءِ الرَّجَا سَاغِبًا صَدِ"],["فَلَيْسَ بِثَانٍ عَزْمَهُ عَنْ طِلَابِهِ","إِذَا ثَوَّبَ الدَّاعِي بِهِ وَصْلَ خُرَّدِ"],["أَطَارَ الْكَرَى عَنْهُمْ رَجَاءَ وِصَالِهِمْ","وَشَوْقًا إِلَى قَبْرِ النَّبِيِّ مُحَمَّدِ"],["عَفَا اللَّهُ عَنِّي كَمْ أُوَدِّعُ سَائِرًا","إِلَيْهِ وَذَنْبِي حَابِسِي وَمُقَيِّدِي"],["تَحَمَّلْتُ أَوْزَارًا تُثَقِّلُ مَنْهَضِي","وَلَكِنَّنِي أَرْجُو تَجَاوُزَ سَيِّدِي"],["وَظَنِّي جَمِيلٌ بِالْكَرِيمِ وَعُدَّتِي","شَفِيعُ الْوَرَى فِي مَوْقِفِ الْحَشْرِ فِي غَدِ"],["لَئِنْ ثَنَتِ الْأَقْدَارُ عَزْمِي عَنِ السُّرَى","فَشَوْقِي إِلَيْهِ دَائِمٌ وَتَلَدُّدِي"],["وَإِنَّ رَجَائِي أَنْ يَمُنَّ بِزَوْرَةٍ","فَأَبْلُغُ مِنْ تِلْكَ الْمَشَاعِرِ مَقْصِدِي"],["وَأَلْثِمُ آثَارَ النَّبِيِّينَ ضَارِعًا","وَأَبْسُطُ كَفِّي لِلدُّعَاءِ وَأَجْهَدِ"],["وَمَنْ حَجَّ بِالْمَالِ الْحَرَامِ يُعِيدُهَا","كَذَلِكَ مُرْتَدٌّ أَنَابَ بِأَوْكَدِ"],["وَلِلرَّفَثِ اهْجُرْ وَالْفُسُوقِ وَهَكَذَا الْـ","ـجِدَالُ وَأَقْلِلْ مِنْ كَلَامِكَ تُحْمَدِ"],["وَمَكَّةُ بِالتَّفْضِيلِ أَوْلَى وَعَنْهُ بَلْ","مَدِينَةُ خَيْرِ الْخَلْقِ مَثْوَى مُحَمَّدِ"],["وَكِلْتَا يَدَيْكَ ارْفَعْ لِرُؤْيَةِ كَعْبَةٍ","مُعَظَّمَةٍ عُلْيَا وَكَبِّرْ وَمَجِّدِ"],["وَنَادِ بِقَلْبٍ خَاشِعٍ مُتَضَرِّعًا","بِمَا شِئْتَ مِنْ كُلِّ الدُّعَا غَيْرَ مُعْتَدِ"],["وَسَلْهُ قَبُولَ الْحَجِّ وَالْعَفْوِ وَادْعُهُ","وَكَبِّرْ وَهَلِّلْ فِي مُحَاذَاةِ أَسْوَدِ"],["وَنَدْبٌ لَهُ أَنْ يَدْخُلَ الْبَيْتَ حَافِيًا","وَيُكْثِرَ مِنْ نَفْلٍ بِهِ وَتَعَبُّدِ"],["وَيَرْمُقُهُ مَا اسْطَاعَ ثَمَّ بِطَرْفِهِ","وَيُكْثِرُ فِعْلَ الِاعْتِمَارِ وَيَجْهَدِ"],["وَمِنْ زَمْزَمٍ فَاشْرَبْ بِمَا شِئْتَ مُمْعِنًا","وَسَمِّ وَسَلْ مَا تَبْتَغِي وَتَزَوَّدِ"],["وَعِنْدَ خُرُوجٍ طُفْ طَوَافَ مُوَدِّعٍ","وَقِفْ بَعْدُ بَيْنَ الْبَابِ وَالرُّكْنِ تُرْشَدِ"],["وَنَادِ كَرِيمًا قَدْ دَعَا وَفْدَهُ إِلَى","جَوَائِزِهِ فِي بَيْتِهِ فَادْعُ وَاجْهَدِ"],["وَقُلْ يَا إِلَهِي قَدْ أَتَيْنَاكَ نَرْتَجِي","مَوَاعِيدَ صِدْقٍ مِنْ كَرِيمٍ مُعَوِّدِ"],["وَهَذَا مَقَامُ الْمُسْتَجِيرِينَ مِنْ لَظَى","بِعَفْوِكَ يَا مَنَّانُ يَا ذَا التَّغَمُّدِ"],["بِعَوْنِكَ جِئْنَا فَوْقَ كُلِّ مُسَخَّرٍ","فَجُدْ بِالرِّضَا يَا رَبِّ قَبْلَ التَّبَعُّدِ"],["فَهَذَا أَوَانُ السَّيْرِ عَنْ بَيْتِكَ الَّذِي","نُفَارِقُهُ كُرْهًا مَتَى شِئْتَ نَفْتَدِي"],["فِرَاقَ اضْطِرَارٍ لَا فِرَاقَ زَهَادَةٍ","وَلَا رَغْبَةً عَنْهُ وَلَا عَنْكَ سَيِّدِي"],["وَلَيْسَ لَنَا وَالْحَمْدُ لِلَّهِ رَغْبَةٌ","سِوَاكَ فَأَصْبَحْنَا بِمُغْنِي التَّزَوُّدِ"],["وَلَا تَجْعَلَنْهُ آخِرَ الْعَهْدِ بَيْنَنَا","وَهَوِّنْ عَلَيْنَا السَّيْرَ فِي كُلِّ فَدْفَدِ"],["وَسَلْ كُلَّ مَا تَبْغِي مِنَ الدِّينِ وَالدُّنَا","تَنَلْهُ مَتَى تَدْعُو بِصِدْقِ تَقَصُّدِ"],["وَصَلِّ عَلَى خَيْرِ النَّبِيِّينَ كُلَّمَا","دَعَوْتَ يَكُنْ أَحْرَى لِتَحْصِيلِ مَقْصَدِ"],["وَبَعْدَ فَرَاغِ الْحَجِّ فَانْوِ زِيَارَةً","لِخَيْرِ الْبَرَايَا مَعْ ضَجِيعَيْهِ فَاقْصِدِ"],["وَيُكْرَهُ مَسُّ الْقَبْرِ يَا صَاحِ مُطْلَقًا","وَقُمْ قِبْلَةً وَالْمِنْبَرَ الْيُسْرَةَ احْدُدِ"],["وَصَلِّ وَسَلِّمْ فِي حَرِيمِ ضَرِيحِهِ","عَلَيْهِمْ وَسَلْ مُسْتَشْفِعًا بِمُحَمَّدِ"],["عَلَيْهِ صَلَاةُ اللَّهِ ثُمَّ سَلَامُهُ","وَأَصْحَابِهِ وَالْآلِ مِنْ كُلِّ أَمْجَدِ"],["وَإِنَّ جِهَادَ الْكُفْرِ فَرْضُ كِفَايَةٍ","وَيَفْضُلُ بَعْدَ الْفَرْضِ كُلَّ تَعَبُّدِ"],["لِأَنَّ بِهِ تَحْصِينَ مِلَّةِ أَحْمَدٍ","وَفَضْلَ عُمُومِ النَّفْعِ فَوْقَ الْمُقَيَّدِ"],["فَلِلَّهِ مَنْ قَدْ بَاعَ لِلَّهِ نَفْسَهُ","وَجُودُ الْفَتَى بِالنَّفْسِ أَقْصَى التَّجَوُّدِ"],["وَمَنْ يَغْدُ إِنْ يَغْنَمْ فَأَجْرٌ وَمَغْنَمٌ","وَإِنْ يَرْدَ يَظْفَرْ بِالنَّعِيمِ الْمُخَلَّدِ"],["وَمَا مُحْسِنٌ يَبْغِي إِذَا مَاتَ رُجْعَةً","سِوَى الشُّهَدَا كَيْ يَجْهَدُوا فِي التَّزَيُّدِ"],["لَفَضْلُ الَّذِي أُعْطُوا وَنَالُوا مِنَ الرِّضَى","يَفُوقُ الْأَمَانِيَ فِي النَّعِيمِ الْمُسَرْمَدِ"],["كَفَى أَنَّهُمْ أَحْيَا لَدَى اللَّهِ رُوحُهُمْ","تَرُوحُ بِجَنَّاتِ النَّعِيمِ وَتَغْتَدِي"],["وَغَدْوَةُ غَازٍ أَوْ رَوَاحُ مُجَاهِدٍ","فَخَيْرٌ مِنَ الدُّنْيَا بِقَوْلِ مُحَمَّدِ"],["يُكَفَّرُ عَنْ مُسْتَشْهِدِ الْبَرِّ مَا عَدَا","حُقُوقَ الْوَرَى وَالْكُلُّ فِي الْبَحْرِ فَاجْهَدِ"],["وَقَدْ سُئِلَ الْمُخْتَارُ عَنْ حَرِّ قَتْلِهِمْ","فَقَالَ يَرَاهُ مِثْلَ قَرْصَةِ مُفْرَدِ"],["كُلُومُ غُزَاةِ اللَّهِ أَلْوَانُ نَزْفِهَا","دَمٌ وَكَمِسْكٍ عَرْفُهَا فَاحَ فِي غَدِ"],["وَلَمْ يَجْتَمِعْ فِي مِنْخَرِ الْمَرْءِ يَا فَتَى","غُبَارُ جِهَادٍ مَعْ دُخَانِ لَظَى الصَّدِي"],["كَمَنْ صَامَ لَمْ يُفْطِرْ وَقَامَ فَلَمْ يَنَمْ","جِهَادُ الْفَتَى فِي الْفَضْلِ عِنْدَ التَّعَدُّدِ"],["فَشَتَّانَ مَا بَيْنَ الضَّجِيعِ بِفَرْشِهِ","وَسَاهِرِ طَرْفٍ لَيْلُهُ فَوْقَ أَجْرَدِ"],["يُدَافِعُ عَنْ أَهْلِ الْهُدَى وَحَرِيمِهِمْ","وَأَمْوَالِهِمْ بِالنَّفْسِ وَالْمَالِ وَالْيَدِ"],["وَمَنْ قَاتَلَ الْأَعْدَاءَ لِإِعْلَاءِ دِينِنَا","فَذَا فِي سَبِيلِ اللَّهِ لَا غَيْرَ قَيِّدِ"],["وَيَفْضُلُ غَزْوُ الْبَحْرِ غَزْوَ مَفَاوِزٍ","وَمَعْ فَاجِرٍ يُحْتَاطُ فَاغْزُ كَأَرْشَدِ"],["وَمَنْ يَبْغِ نَفْسَ الْمَرْءِ أَوْ مَالَهُ أَوِ الْـ","ـحَرِيمَ بَهِيمٌ أَوْ فَتًى طَالِبُ الرَّدِ"],["فَأَوْجِبْ دِفَاعًا عَنْ حَرِيمِ الْمُطِيقِ لَا","عَنِ الْمَالِ وَالْقَوْلَيْنِ فِي النَّفْسِ أَوْرِدِ"],["وَرَجَّحَ الِاسْتِسْلَامَ فِي الْهَرْجِ شَيْخُنَا","وَحَتِّمْ دِفَاعَ اللِّصِّ وَالْعِصْمَ قَلِّدِ"],["وَيَدْفَعُ بِالْأَدْنَى مَتَى ظَنَّ دَفْعَهُ","بِذَاكُمْ وَإِلَّا فَلْيَزِدْ وَلْيُشَدِّدِ"],["فَتَبْدَا بِوَعْظٍ ثُمَّ تَضْرِبُ بِالْعَصَا","فَإِنْ لَمْ يُفِدْ فَلْيَفْرِهِ بِالْمُحَدَّدِ"],["وَقَاتِلْهُ بِالنُّشَّابِ إِنْ خِفْتَ كَيْدَهُ","إِذَا مَا دَنَا فَادْفَعْ بِمَا شِئْتَ وَاطْرُدِ"],["وَإِنْ نِلْتَهُ بَعْدَ اكْتِفَائِكَ شَرَّهُ","تُضَمَّنُ مَا يَنْشَا عَنِ الْمُتَزَيِّدِ"],["وَلَا شَيْءَ فِي الْعَادِي الْقَتِيلِ بِجَائِلٍ","وَمَنْ قَتَلَ الْعَادِي شَهِيدًا لِيُعْدَدِ"],["وَلَا فَرْقَ بَيْنَ اللِّصِّ يَدْخُلُ دَارَهُ","وَمَنْ صَالَ عُدْوَانًا عَلَيْهِ بِفَدْفَدِ"],["وَلَا بَيْنَ أَدْنَى مَالِهِ وَكَثِيرِهِ","وَمَنْ دَفَعَ الْمُضْطَرَّ عَنْهُ فَمُعْتَدِي"],["وَأَوْجِبْ فِي الْأَقْوَى الدَّفْعَ عَنْ مَالِهَا لِذِي","لَهُ اضْطُرَّ مِثْلُ الْأَكْلِ مِنْهُ بِأَجْوَدِ"],["وَيَلْزَمُ مَنْ يَقْوَى عَلَى دَفْعِ صَائِلٍ","عَلَى غَيْرِهِ دَفْعٌ لِأَمْنٍ مِنَ الرَّدِي"],["وَلَا شَيْءَ فِيمَا جَوَّزَ الصَّوْلُ قَتْلَهُ","مُكَلَّفُ أَوْ عَجْمَا وَبُلْهٌ وَفُوهَدِ"],["وَلَا غُرْمَ فِي الْمَقْتُولِ دَفْعًا لِشَرِّهِ","إِذَا لَمْ يُفَرِّطْ قَاتِلٌ فِي التَّزَيُّدِ"],["وَمَنْ رَبَطَ الْعَجْمَاءَ فِي ضَيِّقٍ مِنَ الدُّ","رُوبِ لِيَضْمَنْ مَا جَنَتْ لَا تُقَيَّدِ"],["وَقَوْلَانِ بِالْإِطْلَاقِ إِنْ كَانَ وَاسِعًا","كَذَا فِي اقْتِنَا كَلْبٍ عَقُورٍ بِأَجْوَدِ"],["كَذَا الْحُكْمُ فِي هِرٍّ يَصِيدُ الطُّيُورَ لَا","إِذَا بَالَ فِي شَيْءٍ وَوَلْغِ الَّذِي ابْتُدِي"],["وَإِنْ يُوقِدِ الْإِنْسَانُ نَارًا بِمِلْكِهِ","وَيُجْرِي عَلَيْهِ مَاءَهُ غَيْرَ مُعْتَدِ"],["فَلَيْسَ عَلَيْهِ غُرْمُ تَاوٍ لِجَارِهِ","بِهِ مَعْ سِوَى تَفْرِيطِهِ وَالتَّزَيُّدِ"],["وَيُمْنَعُ مِنْ إِنْشَا مُضِرٍّ بِجَارِهِ","وَيَضْمَنُ مَا أَرْدَى بِحَظْرٍ مُجَدَّدِ"],["وَلَا غُرْمَ فِي مُلْقَى مَمَرٍّ بِمُوحِلٍ","وَأَشْبَاهِهِ مِنْ نَافِعٍ غَيْرِ مُفْسِدِ"],["وَيَضْمَنُ مُنْشِي مَا يَضُرُّ بِمَسْلَكٍ","وَمِنْ قِشْرِ بِطِّيخٍ وَمَاءٍ مُبَدَّدِ"],["وَمَنْ يُدْخِلِ الْإِنْسَانَ حَتَّى يُضِيفَهُ","فَيَسْقُطْ بِبِئْرٍ عِنْدَهُ لَمْ يُحَدَّدِ"],["وَلَمْ يَرَ إِمَّا لِلْعَمَى أَوْ لِسَتْرِهَا","فَضَمِّنْهُ مَا لَمْ يُنْذِرِ الْمَرْءَ تُرْشَدِ"],["وَمَنْ يَغْتَصِبْ أَرْضًا فَحَظِّرْ دُخُولَهَا","عَلَى غَيْرِ رَبِّ الْأَرْضِ إِنْ حُوِّطَتْ قِدِ"],["وَإِنْ لَمْ تُحَوَّطْ جَازَ فِيهَا دُخُولُهُ","وَأَخْذُ الْكَلَا مِنْهَا عَلَى نَصِّ أَحْمَدِ"],["وَإِيَّاكَ إِيَّاكَ الرِّبَا فَلَدِرْهَمٌ","أَشَدُّ عِقَابًا مِنْ زِنَاكَ بِنُهَّدِ"],["وَتُمْحَقُ أَمْوَالُ الرِّبَاءِ وَإِنْ نَمَتْ","وَيَرْبُو قَلِيلُ الْحِلِّ فِي صِدْقِ مَوْعِدِ"],["وَآكِلُهُ مَعْ مُوكِلٍ مَعَ كَاتِبٍ","فَقَدْ جَاءَ فِيهِ لَعْنُهُمْ مَعَ شُهَّدِ"],["وَإِنْ تَقْتَرِضْ شَيْئًا فَنَدْبٌ مُضَاعَفٌ","كَمِثْلَيْنِ إِلَّا خَمْسَ بَذْلِ التَّجَوُّدِ"],["وَإِنْ تَقْتَرِضْ أَحْسِنْ وَفَاءً لِمُقْرِضٍ","فَإِنَّ خِيَارَ النَّاسِ أَحْسَنُ مَرْدَدِ"],["وَيُكْرَهُ الِاسْتِقْرَاضُ لِلسَّيِّئِ الْوَفَا","وَلِلسَّهْلِ لَا بَأْسٌ وَبِالشَّارِعِ اقْتَدِ"],["أَلَا حَبَّذَا الْمَالُ الْحَلَالُ لِمَنْ هُدِي","إِلَى الْبَذْلِ فِي أَبْوَابِ بِرٍّ مُعَوَّدِ"],["وَذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَنْ يَشَا","وَمِنْ خَيْرِ بِرِّ الْمَرْءِ وَقْفُ مُؤَبَّدِ"],["إِذَا انْقَطَعَتْ أَعْمَالُ بِرِّ الْفَتَى أَتَى","إِلَيْهِ أَنِيسًا عِنْدَ وَحْشَةِ مُفْرَدِ"],["وَمِنْ أَعْظَمِ الْمَنْدُوبِ عِتْقٌ وَخَيْرُهُ","عَبِيدٌ وَعَنْهُ بَلْ إِمَاءٌ لِخُرَّدِ"],["حَقِيقٌ بِأَنْ تَسْعَى لِعِتْقٍ مُعَبَّدٍ","لِتُعْتَقَ مِنْ نَارِ الْجَحِيمِ وَتَقْتَدِي"],["وَنَدْبٌ بِلَا خُلْفٍ عِتَاقَةُ دَيِّنٍ","قَوِيٍّ لَهُ كَسْبٌ أَمِينُ التَّفَرُّدِ"],["فَلَا تَكُ جَمَّاعًا مَنُوعًا مُكَاثِرًا","وَسَارِعْ لِبَذْلِ الْمَالِ فِي الْفَرْضِ وَابْتَدِي"],["وَإِيَّاكَ وَالْمَالَ الْحَرَامَ مُوَرِّثًا","لِبَاذِلِهِ فِي الْبِرِّ تَشْقَ وَيَسْعَدِ"],["تُعَدُّ لَعَمْرِي أَخْسَرَ النَّاسِ صَفْقَةً","وَأَكْثَرَهُمْ غُبْنًا وَعَضًّا عَلَى الْيَدِ"],["فَبَادِرْ إِلَى تَقْدِيمِ مَالِكَ طَائِعًا","صَحِيحًا شَحِيحًا رَغْبَةً فِي التَّزَوُّدِ"],["وَلَا تَخْشَ فَوْتَ الرِّزْقِ فَاللَّهُ ضَامِنٌ","لَكَ الرِّزْقَ مَا أَبْقَاكَ فِي الْيَوْمِ وَالْغَدِ"],["أَلَا إِنَّ ذِي الْأَمْوَالَ فِي الْأَرْضِ مِنْحَةٌ","كَمِنْحَةِ مَنْ يُجْدِي النَّوَالَ وَيَجْتَدِي"],["بِهَا يُعْرَفُ الْمَرْءُ السَّخِيُّ مِنَ الْفَتَى الْـ","ـبَخِيلِ وَذُو الْأَطْمَاعِ مِنْ ذِي التَّزَهُّدِ"],["وَيُعْرَفُ أَرْبَابُ الْأَمَانَاتِ عِنْدَهَا","وَكُلُّ خَؤُونٍ بِالتَّصَنُّعِ يَرْتَدِي"],["يُرِي النَّاسَ أَبْوَابَ التَّزَهُّدِ حِلْيَةً","وَيَسْعَى لِتَحْصِيلِ الْحُطَامِ الْمُزَهِّدِ"],["لَهُ وَثَبَاتٌ فِي اكْتِسَابِ حُطَامِهِ","وَلَوْ مَلَكَ الطُّوفَانَ لَمْ يُسْقَ مِنْ صَدِي"],["تَعَالَى الْكَرِيمُ اللَّهُ عَنْ أَنْ يُرَى لَهُ","وَلِيٌّ بَخِيلٌ قَابِضُ الْكَفِّ وَالْيَدِ"],["فَشَرُّ خِلَالِ الْمَرْءِ حِرْصٌ وَبُخْلُهُ","مِنَ اللَّهِ يُقْصِيهِ فَيَا وَيْلَ مُبْعَدِ"],["وَإِنَّ كَرِيمَ النَّاسِ فِيهِمْ مُحَبَّبٌ","قَرِيبٌ مِنَ الْحُسْنَى بَعِيدٌ مِنَ الرَّدِي"],["يُغَطِّي عُيُوبَ الْمَرْءِ فِي النَّاسِ جُودُهُ","وَيُخْمِلُ ذِكْرَ النَّابِهِ الْبُخْلُ فَابْعِدِ"],["فَسَارِعْ إِلَى كَسْبِ الْمَعَالِي وَدَعْ فَتًى","تَوَانَى عَنِ الْعَلْيَا لِكَسْبِ مُصَرِّدِ"],["فَمَا الْمَالُ إِلَّا كَالظِّلَالِ تَنَقُّلًا","فَبَادِرْ إِلَى الْإِنْفَاقِ قَبْلَ التَّشَرُّدِ"],["وَلَا تَحْسَبَنَّ الْبَذْلَ يَنْقُصُ مَا أَتَى","وَلَا الْبُخْلَ جَلَّابَ الْغِنَى وَالتَّزَيُّدِ"],["وَلَا تُوعِيَنْ يُوعَى عَلَيْكَ وَأَنْفِقَنْ","يُوَسِّعْ عَلَيْكَ اللَّهُ رِزْقًا وَتَرْفِدِ"],["فَلَا تَدَعَنْ بَابًا مِنَ الْبِرِّ مُغْلَقًا","تُلَاقِ غَدًا بَابَ الرِّضَى غَيْرَ مُؤْصَدِ"],["وَتَمْلِيكُ مَالِ الْمَرْءِ حَالَ حَيَاتِهِ","بِلَا عِوَضٍ يُدْعَى هِبَاتِ التَّجَوُّدِ"],["وَتِلْكَ لَعَمْرِي مِنْحَةٌ مُسْتَحَبَّةٌ","تُؤَلِّفُ مَا بَيْنَ الْوَرَى مَعْ تَبَعُّدِ"],["تَسُلُّ سَخِيمَاتِ الْقُلُوبِ وَتَزْرَعُ الْـ","ـمَحَبَّةَ فِيهَا لِلْفَتَى الْمُتَجَوِّدِ"],["وَتَخْصِيصُ ذِي عِلْمٍ بِهَا وَقَرَابَةٍ","أَبَرُّ وَمَنْ بَاهَى بِهَا اكْرَهْ وَفَنِّدِ"],["وَكُنْ عَالِمًا أَنَّ الْقُضَاةَ ثَلَاثَةٌ","فَقَاضٍ قَمِينٌ بِالنَّعِيمِ الْمُخَلَّدِ"],["وَذَلِكَ مَنْ بِالْحَقِّ أَصْبَحَ عَالِمًا","وَيَعْدِلُ فِي حُكْمِ الْقَضَايَا فَيَهْتَدِي"],["وَقَاضٍ بِحُكْمِ الْحَقِّ أَصْبَحَ عَالِمًا","وَلَكِنَّهُ فِيهِ يَجُورُ وَيَعْتَدِي"],["وَآخَرُ يَقْضِي جَاهِلًا فَكِلَاهُمَا","لَهُ النَّارُ فِي نَصِّ الْحَدِيثِ الْمُسَدَّدِ"],["وَكُلُّ جَهُولٍ بِالْقَضَاءِ فَإِنَّهُ","حَرَامٌ عَلَيْهِ فَلْيُحَذَّرْ وَيُوعَدِ"],["فَخُذْ فِي سَبِيلٍ لِلسَّلَامَةِ وَاجْتَنِبْ","تَوَلِّي الْقَضَا وَاحْفَظْ لِنَفْسِكَ وَارْتَدِ"],["فَكُلُّ وِلَايَاتِ الْأَنَامِ نَدَامَةٌ","سِوَى مَنْ وَقَى اللَّهُ الْمُهَيْمِنُ فِي غَدِ"],["وَحَسْبُ فَتًى يَرْجُو السَّلَامَةَ زَاجِرًا","سُؤَالٌ عَنِ الْمَرْعِيِّ فَافْقَهْ تُسَدَّدِ"],["أَمَا عُمَرُ الْحَبْرُ الْمُسَدَّدُ قَائِلٌ","أَلَا لَيْتَنِي أَنْجُو كَفَافًا مِنَ الرَّدِي"],["وَكُنْ عَالِمًا أَنَّ الْقَضَاءَ فَضِيلَةٌ","وَأَجْرٌ عَظِيمٌ لِلْمُحِقِّ الْمُؤَيَّدِ"],["لِأَمْرٍ بِمَعْرُوفٍ وَكَشْفِ ظُلَامَةٍ","وَإِصْلَاحِ ذَاتِ الْبَيْنِ مَعْ زَجْرِ مُعْتَدِ"],["إِذَا بَذَلَ الْجُهْدَ الْمُحِقُّ انْ يُصِبْ يَفُزْ","بِأَجْرَيْنِ وَالْمُخْطِي لَهُ وَاحِدٌ قِدِ"],["وَحَظِّرْ عَلَيْهِ الِارْتِشَا وَقَبُولَهُ","وَأَنْتَ لِدَفْعِ الظُّلْمِ فَارْشُ لِتَفْتَدِي"],["وَيُكْرَهُ لُبْسٌ فِيهِ شُهْرَةُ لَابِسٍ","وَوَاصِفُ جِلْدٍ لَا لِزَوْجٍ وَسَيِّدِ"],["وَإِنْ كَانَ يُبْدِي عَوْرَةً لِسِوَاهُمَا","فَذَلِكَ مَحْظُورٌ بِغَيْرِ تَرَدُّدِ"],["وَخَيْرُ خِلَالِ الْمَرْءِ جَمْعًا تَوَسُّطُ الْـ","ـأُمُورِ وَحَالٌ بَيْنَ أَرْدَى وَأَجْوَدِ"],["وَيَحْرُمُ لُبْسٌ فِيهِ حَيٌّ مُصَوَّرٌ","طِرَازًا وَصَبْغًا فِي أَصَحِّ التَّرَدُّدِ"],["وَتُكْرَهُ فِي سَتْرٍ وَسَقْفٍ وَحَائِطٍ","وَلَا بَأْسَ فِي مَوْطُوئِهَا وَالْمُوَسَّدِ"],["وَيُكْرَهُ لِلْمَرْءِ السُّجُودُ بِوَجْهِهِ","عَلَى صُورَةٍ قَدْ صُوِّرَتْ فِي مُمَهَّدِ"],["بِذَاكَ حَفِيدُ الْمَجْدِ أَفْتَى لِشِبْهِهِ","بِعُبَّادِ أَصْنَامٍ عَلَى غَيْرِهَا اسْجُدِ"],["وَيُكْرَهُ مَا فِيهِ صَلِيبٌ مُصَوَّرٌ","وَهَذَا جَمِيعٌ لِلرِّجَالِ وَنُهَّدِ"],["وَيُكْرَهُ لُبْسُ الْأُزْرِ وَالْخُفِّ قَائِمًا","كَذَاكَ الْتِصَاقُ اثْنَيْنِ عُرْيًا بِمَرْقَدِ"],["وَثِنْتَيْنِ وَافْرُقْ فِي الْمَضَاجِعِ بَيْنَهُمْ","وَلَوْ إِخْوَةً مِنْ بَعْدِ عَشْرٍ تُسَدَّدِ"],["وَقُلْ فِي انْتِبَاهٍ وَالصَّبَاحِ وَفِي الْمَسَا","وَنَوْمٍ مِنَ الْمَرْوِيِّ مَا شِئْتَ تَهْتَدِ"],["فَفِي سَفَرٍ إِنْ كُنْتَ أَوْ حَضَرٍ فَلَا","تَدَعْ وِرْدَ خَيْرٍ قَدْ رُوِي عَنْ مُحَمَّدِ"],["وَيَحْسُنُ عِنْدَ النَّوْمِ نَفْضُ فِرَاشِهِ","وَنَوْمٌ عَلَى الْيُمْنَى وَكُحْلٌ بِإِثْمِدِ"],["وَسِرْ حَافِيًا أَوْ حَاذِيًا وَامْشِ وَارْكَبَنْ","تَمَعْدَدْ وَاخْشَوْشِنْ وَلَا تَتَعَوَّدِ"],["فَإِنَّ عِبَادَ اللَّهِ لَيْسُوا بِنُعَّمٍ","فَإِيَّاكَ وَالتَّنْعِيمَ مَعْ زِيِّ جُحَّدِ"],["وَكُنْ شَاكِرًا لِلَّهِ وَارْضَ بِقَسْمِهِ","تُثَبْ وَتُزَدْ رِزْقًا وَإِرْغَامَ حُسَّدِ"],["وَأَطْوَلُ ذَيْلِ الْمَرْءِ لِلْكَعْبِ وَالنِّسَا","بِلَا الْأُزْرِ شِبْرًا أَوْ ذِرَاعًا لِتَزْدَدِ"],["وَأَشْرَفُ مَلْبُوسٍ إِلَى نِصْفِ سَاقِهِ","وَمَا تَحْتَ كَعْبٍ فَاكْرَهَنْهُ وَصَعِّدِ"],["وَلِلرُّصْغِ كُمُّ الْمُصْطَفَى فَإِنِ ارْتَخَى","تَنَاهَى إِلَى أَقْصَى أَصَابِعِهِ قَدِ"],["وَلِلرَّجُلِ احْظُرْ لُبْسَ أُنْثَى وَعَكْسِهِ","لِلَعْنٍ عَلَيْهِ وَاكْرَهَنْهُ بِأَبْعَدِ"],["وَلَا بَأْسَ فِي لُبْسِ السَّرَاوِيلِ سُتْرَةً","أَتَمُّ مِنَ التَّأْزِيرِ فَالْبَسْهُ وَاقْتَدِ"],["بِسُنَّةِ إِبْرَاهِيمَ فِيهِ وَأَحْمَدٍ","وَأَصْحَابِهِ وَالْأُزْرَ أَشْهِرْ وَأَكِّدِ"],["وَعِمَّةُ مُخْلِي حَلْقِهِ مِنْ تَحَنُّكٍ","لَدَى أَحْمَدٍ مَكْرُوهَةٌ بِتَأَكُّدِ"],["وَيَحْسُنُ أَنْ يُرْخِيَ الذُّؤَابَةَ خَلْفَهُ","وَلَوْ شِبْرًا أَوْ أَدْنَى عَلَى نَصِّ أَحْمَدِ"],["وَأَحْسَنُ مَلْبُوسٍ بَيَاضٌ لِمَيِّتٍ","وَحَيٍّ فَبَيِّضْ مُطْلَقًا لَا تُسَوِّدِ"],["وَلَا بَأْسَ بِالْمَصْبُوغِ مِنْ قَبْلِ غَسْلِهِ","مَعَ الْجَهْلِ فِي أَصْبَاغِ أَهْلِ التَّهَوُّدِ"],["وَقِيلَ اكْرَهَنْهُ مِثْلُ مُسْتَعْمَلِ الْإِنَا","وَإِنْ تَعْلَمِ التَّنْجِيسَ فَاغْسِلْهُ تَهْتَدِ"],["وَأَحْمَرَ قَانٍ وَالْمُعَصْفَرَ فَاكْرَهَنْ","لِلُبْسِ رِجَالٍ حَسْبُ فِي نَصِّ أَحْمَدِ"],["وَلَا تَكْرَهَنْ فِي نَصِّهِ مَا صَبَغْتَهُ","مِنَ الزَّعْفَرَانِ الْبَحْتِ لَوْنِ الْمُوَرَّدِ"],["وَلَيْسَ بِلُبْسِ الصُّوفِ بَأْسٌ وَلَا الْقَبَا","وَلَوْ لِلنِّسَا وَالْبُرْنُسِ افْهَمْهُ وَاقْتَدِ"],["وَيَحْسُنُ تَنْظِيفُ الثِّيَابِ وَطَيُّهَا","وَيُكْرَهُ مَعْ طُولِ الْغِنَى لُبْسُكَ الرَّدِ"],["وَمَا يُشْبِهُ الزُّنَّارَ يُكْرَهُ مُطْلَقًا","وَمُزْرٍ بِهِ أَوْ شِبْهِ لُبْسِ التَّهَوُّدِ"],["وَيَحْرُمُ جَرُّ اللُّبْسِ لِلْخُيَلَاءِ مِنْ","فَتًى مُطْلَقًا بَلْ فِي الصَّلَاةِ فَأَكِّدِ"],["وَمَا يُشْبِهُ الزُّنَّارَ يُكْرَهُ مُطْلَقًا","وَلَا بَأْسَ فِي شَدِّ الْإِزَارِ لِسُجَّدِ"],["وَلُبْسَ الْحَرِيرِ احْظُرْ عَلَى كُلِّ بَالِغٍ","سِوَى لِضَنًى أَوْ قَمْلٍ أَوْ جَرْبِ جُحَّدِ"],["فَجَوِّزْهُ فِي الْأَوْلَى وَحَرِّمْهُ فِي الْأَصَحِّ","عَلَى هَذِهِ الصِّبْيَانِ مِنْ مُصْمَتٍ زِدِ"],["وَيَحْرُمُ بَيْعٌ لِلرِّجَالِ لِلُبْسِهِمْ","وَتَخْيِيطِهِ وَالنَّسْجِ فِي نَصِّ أَحْمَدِ"],["وَبَيْعُ عَصِيرٍ لِلْمُخَمِّرِ بَاطِلٌ","كَذَا عِنَبٌ مَعْ كُلِّ عَوْنٍ لِمُفْسِدِ"],["كَشَمْعٍ لِشُرَّابٍ وَأَكْلٍ وَجَوْزَةِ الْـ","ـقِمَارِ وَشِطْرَنْجٍ وَسَيْفٍ لِمُعْتَدِ"],["وَدُفٍّ وَمِزْمَارٍ وَجَارِيَةِ الْغِنَا","وَعُودٍ وَعَنْ إِيجَارِ ذَلِكَ فَاصْدُدِ"],["كَذَا بَيْعُ مَأْمُورٍ بِسَعْيٍ لِجُمْعَةٍ","إِذَا أَذَّنَ الثَّانِي وَعَنْهُ الَّذِي ابْتُدِي"],["كَذَا الْحُكْمُ فِيمَا ضَاقَ مِنْ وَقْتِ غَيْرِهَا","وَصَحِّحْ مِنَ الْمَعْذُورِ عَنْهَا بِأَوْطَدِ"],["وَيَحْرُمُ إِيجَارُ الْكِلَابِ وَبَيْعُهَا","بِغَيْرِ خِلَافٍ عِنْدَنَا لَمْ يُقَيَّدِ"],["وَكُرْهٌ بِلَا حَظْرٍ مُبَايَعَةُ امْرِئٍ","تَمَوَّلَ مِنْ حِلٍّ وَحَظْرٍ مُنَكَّدِ"],["وَمَعْلُومُ حَظْرٍ مِنْهُ حَظِّرْ وَحِلُّهُ","مُبَاحٌ وَفِي الشُّبْهَاتِ مُبْهَمَهُ اعْدُدِ"],["وَيَزْدَادُ طَوْرًا أَوْ يَقِلُّ اشْتِبَاهُهُ","وَلَكِنَّ دَعْوَى الْمُشْتَرِي الْحَظْرَ فَارْدُدِ"],["وَيُكْرَهُ بَيْعٌ وَابْتِيَاعٌ بِمَوْطِنِ الظُّـ","ـلَامَاتِ أَوْ غَصْبٍ لِقَصْدِ التَّزَهُّدِ"],["وَحِكْمَةُ بَيْعٍ وَاشْتِرَاءٍ لِذِي النُّهَى","تُوَصِّلُ ذَا فَقْرٍ إِلَى كُلِّ مَقْصَدِ"],["تَبَارَكَ ذُو الْأَحْكَامِ وَالْحِكَمِ الَّتِي","تَحَارُ عُقُولُ الْخَلْقِ فِيهَا فَتَهْتَدِي"],["فَفِي كُلِّ شَيْءٍ حِكْمَةٌ وَدَلَالَةٌ","لِدَاعٍ عَلَى تَوْحِيدِهِ وَالتَّفَرُّدِ"],["أَبَاحَ اكْتِسَابَ الْمَالِ مِنْ سُبْلِ حِلِّهِ","فَكَانَ إِلَى تَحْصِيلِهِ خَيْرَ مُرْشِدِ"],["فَمِنْ حُكْمِهِ إِبْدَاؤُنَا وَأُمُورُنَا","ذَوَاتُ ارْتِبَاطٍ لَا ذَوَاتُ تَوَحُّدِ"],["فَكُلُّ امْرِئٍ لَا يَسْتَقِلُّ بِأَمْرِهِ","فَسَنَّ لَنَا سُبْلَ التَّعَاوُنِ فَاهْتَدِ"],["فَطَوْرًا بِتَوْكِيلٍ وَطَوْرًا بِأُجْرَةٍ","مُعَيَّنَةٍ فِي فِعْلِ شَيْءٍ مُقَيَّدِ"],["وَطَوْرًا أَبَاحَ الْجَهْلَ عِنْدَ تَعَذُّرِ التَّـ","ـعَيُّنِ وَمِنْ هَذَا الْمُضَارَبَةَ اعْدُدِ"],["إِلَيْهِ انْتَهَى الْأَسْبَابُ فِي كُلِّ كَائِنٍ","وَمِنْهُ جَمِيعُ الْأَمْرِ يُنْهِي وَيَبْتَدِي"],["يُعَلِّقُ أَطْمَاعَ الْأَنَامِ بِمَكْسَبٍ","لَهُ يَرْكَبُونَ الْهَوْلَ فِي كُلِّ مَقْصَدِ"],["يَهُونُ عَلَى هَذَا اقْتِحَامٌ بِنَفْسِهِ","وَهَذَا بِمَالٍ رَغْبَةً فِي التَّزَيُّدِ"],["لِيَأْتِيَ بِأَرْزَاقٍ يَعِزُّ حُصُولُهَا","إِلَى عَاجِزٍ عَنْهَا ضَجِيعٍ بِمَرْقَدِ"],["فَسُبْحَانَ مَنْ أَبْدَى فَأَتْقَنَ صُنْعَهُ","وَجَلَّ تَعَالَى عَنْ أَبَاطِيلِ مُلْحِدِ"],["وَلَيْسَ بِمَحْظُورٍ عَطَايَا مُلُوكِنَا","فَقَدْ قَبِلُوا مِنْهُمْ صَحَابَةُ أَحْمَدِ"],["وَقَدْ عَامَلَ الْمُخْتَارُ بَعْضَ الْيَهُودِيَا","فَتًى وَأَكَلْ لَمَّا دَعَوْهُ فَقَلِّدِ"],["وَمَنْ يَتَصَدَّقْ أَوْ يَرُدَّ كَمُبْهَمِ الْـ","ـحَرَامِ لَدَيْهِ حَلَّ بَاقِيهِ فَاشْهَدِ"],["وَحَظِّرْ عَلَى الذُّكْرَانِ مَا نَسَجُوهُ مِنْ","لُجَيْنٍ وَعَيْنٍ غَالِبٍ أَوْ مُصَرَّدِ"],["وَيَحْرُمُ فِي مَنْصُوصِ أَحْمَدَ تِكَّةُ الْـ","ـحَرِيرِ كَذَا شُرَّابَةٌ لَا تُرَدِّدِ"],["وَحَلَّ عَلَى الذُّكْرَانِ خَاتَمُ فِضَّةٍ","وَحِلْيَةُ سَيْفٍ مَعْ قَبِيعَةِ عَسْجَدِ"],["وَأَنْفٍ وَرَبْطِ السِّنِّ مِنْهُ ضَرُورَةً","وَقَوْلُ أَبِي بَكْرٍ مُبِيحِ الْمُزَهِّدِ"],["وَقَوْلَيْنِ خُذْ فِي حِلْيِ مِنْطَقَةِ الْفَتَى","مِنَ الْفِضَّةِ الْبَيْضَا وَوَجْهَيْنِ أَسْنِدِ"],["أُحِلَّ لُجَيْنٌ فِي حَمَائِلِ صَارِمٍ","وَخُفٍّ وَرَانٍ خُوذَةٍ جَوْشَنٍ طِدِ"],["وَفِي السِّتْرِ أَوْ مَا هُوَ مَظِنَّةُ بِذْلَةٍ","لَيُكْرَهُ كَتْبٌ لِلْقُرَانِ الْمُمَجَّدِ"],["وَلَيْسَ بِمَكْرُوهٍ كِتَابَةُ غَيْرِهِ","مِنَ الذِّكْرِ فِيمَا لَمْ يُدَسْ وَيُمَهَّدِ"],["وَحَلَّ لِمَنْ يَسْتَأْجِرُ الْبَيْتَ حَكُّهُ الْـ","ـتَّصَاوِيرَ كَالْحَمَّامِ لِلدَّاخِلِ اشْهَدِ"],["وَحَلَّ شِرَى وَالِي الْيَتِيمَةِ لُعْبَةً","بِلَا رَأْسٍ انْ تَطْلُبْ وَبِالرَّأْسِ فَاصْدُدِ"],["وَلَا يَشْتَرِي مَا كَانَ مِنْ ذَاكَ صُورَةً","وَمِنْ مَالِهِ لَا مَالِهَا فِي الْمُجَرَّدِ"],["وَيَحْرُمُ تَصْوِيرٌ لِذِي الرُّوحِ كَامِلًا","وَذَنْبًا كَبِيرًا عُدَّهُ لِلتَّوَعُّدِ"],["وَلَا بَأْسَ فِي لُبْسِ الْفِرَا وَاشْتِرَائِهَا","جُلُودُ حَلَالٍ مَوْتُهُ لَمْ يُؤَطَّدِ"],["وَكَاللَّحْمِ فِي الْأَوْلَى احْظُرَنْ جِلْدَ ثَعْلَبٍ","وَعَنْهُ لِيُلْبَسْ وَالصَّلَاةَ بِهِ اصْدُدِ"],["وَقَدْ كَرِهَ السَّمُّورَ وَالْفَنْكَ أَحْمَدٌ","وَسِنْجَابَهُمْ وَالْقَاقُمَ أَيْضًا لِيَزْدَدِ"],["وَفِي نَصِّهِ لَا بَأْسَ فِي جِلْدِ أَرْنَبٍ","وَكُلَّ السِّبَاعِ احْظُرْ كَهِرٍّ بِأَوْطَدِ"],["وَلَا بَأْسَ بِالْخَاتَامِ مِنْ فِضَّةٍ وَمِنْ","عَقِيقٍ وَبَلُّورٍ وَشِبْهِ الْمُعَدَّدِ"],["وَيُكْرَهُ مِنْ صُفْرٍ رَصَاصٍ حَدِيدُهُمْ","وَيَحْرُمُ لِلذُّكْرَانِ خَاتَمُ عَسْجَدِ"],["وَيَحْسُنُ فِي الْيُسْرَى كَأَحْمَدْ وَصَحْبِهِ","وَيُكْرَهُ فِي الْوُسْطَى وَسَبَّابَةِ الْيَدِ"],["وَمَنْ لَمْ يَضَعْهُ فِي الدُّخُولِ إِلَى الْخَلَا","فَعَنْ كَتْبِ قُرْآنٍ وَذِكْرٍ بِهِ اصْدُدِ"],["وَمُكْحُلَةً مِيلًا مِنَ النَّقْدِ حَرِّمَنْ","وَحِلْيَةَ مِرْآةٍ وَمُشْطٍ مُكَدَّدِ"],["وَحِلْيَةَ قِنْدِيلٍ دَوَاةٍ وَمُصْحَفٍ","وَسَرْجٍ وَطَوْقٍ لِلدَّوَابِّ مُقَلَّدِ"],["وَإِنَّ عُقُوقَ الْوَالِدَيْنِ كَبِيرَةٌ","فَبِرَّهُمَا تَبْرُرْ جَزَاءً وَتُحْمَدِ"],["وَيُكْرَهُ فِي الْمَشْيِ الْمُطَيْطَا وَشِبْهُهَا","مَظِنَّةَ كِبْرٍ غَيْرَ فِي حَرْبِ جُحَّدِ"],["وَلَا تَكْرَهَنَّ الشُّرْبَ مِنْ قَائِمٍ وَلَا انْـ","ـتِعَالَ الْفَتَى فِي الْأَظْهَرِ الْمُتَأَكَّدِ"],["وَيَحْسُنُ بِالْيُمْنَى ابْتِدَاءُ انْتِعَالِهِ","وَفِي الْخَلْعِ عَكْسٌ وَاكْرَهِ الْعَكْسَ تُرْشَدِ"],["وَيُكْرَهُ مَشْيُ الْمَرْءِ فِي فَرْدِ نَعْلِهِ اخْـ","ـتِيَارًا أَصَحْ حَتَّى لِإِصْلَاحِ مُفْسِدِ"],["وَلَا بَأْسَ فِي نَعْلٍ تُصَلِّي بِهَا بِلَا","أَذًى وَافْتَقِدْهَا عِنْدَ أَبْوَابِ مَسْجِدِ"],["وَيَحْسُنُ الِاسْتِرْجَاعُ فِي قَطْعِ شِسْعِهِ","وَتَخْصِيصُ حَافٍ بِالطَّرِيقِ الْمُمَهَّدِ"],["وَإِنْ تَلْقَ يَوْمًا فِي الطَّرِيقِ حِجَارَةً","أَوِ الشَّوْكَ أَوْ عَظْمًا أَزِلْ وَكَذَا الرَّدِي"],["وَكُنْ حَذِرًا عَنْ مَجْلِسٍ فِي الطَّرِيقِ قَدْ","نُهِي عَنْهُ إِلَّا مَعْ شُرُوطٍ تُعَدَّدِ"],["هِيَ امْرٌ بِمَعْرُوفٍ وَنَهْيٌ لِمُنْكَرٍ","وَرَدُّ سَلَامٍ لِلْمُسَلِّمِ يَبْتَدِي"],["وَغَضٌّ لِأَبْصَارٍ وَكَفٌّ عَنِ الْأَذَى","وَإِرْشَادُ مَنْ قَدْ يَسْتَدِلُّ لِمَقْصَدِ"],["وَمُبْهَمُ طِينٍ فِي الشَّوَارِعِ طَاهِرٌ","وَإِلَّا فَنَزْرٌ مِنْهُ عَفْوٌ بِأَجْوَدِ"],["وَيَطْهُرُ بِالْأَمْطَارِ كُلُّ مَقَابِرِ الْأَ","وَائِلِ إِنْ لَمْ يَبْقَ عَظْمٌ بِهَا نَدِي"],["وَقَدْ لَبِسَ السِّبْتِيَّ وَهْوَ الَّذِي خَلَا","مِنَ الشَّعْرِ مَعْ أَصْحَابِهِ بِهِمُ اقْتَدِ"],["وَيُكْرَهُ سِنْدِيُّ النِّعَالِ لِعُجْبِهِ","فَصَرَّارُهَا زِيُّ الْيَهُودِ فَأَبْعِدِ"],["وَفِي نَصِّهِ اكْرَهْ لِلرِّجَالِ وَلِلنِّسَا الرَّ","قِيقَ سِوَى لِلزَّوْجِ يَخْلُو وَسَيِّدِ"],["وَإِنْ كَانَ يُبْدِي عَوْرَةً لِسِوَاهُمَا","فَذَلِكَ مَحْظُورٌ بِغَيْرِ تَرَدُّدِ"],["وَيُكْرَهُ تَقْصِيرُ اللِّبَاسِ وَطُولُهُ","بِلَا حَاجَةٍ كِبْرًا وَتَرْكُ التَّعَوُّدِ"],["وَلِلرَّجُلِ اكْرَهْ عَرْضَ زِيقٍ بِنَصِّهِ","وَلَا يُكْرَهُ الْكَتَّانُ فِي الْمُتَأَطِّدِ"],["وَيَحْسُنُ حَمْدُ اللَّهِ فِي كُلِّ حَالَةٍ","وَلَا سِيَّمَا فِي لُبْسِ ثَوْبٍ مُجَدَّدِ"],["وَقُلْ لِأَخٍ أَبْلِي وَأَخْلِقْ وَيُخْلِفُ الْـ","ـإِلَهُ كَذَا قُلْ عِشْ حَمِيدًا تُسَدَّدِ"],["وَمَنْ يَرْتَضِي أَدْنَى اللِّبَاسِ تَوَاضُعًا","سَيُكْسَى الثِّيَابَ الْعَبْقَرِيَّاتِ فِي غَدِ"],["تَبَارَكَ ذُو الْمَنِّ الْمُدَبِّرُ خَلْقَهُ","بِمَا شَاءَهُ مِنْ غَيْرِ مَنْعٍ مُصَرَّدِ"],["فَكَمْ حِكَمٍ فِي طَيِّ أَحْكَامِهِ لَهُ","يُدَبِّرُهَا تَجْلُو الْقُلُوبَ فَتَهْتَدِي"],["فَلَيْسَ بِمَسْؤُولٍ وَلَكِنْ مُسَائِلٌ","بَرِيَّتَهُ عَمَّا يَقُولُونَ فِي غَدِ"],["أَبَاحَ لَنَا فِعْلَ النِّكَاحِ وَسَنَّهُ","لِمَا شَاءَ فِينَا مِنْ نَمَاءٍ مُعَوَّدِ"],["وَمَذْهَبُنَا اسْتِحْبَابُهُ وَهْوَ وَاجِبٌ","عَلَى خَائِفٍ مِنْ مُعْنِتٍ مُتَوَقِّدِ"],["وَخُذْ مِنْ نَصِيحٍ يَا أُخَيَّ نَصِيحَةً","وَكُنْ حَازِمًا وَاحْضُرْ بِقَلْبٍ مُؤَيَّدِ"],["وَلَا تَنْكِحَنْ إِنْ كُنْتَ شَيْخًا فَتِيَّةً","تَعِشْ فِي ضِرَارِ الْعَيْشِ أَوْ تَرْضَ بِالرَّدِ"],["وَلَا تَنْكِحَنَّ مَنْ تَسْمُ فَوْقَكَ رُتْبَةً","تَكُنْ أَبَدًا فِي حُكْمِهَا فِي تَنَكُّدِ"],["وَهَذَا لَعَمْرِي جُمْلَةٌ فِي اشْتِرَاطِهِ الْـ","ـكَفَاءَةَ إِذْ فِيهِ كَمَالُ التَّوَدُّدِ"],["وَلَا تَرْغَبَنْ فِي مَالِهَا وَأَثَاثِهَا","إِذَا كُنْتَ ذَا فَقْرٍ تَذِلَّ وَتُضْهَدِ"],["وَلَا تَسْكُنَنْ فِي دَارِهَا عِنْدَ أَهْلِهَا","تَسَمَّعْ إِذَنْ أَنْوَاعَ مَنٍّ مُعَدَّدِ"],["فَلَا خَيْرَ فِيمَنْ كَانَ فِي فَضْلِ عِرْسِهِ","يَرُوحُ عَلَى هَوْنٍ إِلَيْهَا وَيَغْتَدِي"],["وَلَا تُنْكِرَنْ بَذْلَ الْيَسِيرِ تَنَكُّدًا","وَسَامِحْ تَنَلْ أَجْرًا وَحُسْنَ تَوَدُّدِ"],["وَلَا تَسْأَلَنْ عَمَّا عَهِدْتَ وَأَغْضِ عَنْ","عَوَارٍ إِذَا لَمْ يَذْمُمِ الشَّرْعُ تَرْشُدِ"],["وَكُنْ حَافِظًا أَنَّ النِّسَاءَ وَدَائِعٌ","عَوَانٌ لَدَيْنَا احْفَظْ وَصِيَّةَ مُرْشِدِ"],["وَلَا تُكْثِرِ الْإِنْكَارَ تُرْمَ بِتُهْمَةٍ","وَلَا تَرْفَعَنَّ السَّوْطَ عَنْ كُلِّ مُعْتَدِ"],["وَلَا تَطْمَعَنْ فِي أَنْ تُقِيمَ اعْوِجَاجَهَا","فَمَا هِيَ إِلَّا مِثْلُ ضِلْعٍ مُرَدَّدِ"],["وَسُكْنَى الْفَتَى فِي غُرْفَةٍ فَوْقَ سِكَّةٍ","يَؤُولُ إِلَى تُهْمَى الْبَرِيِّ الْمُسَدَّدِ"],["وَإِيَّاكَ يَا هَذَا وَرَوْضَةَ دِمْنَةٍ","سَتَرْجِعُ عَنْ قُرْبٍ إِلَى أَصْلِهَا الرَّدِي"],["وَحَرِّمْ عَلَى كُلٍّ نِكَاحَ الَّتِي زَنَتْ","إِلَى تَوْبَةٍ ثُمَّ انْقِضَا عِدَّةٍ زِدِ"],["وَعَنْ أَحْمَدٍ إِنْ يَبْغِهَا مَنْ زَنَا بِهَا","فَتَوْبَتُهُ شَرْطٌ لِعَقْدٍ مُعَقَّدِ"],["وَلَا تَنْكِحَنْ فِي الْفَقْرِ إِلَّا ضَرُورَةً","وَلُذْ بِوِجَاءِ الصَّوْمِ تُهْدَ وَتُرْشَدِ"],["وَكُنْ عَالِمًا أَنَّ النِّسَا لُعَبٌ لَنَا","فَحَسِّنْ إِذَنْ مَهْمَا اسْتَطَعْتَ وَجَوِّدِ"],["وَخَيْرُ النِّسَا مَنْ سَرَّتِ الزَّوْجَ مَنْظَرًا","وَمَنْ حَفِظَتْهُ فِي مَغِيبٍ وَمَشْهَدِ"],["قَصِيرَةُ أَلْفَاظٍ قَصِيرَةُ بَيْتِهَا","قَصِيرَةُ طَرْفِ الْعَيْنِ عَنْ كُلِّ أَبْعَدِ"],["عَلَيْكَ بِذَاتِ الدِّينِ تَظْفَرْ بِالْمُنَى الْـ","ـوَدُودِ الْوَلُودِ الْأَصْلِ ذَاتِ التَّعَبُّدِ"],["حَسِيبَةِ أَصْلٍ مِنْ كِرَامٍ تَفُزْ إِذَنْ","بِوُلْدٍ كِرَامٍ وَالْبَكَارَةَ فَاقْصِدِ"],["وَوَاحِدَةٌ أَدْنَى إِلَى الْعَدْلِ فَاقْتَنِعْ","وَإِنْ شِئْتَ فَابْلُغْ أَرْبَعًا لَا تُزَيَّدِ"],["وَيُشْرَعُ إِعْلَانُ النِّكَاحِ وَضَرْبُهُمْ","عَلَيْهِ بِدُفٍّ لِلْخِلَافِ لِمُفْسِدِ"],["وَسَلْ خَيْرَهَا الرَّحْمَنَ ثُمَّ اسْتَعِذْهُ مِنْ","أَذَى شَرِّهَا عِنْدَ الزِّفَافِ تُسَدَّدِ"],["وَحَقٌّ عَلَى الزَّوْجَيْنِ أَنْ يَتَعَاشَرَا","بِعُرْفٍ وَبَذْلِ الْحَقِّ لَا بِتَنَكُّدِ"],["وَلَيْسَ حَلَالًا وَطْءُ سُرِّيَّةٍ وَلَا","لِزَوْجَتِهِ فِي الْحَيْضِ وَالدُّبُرِ اصْدُدِ"],["وَمَنْ شَاءَ بَيْنَ الْأَلْيَتَيْنِ تَلَذُّذًا","إِذَا هُوَ لَمْ يُولِجْ فَلَيْسَ بِمُبْعَدِ"],["وَقِيلَ يُسَنُّ الْوَطْءُ فِي الشَّهْرِ مَرَّةً","وَإِلَّا فَفِي الْأُسْبُوعِ إِنْ يَتَزَيَّدِ"],["وَلَيْسَ بِمَسْنُونٍ عَلَيْهِ زِيَادَةٌ سِوَى","عِنْدَ دَاعِي شَهْوَةٍ وَتَوَلُّدِ"],["وَسَمِّ وَقُلْ لَاهُمَّ جَنِّبْنَنَا وَمَا","رَزَقْتَ الشَّيَاطِينَ ادْعُ لِلْوَطْءِ تَهْتَدِ"],["وَيُكْرَهُ تَكْثِيرُ الْكَلَامِ مُجَامِعًا","وَعَنْ نَزْعِهِ مِنْ قَبْلِ تَتْمِيمِهَا اصْدُدِ"],["وَيُشْرَعُ أَيْضًا أَنْ يُلَاعِبَ قَبْلَهُ","وَيُكْرَهُ مِنْهُ وَطْؤُهَا ذَا تَجَرُّدِ"],["وَأَنَّ وُضُوءَ الْمَرْءِ مَعْ غَسْلِ فَرْجِهِ","إِذَا رَامَ عَوْدًا يُسْتَحَبُّ فَجَوِّدِ"],["وَيُكْرَهُ وَطْءُ الْخَوْدِ مَعْ رَأْيِ غَيْرِهَا","وَلَوْ ضَرَّةً تَرْضَى وَجَمْعٌ بِمَرْقَدِ"],["وَطَاعَةَ الِاسْتِمْتَاعِ لِلزَّوْجِ أَوْجِبَنْ","بِإِغْضَابِهِ يُغْضَبْ عَلَيْهَا وَتُبْعَدِ"],["فَمَنْ أَغْضَبَتْ زَوْجًا بِعِصْيَانِهَا تَبِتْ","مَلَائِكَةُ الرَّحْمَنِ تَلْعَنُهَا اسْنِدِ"],["وَإِذْنُكَ نَدْبٌ فِي عِيَادَةِ مَحْرَمٍ","وَحَضْرَتِهَا لِلْمَيْتِ لَا بِتَشَدُّدِ"],["وَإِنْ خَرَجَتْ فِي زِينَةٍ أَوْ تَطَيَّبَتْ","لِتُمْنَعْ وَإِنْ خِفْتَ الْأَذَى امْنَعْ وَشَدِّدِ"],["وَكُنْ عَالِمًا أَنَّ الْفُرُوضَ تَقَسَّمَتْ","بِعَيْنٍ كَصَوْمٍ مَعْ صَلَاةِ تَعَبُّدِ"],["وَفَرْضُ كِفَايَاتٍ مَتَى قَامَ بَعْضُهُمْ","بِهِ سَقَطَ التَّأْثِيمُ عَنْ كُلِّ مُفْرَدِ"],["كَدَفْعٍ لِضُرِّ الْمُسْلِمِينَ لِقَادِرٍ","كَإِشْبَاعِ ذِي جُوعٍ فَقِيرٍ مُصَرَّدِ"],["وَسَتْرٍ لِعُرْيَانٍ عِيَادَةِ مُدْنَفٍ","وَتَغْسِيلِ مَيْتٍ ثُمَّ دَفْنِ الْمُلَحَّدِ"],["وَتَكْفِينِهِ ثُمَّ الصَّلَاةِ عَلَيْهِ مَعْ","مُتَابَعَةِ الْمَحْمُولِ لِلْقَبْرِ فَاسْعَدِ"],["وَمِنْهَا صِنَاعَاتٌ أُبِيحَتْ مُهِمَّةٌ","لِمَصْلَحَةٍ تَحْتَاجُهَا النَّاسُ تُرْفَدِ"],["وَزَرْعٌ وَغَرْسٌ حَفْرُ نَهْرٍ وَبِئْرِهَا","وَتَنْظِيمُهَا ثُمَّ الْبُثُوقَ فَسَدِّدِ"],["بِنَاءٌ لِجِسْرٍ ثُمَّ سُورٍ وَرَمُّهَا","وَقَنْطَرَةٍ يَحْتَاجُهَا ثُمَّ مَسْجِدِ"],["إِمَامَتُنَا الْعُظْمَى إِقَامَةُ دَعْوَةٍ","وَدَفْعٌ لِشُبْهَاتِ الْمُضِلِّ الْمُلَدَّدِ"],["جِهَادٌ وَحَجٌّ كُلَّ عَامٍ كَذَا الْقَضَا","وَالِافْتَا وَتَعْلِيمُ الْكِتَابِ الْمُمَجَّدِ"],["وَتَعْلِيمُ مَا قَدْ سَنَّهُ خَيْرُ مُرْسَلٍ","وَسَائِرُ عِلْمٍ فِي الشَّرِيعَةِ مُسْعِدِ"],["حِسَابٍ وَتَصْرِيفٍ وَنَحْوِ قِرَاءَةٍ","وَمَعْ لُغَةٍ مَعْ عِلْمِ طِبٍّ بِمُبْعَدِ"],["عَلَيْكَ بِتَقْوَى اللَّهِ فِي كُلِّ حَالَةٍ","تَحُزْ قَصَبَاتِ السَّبْقِ فِي الْيَوْمِ مَعْ غَدِ"],["وَنُصْحِ كِتَابِ اللَّهِ مَعْ نُصْحِ أَحْمَدٍ","نَبِيِّكَ خَيْرِ الْمُرْسَلِينَ مُحَمَّدِ"],["وَنُصْحِ جَمِيعِ الْمُسْلِمِينَ أَمِيرِهِمْ","وَمَأْمُورِهِمْ فَاقْبَلْ وَصِيَّةَ مُرْشِدِ"],["وَمَا زَالَ فِينَا كُلَّ عَصْرٍ أَئِمَّةٌ","يَذُبُّونَ عَنْ دِينِ الْهُدَى بِالْمُهَنَّدِ"],["فَيَنْفُونَ تَحْرِيفَ الْغُوَاةِ وَأَظْهَرُوا الْـ","ـصَّحِيحَ مِنَ الْمَعْلُولِ فِي كُلِّ مَشْهَدِ"],["فَأَرْبَعَةٌ فِي أَوَّلِ الْأَمْرِ عُمْدَةٌ","وَأَرْبَعَةٌ فِي آخِرِ الْأَمْرِ قَلِّدِ"],["فَكُلٌّ أَتَى فِي الدِّينِ أَقْصَى اجْتِهَادِهِ","وَأَحْمَدُهُمْ فِي النَّقْدِ مَذْهَبُ أَحْمَدِ"],["لِفَرْطِ اتِّبَاعٍ لِلنَّبِيِّ وَصَحْبِهِ","فَمِنْ أَجْلِ ذَا لَمْ يَسْتَجِبْ لِمُهَدِّدِ"],["دَعَوْهُ إِلَى قَوْلِ الضَّلَالِ فَلَمْ يُجِبْ","وَرَدَّ عَلَيْهِمْ رَدَّ خَيْرِ مُسَدَّدِ"],["وَجَادَ لِنَصْرِ الْحَقِّ بِالنَّفْسِ صَابِرًا","عَلَى الْجَلْدِ وَالتَّهْدِيدِ مِنْ كُلِّ مُعْتَدِ"],["فَآبَ بِحَمْدِ اللَّهِ بِالنَّصْرِ وَالْهُدَى","وَبَاءُوا بِخُسْرَانٍ وَذُلٍّ مُؤَبَّدِ"],["وَمَا زَالَتِ الْعُقْبَى لِكُلِّ مَنِ اتَّقَى","كَذَلِكَ وَعْدُ اللَّهِ فِي الذِّكْرِ الَامْجَدِ"],["وَإِيَّاكَ عَنْ آرَاءِ كُلِّ مُزَخْرِفٍ","مَقَالَتَهُ فَالسُّمُّ فِي ضِمْنِهَا الرَّدِي"],["فَقَدْ مَاتَ خَيْرُ النَّاسِ وَالدِّينُ كَامِلٌ","غَنِيٌّ عَنِ التَّبْيِينِ مِنْ كُلِّ مُلْحِدِ"],["فَطَالِبُ دِينِ الْحَقِّ فِي الرَّأْيِ ضَائِعٌ","وَمَنْ خَاضَ فِي عِلْمِ الْكَلَامِ فَمَا هُدِي"],["كَفَى بِهِمُ نَقْصًا تَنَاقُضُ قَوْلِهِمْ","وَكُلٌّ يَقُولُ الْحَقُّ عِنْدِي فَقَلِّدِ"],["وَلَوْ كَانَ حَقًّا لَمْ يَكُنْ مُتَنَاقِضًا","وَلَمْ يَتَنَقَّلْ رَبُّهُ ذَا تَلَدُّدِ"],["وَمَا الْحَقُّ إِلَّا لَيْلُهُ كَنَهَارِهِ","يُزِيلُ ضِيَاءً خَالِيًا مِنْ تَرَدُّدِ"],["بِهِ يَطْمَئِنُّ الْقَلْبُ غَيْرَ مُزَعْزَعٍ","وَلَا خَائِفٍ بَلْ آمِنٍ مِنْ تَنَكُّدِ"],["فَمَنْ قَلَّدَ الْآرَاءَ ضَلَّ عَنِ الْهُدَى","وَمَنْ قَلَّدَ الْمَعْصُومَ فِي الدِّينِ يَهْتَدِي"],["فَمَا الدِّينُ إِلَّا الِاتِّبَاعُ لِمَا أَتَى","عَنِ اللَّهِ وَالْهَادِي الْبَشِيرِ مُحَمَّدِ"],["كَذَلِكَ قَالَ الشَّافِعِيُّ وَغَيْرُهُ","مِنَ النَّاصِرِينَ الْحَقَّ مِنْ كُلِّ مُهْتَدِ"],["وَمَحْضُ التَّلَقِّي بِالْقَبُولِ لَهُ بِلَا","تَأَوُّلٍ اوْ تَشْبِيهٍ اوْ رَدِّ جُحَّدِ"],["فَكَابِدْ إِلَى أَنْ تُبْلِغَ النَّفْسَ عُذْرَهَا","وَكُنْ فِي اكْتِسَابِ الْعِلْمِ طَلَّاعَ أَنْجُدِ"],["وَلَا تُذْهِبَنَّ الْعُمْرَ مِنْكَ سَبَهْلَلًا","وَلَا تُغْبَنَنْ فِي النِّعْمَتَيْنِ بَلِ اجْهَدِ"],["فَمَنْ هَجَرَ اللَّذَّاتِ نَالَ الْمُنَى وَمَنْ","أَكَبَّ عَلَى اللَّذَّاتِ عَضَّ عَلَى الْيَدِ"],["وَفِي قَمْعِ أَهْوَاءِ النُّفُوسِ اعْتِزَازُهَا","وَفِي نَيْلِهَا مَا تَشْتَهِي ذُلٌّ سَرْمَدِي"],["فَلَا تَشْتَغِلْ إِلَّا بِمَا يُكْسِبُ الْعُلَا","وَلَا تَرْضَ لِلنَّفْسِ النَّفِيسَةِ بِالرَّدِي"],["وَفِي خَلْوَةِ الْإِنْسَانِ بِالْعِلْمِ أُنْسُهُ","وَيَسْلَمُ دِينُ الْمَرْءِ عِنْدَ التَّوَحُّدِ"],["وَيَسْلَمُ مِنْ قَالٍ وَقِيلٍ وَمِنْ أَذَى","جَلِيسٍ وَمِنْ وَاشٍ بَغِيضٍ وَحُسَّدِ"],["فَكُنْ حِلْسَ بَيْتٍ فَهْوَ سَتْرٌ لِعَوْرَةٍ","وَحِرْزُ الْفَتَى عَنْ كُلِّ غَاوٍ وَمُفْسِدِ"],["وَخَيْرُ جَلِيسِ الْمَرْءِ كُتْبٌ تُفِيدُهُ","عُلُومًا وَآدَابًا كَعَقْلٍ مُؤَيِّدِ"],["وَخَالِطْ إِذَا خَالَطْتَ كُلَّ مُوَفَّقٍ","مِنَ الْعُلَمَا أَهْلِ التُّقَى وَالتَّسَدُّدِ"],["يُفِيدُكَ مِنْ عِلْمٍ وَيَنْهَاكَ عَنْ هَوًى","فَصَاحِبْهُ تُهْدَ مِنْ هُدَاهُ وَتُرْشَدِ"],["وَإِيَّاكَ وَالْهَمَّازَ إِنْ قُمْتَ عَنْهُ وَالْـ","ـبَذِيءَ فَإِنَّ الْمَرْءَ بِالْمَرْءِ يَقْتَدِي"],["وَلَا تَصْحَبِ الْحَمْقَى فَذُو الْجَهْلِ إِنْ يَرُمْ","صَلَاحًا لِأَمْرٍ يَا أَخَا الْحَزْمِ يُفْسِدِ"],["وَخَيْرُ صِحَابٍ عِنْدَ رَبِّكَ خَيْرُهُمْ","لِصَاحِبِهِ وَالْجَارُ مِثْلُ الَّذِي ابْتَدِي"],["وَخَيْرُ مَقَامٍ قُمْتَ فِيهِ وَحِلْيَةٍ","تَحَلَّيْتَهَا ذِكْرُ الْإِلَهِ بِمَسْجِدِ"],["وَكُفَّ عَنِ الْعَوْرَا لِسَانَكَ وَلْيَكُنْ","دَوَامًا بِذِكْرِ اللَّهِ يَا صَاحِبِي نَدِي"],["وَحَصِّنْ عَنِ الْفَحْشَا الْجَوَارِحَ كُلَّهَا","تَكُنْ لَكَ فِي يَوْمِ الْجَزَا خَيْرَ شُهَّدِ"],["وَوَاظِبْ عَلَى دَرْسِ الْقُرَانِ فَإِنَّهُ","يُلَيِّنُ قَلْبًا قَاسِيًا مِثْلَ جَلْمَدِ"],["وَحَافِظْ عَلَى فِعْلِ الْفُرُوضِ بِوَقْتِهَا","وَخُذْ بِنَصِيبٍ فِي الدُّجَا مِنْ تَهَجُّدِ"],["وَنَادِ إِذَا مَا قُمْتَ فِي اللَّيْلِ سَامِعًا","قَرِيبًا مُجِيبًا بِالْفَوَاضِلِ يَبْتَدِي"],["وَمُدَّ إِلَيْهِ كَفَّ فَقْرِكَ ضَارِعًا","بِقَلْبٍ مُنِيبٍ وَادْعُ تُعْطَ وَتُرْشَدِ"],["وَلَا تَسْأَمَنَّ الْعِلْمَ وَاسْهَرْ لِنَيْلِهِ","بِلَا ضَجَرٍ تَحْمَدْ سُرَى السَّيْرِ فِي غَدِ"],["وَكُنْ صَابِرًا لِلْفَقْرِ وَادَّرِعِ الرِّضَا","بِمَا قَدَّرَ الرَّحْمَنُ وَاشْكُرْهُ وَاحْمَدِ"],["فَمَا الْعِزُّ إِلَّا فِي الْقَنَاعَةِ وَالرِّضَا","بِأَدْنَى كَفَافٍ حَاصِلٍ وَالتَّزَهُّدِ"],["فَمَنْ لَمْ يُقَنِّعْهُ الْكَفَافُ فَمَا إِلَى","رِضَاهُ سَبِيلٌ فَاقْتَنِعْ وَتَقَصَّدِ"],["فَمَنْ يَتَغَنَّ يُغْنِهِ اللَّهُ وَالْغِنَى","غِنَى النَّفْسِ لَا عَنْ كَثْرَةِ الْمُتَعَدِّدِ"],["وَلَا تَطْلُبَنَّ الْعِلْمَ لِلْمَالِ وَالرِّيَا","فَإِنَّ مِلَاكَ الْأَمْرِ فِي حُسْنِ مَقْصَدِ"],["وَكُنْ عَامِلًا بِالْعِلْمِ فِيمَا اسْتَطَعْتَهُ","لِيُهْدَى بِكَ الْمَرْءُ الَّذِي بِكَ يَقْتَدِي"],["حَرِيصًا عَلَى نَفْعِ الْوَرَى وَهُدَاهُمُ","تَنَلْ كُلَّ خَيْرٍ فِي نَعِيمٍ مُؤَبَّدِ"],["وَإِيَّاكَ وَالْإِعْجَابَ وَالْكِبْرَ تَحْظَ بِالشَّـ","ـقَاوَةِ فِي الدَّارَيْنِ فَارْشُدْ وَأَرْشِدِ"],["وَهَا قَدْ بَذَلْتُ النُّصْحَ جَهْدِي وَإِنَّنِي","مُقِرٌّ بِتَقْصِيرِي وَبِاللَّهِ أَهْتَدِي"],["وَقَدْ كَمُلَتْ وَالْحَمْدُ لِلَّهِ وَحْدَهُ","عَلَى كُلِّ حَالٍ دَائِمًا لَمْ يُصَرَّدِ"],["عَرُوسًا سَمَتْ شَمْسَ الضُّحَى حَنْبَلِيَّةً","تَآزَّرُ بِالنُّورِ الْمُبِينِ وَتَرْتَدِي"],["إِذَا انْتَسَبَتْ فِي الْعِلْمِ كَانَ انْتِسَابُهَا","لِمُجْتَهِدٍ فِي نُصْرَةِ الدِّينِ مُقْتَدِ"],["إِمَامِ الْهُدَى زَيْنِ التُّقَاةِ ابْنِ حَنْبَلٍ","عَلَى حُبِّهِ فِي اللَّهِ أُودَعُ مَلْحَدِ"],["فَمَا رَوْضَةٌ حُفَّتْ بِنُورِ رَبِيعِهَا","بِسَلْسَالِهَا الْعَذْبِ الزُّلَالِ الْمُبَرَّدِ"],["بِأَحْسَنَ مِنْ أَبْيَاتِهَا وَمَسَائِلٍ","أَحَاطَتْ بِهَا يَوْمًا بِغَيْرِ تَرَدُّدِ"],["فَخُذْهَا بِدَرْسٍ لَيْسَ بِالنَّوْمِ تُدْرِكَنْ","لِأَهْلِ التُّقَى وَالْعِلْمِ فِي كُلِّ مَشْهَدِ"],["فَلَا تَرْعَوِي عَنْ حِفْظِهَا فَهْيَ دُرَّةٌ","يَتِيمَةٌ اسْتَخْلَصْتُهَا فِي التَّنَقُّدِ"],["وَأَزْكَى صَلَاةِ اللَّهِ جَلَّ ثَنَاؤُهُ","وَعَزَّ عَلَى خَيْرِ الْبَرَايَا مُحَمَّدِ"],["وَأَصْحَابِهِ وَالْغُرِّ مِنْ آلِهِ وَمَنْ","تَلَاهُمْ بِإِحْسَانٍ بِهِمْ ظَلَّ يَقْتَدِي"]],"secs":{"20":"صَوْنُ الْجَوَارِحِ","39":"تَحْرِيمُ الْغِيبَةِ وَالنَّمِيمَةِ","44":"الْأَمْرُ بِالْمَعْرُوفِ وَالنَّهْيُ عَنِ الْمُنْكَرِ","62":"حُكْمُ آلَاتِ اللَّهْوِ وَالْغِنَاءِ وَالشِّعْرِ","77":"هِجْرَانُ أَهْلِ الْمَعَاصِي","87":"السَّلَامُ وَالْمُصَافَحَةُ وَالِاسْتِئْذَانُ","116":"صِلَةُ الْأَرْحَامِ وَبِرُّ الْوَالِدَيْنِ وَالتَّعْدِيلُ بَيْنَ الْأَوْلَادِ","129":"النَّهْيُ عَنِ التَّنْجِيمِ وَالسِّحْرِ وَالتَّعْزِيمِ","145":"إِجَارَةُ الْحَمَّامِ وَالْقِرَاءَةُ فِيهِ وَأَحْكَامُ الْمُصْحَفِ","154":"الِادِّهَانُ وَالِاكْتِحَالُ وَالْوَشْمُ وَإِعْفَاءُ اللِّحَى وَنَحْوُهُ","161":"الْخِتَانُ وَتَخْمِيرُ الْأَوَانِي وَتَقْلِيمُ الْأَظْفَارِ وَتَشْمِيتُ الْعَاطِسِ","172":"الطِّبُّ وَمَا يَتَعَلَّقُ بِهِ وَإِنْذَارُ مَنْ لَاحَ بِهِ الشَّيْبُ","215":"عِيَادَةُ الْمَرِيضِ وَتَلْقِينُ الْمَيِّتِ وَزِيَارَةُ الْقُبُورِ","234":"الْحَثُّ عَلَى تَعَلُّمِ الْفَرَائِضِ وَحُكْمُ النَّظَرِ وَمَا يَتَعَلَّقُ بِهِ","261":"قَطْعُ الْبَوَاسِيرِ وَالْكَيُّ بِالنَّارِ وَالرُّقَى وَتَعْلِيقُ الْأَجْرَاسِ وَالتَّعَاوِيذِ وَالتَّدَاوِي بِالْمُحَرَّمِ وَحُكْمُ الْحَيَوَانَاتِ","288":"حُكْمُ الْأَكْلِ وَالْمَسَاجِدِ","309":"احْتِكَارُ الْقُوتِ وَإِكْرَامُ الضَّيْفِ وَالْجَارِ","346":"أَحْكَامُ الثِّمَارِ وَالْجَلَّالَةِ وَآدَابُ الشُّرْبِ وَالنَّوْمِ","379":"النَّذْرُ وَالشَّهَادَةُ وَحُكْمُ شَاهِدِ الزُّورِ وَشَارِبِ الْخَمْرِ","428":"الِاسْتِمْنَاءُ وَالْأَيْمَانُ وَقَذْفُ الْمُحْصَنَاتِ وَمَا يَتَرَتَّبُ عَلَيْهِ","462":"الْقَتْلُ بِغَيْرِ حَقٍّ وَمَا يَتَرَتَّبُ عَلَيْهِ وَالرُّجُوعُ إِلَى اللَّهِ تَعَالَى","478":"الصَّلَاةُ وَمَا يَتَعَلَّقُ بِهَا وَمَنْ جَحَدَهَا أَوْ جَحَدَ رُكْنًا مِنْ أَرْكَانِ الْإِسْلَامِ أَوْ جَحَدَ رُبُوبِيَّةَ اللَّهِ تَعَالَى أَوِ اسْتَهْزَأَ بِهِ أَوِ ادَّعَى النُّبُوَّةَ","504":"الْأَذَانُ وَصَلَاةُ النَّافِلَةِ وَقِرَاءَةُ الْقُرْآنِ وَصَلَاةُ الْجُمُعَةِ","545":"الزَّكَاةُ وَالصَّوْمُ وَمَا يَتَعَلَّقُ بِهِمَا مِنَ الْأَحْكَامِ","585":"الْحَجُّ وَالْجِهَادُ وَمَا يَتَعَلَّقُ بِهِمَا وَدَفْعُ الصَّائِلِ عَنِ الْأَهْلِ وَالْمَالِ","673":"الرِّبَا وَالْقَرْضُ وَالْوَقْفُ وَالْعِتْقُ","686":"اكْتِسَابُ الْحَلَالِ مِنَ الْمَالِ وَاجْتِنَابُ الْحَرَامِ وَذَمُّ الْبُخْلِ","708":"الْقَضَاءُ وَآدَابُ اللِّبَاسِ وَالنَّوْمِ وَلُبْسُ الصُّوفِ وَالْحَرِيرِ","758":"بَيْعُ الْعَصِيرِ وَالْعِنَبِ وَالشَّرَابِ وَآلَاتِ اللَّهْوِ وَمُعَامَلَةُ مَنْ خَالَطَ الْحَرَامَ","784":"فِيمَا يَجُوزُ لُبْسُهُ وَمَا يَحْرُمُ مِنَ الْفِضَّةِ وَالْحَرِيرِ وَالتَّخَتُّمِ وَحُكْمُ أَوَانِي الذَّهَبِ وَالْفِضَّةِ وَعُقُوقُ الْوَالِدَيْنِ وَإِعْطَاءُ الطَّرِيقِ حَقَّهُ","831":"النِّكَاحُ وَعِشْرَةُ الزَّوْجَةِ وَآدَابُ الْجِمَاعِ وَالْقَسْمُ","872":"فَرْضُ الْعَيْنِ وَفَرْضُ الْكِفَايَةِ وَوُجُوبُ النُّصْحِ لِلَّهِ وَلِرَسُولِهِ وَلِلْأُمَّةِ"}}],"sharh":false};
